INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地心", "is_correct": true, "explanation": "正确：地心就是地球的中心。"}, {"text": "地表", "is_correct": false, "explanation": "语义：地表是地球的表面，不是地球的中心，句子与定义矛盾。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋覆盖在地表上，不是地球的中心，句子与定义矛盾。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“就是”连接的两个成分应指同一事物，地图是画在纸上的东西，不能等同于地球的中心。"}], "explanations": {"地心": "正确：地心就是地球的中心。", "地表": "语义：地表是地球的表面，不是地球的中心，句子与定义矛盾。", "海洋": "语义：海洋覆盖在地表上，不是地球的中心，句子与定义矛盾。", "地图": "搭配：“就是”连接的两个成分应指同一事物，地图是画在纸上的东西，不能等同于地球的中心。"}, "sentence_index": 0, "correct_answer": "地心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们走在平坦的地心上。", "explanation": "这里应该用〈地面〉。地心在地球中心，人不能走在那里，走路的地方是地面。"}, {"text": "他每天都在地心里工作，上班很方便。", "explanation": "这里应该用〈地下〉。地下指地面以下的地方，可以有工作的房间；地心是地球的中心，人不能在那里工作。"}, {"text": "地心很厚，有好几公里。", "explanation": "这里应该用〈地壳〉。地心在地球中心，说地球外层有多厚要用〈地壳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地心", "is_correct": true, "explanation": "正确：老师在图上指着的是地心。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“在图上指着”的对象须是可以画出来的具体事物，友谊是抽象情感，句意不通。"}, {"text": "道理", "is_correct": false, "explanation": "搭配：道理是抽象的思想，不能在图上指出来，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“指着”的对象应是具体可指的事物，声音不能被指着。"}], "explanations": {"地心": "正确：老师在图上指着的是地心。", "友谊": "搭配：“在图上指着”的对象须是可以画出来的具体事物，友谊是抽象情感，句意不通。", "道理": "搭配：道理是抽象的思想，不能在图上指出来，句意不通。", "声音": "搭配：“指着”的对象应是具体可指的事物，声音不能被指着。"}, "sentence_index": 6, "correct_answer": "地心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的地心有很多矿。", "explanation": "这里应该用〈地下〉。地下指地面以下，可以有矿；地心是地球最中间的地方，不能用来说一座山下面的矿藏。"}, {"text": "沙漠的地心白天非常热。", "explanation": "这里应该用〈地表〉。地表有白天黑夜的温度变化；地心在地球中心，不能用来说沙漠的温度。"}, {"text": "这所学校的地心有一座大操场。", "explanation": "这里应该用〈中心〉。地心专指地球的中心，不能用来指学校的中心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家还没有到了地心。", "corrected_sentence": "科学家还没有到过地心。", "error_description": "错误：“没有”后面不能用“了”，写成“没有到了”。正确：“没有到过”，“过”表示从来没有过这种经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个模型里有一只地心。", "corrected_sentence": "这个模型里有一个地心。", "error_description": "错误：量词“只”用于动物，地心不能用“只”来数，写成“一只地心”。正确：“一个地心”，“个”可以用于大多数事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
