INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "域名是网站的名字，我们在网上输入它就能找到网站。", "primary_collocate": null, "pronunciation": "yù míng", "ipa": "y˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "请你输入这个域名。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "域名就是网站的名字。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给我的网站买一个域名。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个域名很好记。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上输入域名，就能找到网站。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的网站域名是什么？", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个域名太长了，我记不住。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的域名已经有人用了。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先选一个域名，再做网站。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新域名写在纸上了。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "网站的名字，在网上输入它就能找到网站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是可以输入的信息，句意不通。"}, {"text": "域名", "is_correct": true, "explanation": "正确。“输入这个域名”指在浏览器中输入网站的名称，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是可以输入的信息。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“输入”的对象是文字、数字或网址等信息，“米饭”不能搭配。"}], "explanations": {"太阳": "语义：太阳不是可以输入的信息，句意不通。", "域名": "正确。“输入这个域名”指在浏览器中输入网站的名称，与句意相符。", "冰箱": "语义：冰箱是家用电器，不是可以输入的信息。", "米饭": "搭配：“输入”的对象是文字、数字或网址等信息，“米饭”不能搭配。"}, "sentence_index": 0, "correct_answer": "域名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台域名。", "explanation": "这里不能用〈台〉。〈台〉用于机器、电器，域名应使用〈个〉，如“一个域名”。"}, {"text": "我每天早上吃一个域名。", "explanation": "“吃”的对象是食物，域名是网站的名称，不能吃。"}, {"text": "我家的域名在十号楼。", "explanation": "这里应该用〈地址〉。地址指实际的位置，域名是网络上网站的名称，不指地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不能用“太长了，我记不住”来形容。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：“太长”描述的是名称或文字的长度，不用于形容皮鞋。"}, {"text": "星期一", "is_correct": false, "explanation": "语义：星期一是日期，不是需要记住的名称。"}, {"text": "域名", "is_correct": true, "explanation": "正确。“域名”是需要记住的网站名称，过长时不容易记，与句意相符。"}], "explanations": {"西瓜": "语义：西瓜是水果，不能用“太长了，我记不住”来形容。", "皮鞋": "搭配：“太长”描述的是名称或文字的长度，不用于形容皮鞋。", "星期一": "语义：星期一是日期，不是需要记住的名称。", "域名": "正确。“域名”是需要记住的网站名称，过长时不容易记，与句意相符。"}, "sentence_index": 6, "correct_answer": "域名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个域名很高，我够不着。", "explanation": "“很高”描述实物的高度，域名是网站名称，没有高矮之分。"}, {"text": "我在域名里洗了个澡。", "explanation": "“在……里”要求具体场所，域名不是可以进入的地方，不能在里面洗澡。"}, {"text": "我们公司的域名下个月要结婚了。", "explanation": "“结婚”需要人作主体，域名不能结婚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你记住这本域名。", "corrected_sentence": "请你记住这个域名。", "error_description": "错误：“域名”的量词用错了。“本”用于书籍，“域名”应使用量词“个”，正确为“这个域名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把这首域名记清楚了。", "corrected_sentence": "我已经把这个域名记清楚了。", "error_description": "错误：“域名”的量词用错了。“首”用于诗词、歌曲，“域名”应使用量词“个”，正确为“这个域名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
