INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "互联网上用来标识和查找网站的名称，如网站地址中的名称部分。", "primary_collocate": null, "pronunciation": "yù míng", "ipa": "y˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "域名用来标识和查找网站。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网址中的“baidu.com”就是一个域名。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册域名需要先付一点钱。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有很多域名。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的域名能让用户更快找到网站。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上查了这个域名的主人。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个域名快到期了，要尽快续费。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "域名和网站地址有关系。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短域名更容易让人记住。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算换一个新域名。", "target_word": "域名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "互联网上用来标识和查找网站的名称，网址中的名称部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a720de0-ac80-4bf6-b407-5b4e7acb898f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能用来标识和查找网站。"}, {"text": "域名", "is_correct": true, "explanation": "正确。域名用于标识和查找网站，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，与标识和查找网站无关。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“标识和查找”的对象是网站或信息，“米饭”不能搭配。"}], "explanations": {"太阳": "语义：太阳是天体，不能用来标识和查找网站。", "域名": "正确。域名用于标识和查找网站，与句意相符。", "冰箱": "语义：冰箱是家用电器，与标识和查找网站无关。", "米饭": "搭配：“标识和查找”的对象是网站或信息，“米饭”不能搭配。"}, "sentence_index": 0, "correct_answer": "域名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的域名在三楼。", "explanation": "这里应该用〈地址〉。域名是网站的名称，不指实际的地点，不能说“在三楼”。"}, {"text": "这家公司有很多台域名。", "explanation": "这里不能用〈台〉。〈台〉用于机器、电器，域名应使用〈个〉。"}, {"text": "这家公司在域名里开会。", "explanation": "“在……里”要求具体场所，域名不是可以进入开会的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不会到期，也不需要续费。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：“到期”和“续费”用于证件、服务或网站等，不用于皮鞋。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，没有到期和续费的说法。"}, {"text": "域名", "is_correct": true, "explanation": "正确。域名到期后需要续费，与句意相符。"}], "explanations": {"西瓜": "语义：西瓜是水果，不会到期，也不需要续费。", "皮鞋": "搭配：“到期”和“续费”用于证件、服务或网站等，不用于皮鞋。", "窗户": "语义：窗户是建筑部件，没有到期和续费的说法。", "域名": "正确。域名到期后需要续费，与句意相符。"}, "sentence_index": 6, "correct_answer": "域名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板打算把新域名穿在身上。", "explanation": "“穿”用于衣物，域名是网站的名称，不能穿。"}, {"text": "老板打算给新域名发工资。", "explanation": "“发工资”的对象是员工，域名不能领工资。"}, {"text": "老板打算把新域名切成两半。", "explanation": "“切成两半”指对实物的切割，域名是名称，不能被切开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用这把域名查找网站。", "corrected_sentence": "我们用这个域名查找网站。", "error_description": "错误：“域名”的量词用错了。“把”用于有柄的器具，“域名”应使用量词“个”，正确为“这个域名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想注册一张新域名。", "corrected_sentence": "我想注册一个新域名。", "error_description": "错误：“域名”的量词用错了。“张”用于纸张、桌子等平面物，“域名”应使用量词“个”，正确为“一个新域名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af36401c-fbb8-480f-a629-3c4679ac126c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95827, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
