INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95827, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "多语言是有好几种话可以用。", "primary_collocate": null, "pronunciation": "duō yǔ yán", "ipa": "tuo˥ y˨˩˦ jɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这个软件是多语言的，可以选中文、英文或日文。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台手机的菜单是多语言的，你想用哪种都行。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的网站有多语言版本，法国客人也能看懂。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典是多语言的，一个词有五种语言的解释。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的牌子都是多语言的，外国人也不怕找不到路。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多语言字幕可以换，英文和韩文都有。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了一个多语言的网页，各国朋友都能用。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏支持多语言，我可以把它调成西班牙语。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的电视是多语言的，我选了中文节目。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份多语言说明书有八种文字，我找到了中文那页。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多语言版", "label": "复合词"}], "register": "中性", "sense_fingerprint": "软件、网站、词典等可以使用好几种语言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '981d0e3c-e2be-4751-af4a-301b1d651d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多语言", "is_correct": true, "explanation": "句中说软件可以选中文、英文或日文，正是能使用多种语言，所以用“多语言”。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”说只有一种，与“可以选中文、英文或日文”矛盾。"}, {"text": "英文", "is_correct": false, "explanation": "语义：“英文的”只限英语，与句中列出的中文、日文等选项矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容软件。"}], "explanations": {"多语言": "句中说软件可以选中文、英文或日文，正是能使用多种语言，所以用“多语言”。", "单一": "语义：“单一”说只有一种，与“可以选中文、英文或日文”矛盾。", "英文": "语义：“英文的”只限英语，与句中列出的中文、日文等选项矛盾。", "甜": "搭配：“甜”形容味道，不能用来形容软件。"}, "sentence_index": 0, "correct_answer": "多语言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面是多语言的，味道很鲜。", "explanation": "这里应该用〈鲜美〉。多语言指能使用多种语言的事物，不能形容食物；食物味道好要说鲜美。"}, {"text": "这幅油画是多语言的，颜色很亮。", "explanation": "这里应该用〈多彩〉。多语言指能使用多种语言，油画的颜色不涉及语言，应说多彩。"}, {"text": "他的兴趣是多语言的，喜欢画画、唱歌和游泳。", "explanation": "这里应该用〈多样〉。多语言不能形容兴趣，兴趣种类多要说多样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多语言", "is_correct": true, "explanation": "“各国朋友都能用”说明网页要支持多种语言，所以用“多语言”。"}, {"text": "日文", "is_correct": false, "explanation": "语义：“日文的网页”只用日语，与“各国朋友都能用”的意思矛盾。"}, {"text": "手写", "is_correct": false, "explanation": "搭配：“手写”说的是书写方式，不能用来形容网页。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容物体的质地，不用来形容网页。"}], "explanations": {"多语言": "“各国朋友都能用”说明网页要支持多种语言，所以用“多语言”。", "日文": "语义：“日文的网页”只用日语，与“各国朋友都能用”的意思矛盾。", "手写": "搭配：“手写”说的是书写方式，不能用来形容网页。", "硬": "搭配：“硬”形容物体的质地，不用来形容网页。"}, "sentence_index": 6, "correct_answer": "多语言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这周的作业是多语言的，我每天都要写到很晚。", "explanation": "这里应该用〈繁多〉。多语言用于能使用几种语言的事物，作业数量多要说繁多，不能说多语言。"}, {"text": "这家超市的菜是多语言的，什么都能买到。", "explanation": "这里应该用〈齐全〉。种类全要说齐全，多语言不能形容食物。"}, {"text": "这盘菜的口味是多语言的，我很喜欢。", "explanation": "这里应该用〈丰富〉。口味种类多要说丰富，多语言不用于形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个网站是多语言，可以用中文和英文看。", "corrected_sentence": "这个网站是多语言的，可以用中文和英文看。", "error_description": "“多语言”作表语时，后面要带“的”，应说“是多语言的”，不能省去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做了一个多语言地网站，各国朋友都能用。", "corrected_sentence": "他做了一个多语言的网站，各国朋友都能用。", "error_description": "“的”误写为“地”：“多语言”修饰“网站”时要用“的”，“地”通常用来修饰动词，应说“一个多语言的网站”，不能说“一个多语言地网站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
