INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95828, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95828, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "包含或使用多种语言的。", "primary_collocate": null, "pronunciation": "duō yǔ yán", "ipa": "tuo˥ y˨˩˦ jɛn˧˥", "syllable_count": 3, "sentences": [{"text": "新加坡是一个多语言的国家，人们常说几种话。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在多语言的家庭里长大，会说三种话。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市是多语言的，街上能听到很多种话。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瑞士有多语言的环境，学校里要学好几种语言。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说有多语言的对话，读起来很有意思。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司是多语言的团队，同事来自八个国家。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个多语言的班里，同学们说着不同的话。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一首多语言的歌，里面有中文和法文。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多语言社会里，路牌上常常有两三种文字。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的对白是多语言的，一半英文一半中文。", "target_word": "多语言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多语言版", "label": "复合词"}], "register": "中性", "sense_fingerprint": "国家、社会、环境、作品中包含或同时使用多种语言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '981d0e3c-e2be-4751-af4a-301b1d651d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多语言", "is_correct": true, "explanation": "“人们常说几种话”说明国家里有多种语言，所以用“多语言”。"}, {"text": "单语", "is_correct": false, "explanation": "语义：“单语”指只用一种语言，与“人们常说几种话”矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容国家。"}, {"text": "生气", "is_correct": false, "explanation": "搭配：“生气”形容人的情绪，不能用来形容国家。"}], "explanations": {"多语言": "“人们常说几种话”说明国家里有多种语言，所以用“多语言”。", "单语": "语义：“单语”指只用一种语言，与“人们常说几种话”矛盾。", "甜": "搭配：“甜”形容味道，不能用来形容国家。", "生气": "搭配：“生气”形容人的情绪，不能用来形容国家。"}, "sentence_index": 0, "correct_answer": "多语言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子是多语言的，住五个人也不挤。", "explanation": "这里应该用〈宽敞〉。多语言形容包含或使用几种语言的事物，房子空间大要说宽敞。"}, {"text": "这棵树是多语言的，长得很高大。", "explanation": "这里应该用〈高大〉。多语言不用于形容树的体型，树长得大要说高大。"}, {"text": "这片湖是多语言的，水很清。", "explanation": "这里应该用〈清澈〉。多语言指包含或使用多种语言，不能形容湖水；湖水干净透明要说清澈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多语言", "is_correct": true, "explanation": "“同学们说着不同的话”说明班里有多种语言，所以用“多语言”。"}, {"text": "中文", "is_correct": false, "explanation": "语义：“中文的班”只用中文，与“同学们说着不同的话”矛盾。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”指没有人，与“同学们说着不同的话”矛盾。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能用来形容班。"}], "explanations": {"多语言": "“同学们说着不同的话”说明班里有多种语言，所以用“多语言”。", "中文": "语义：“中文的班”只用中文，与“同学们说着不同的话”矛盾。", "空": "语义：“空”指没有人，与“同学们说着不同的话”矛盾。", "咸": "搭配：“咸”形容味道，不能用来形容班。"}, "sentence_index": 6, "correct_answer": "多语言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这束花是多语言的，颜色很鲜艳。", "explanation": "这里应该用〈鲜艳〉。多语言指能使用多种语言，花的颜色亮丽要说鲜艳。"}, {"text": "今天的天气是多语言的，很凉爽。", "explanation": "这里应该用〈凉爽〉。多语言不能形容天气，天气舒适要说凉爽。"}, {"text": "这条河的水是多语言的，能看见河底的石头。", "explanation": "这里应该用〈清澈〉。多语言指包含或使用多种语言，不能形容河水；水干净透明要说清澈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家是多语言地，人们常说几种话。", "corrected_sentence": "这个国家是多语言的，人们常说几种话。", "error_description": "“的”误写为“地”：“多语言”作表语或定语时要用“的”，“地”通常用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写了一首多语言地歌，里面有中文和西班牙文。", "corrected_sentence": "她写了一首多语言的歌，里面有中文和西班牙文。", "error_description": "“的”误写为“地”：“多语言”修饰“歌”时要用“的”，不能用“地”，应说“一首多语言的歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
