INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95829, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大指是手上最粗最短的那个手指。", "primary_collocate": null, "pronunciation": "dà zhǐ", "ipa": "ta˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大指是手上最短的手指。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝爱吸自己的大指。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大指和食指可以夹住小东西。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的大指有一道长长的伤口。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用大指和食指拿笔。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只手套的大指部分破了。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她竖起大指，表示很满意。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我的大指冻红了。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用大指擦掉了脸上的水。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹琴时，大指要放轻松。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "手上最粗最短的那个手指", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95829, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大指", "is_correct": true, "explanation": "大指：手上最粗最短的那个手指，即大拇指。"}, {"text": "大志", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是远大的志向。"}, {"text": "大使", "is_correct": false, "explanation": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。"}, {"text": "大致", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大概、大体上。"}], "explanations": {"大指": "大指：手上最粗最短的那个手指，即大拇指。", "大志": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是远大的志向。", "大使": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。", "大致": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大概、大体上。"}, "sentence_index": null, "correct_answer": "大指"}, "level_3": {"options": [{"text": "大指", "is_correct": true, "explanation": "语义：大指即大拇指，是手上最粗最短的手指，符合句意。"}, {"text": "中指", "is_correct": false, "explanation": "语义：中指是手指中最长的一个，与句中的“最短”正相反。"}, {"text": "食指", "is_correct": false, "explanation": "语义：食指并不是手上最短的手指，与句中的描述不符。"}, {"text": "手掌", "is_correct": false, "explanation": "搭配：“手掌”不是手指，不能与“手上最短的手指”构成比较。"}], "explanations": {"大指": "语义：大指即大拇指，是手上最粗最短的手指，符合句意。", "中指": "语义：中指是手指中最长的一个，与句中的“最短”正相反。", "食指": "语义：食指并不是手上最短的手指，与句中的描述不符。", "手掌": "搭配：“手掌”不是手指，不能与“手上最短的手指”构成比较。"}, "sentence_index": 0, "correct_answer": "大指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的大指扭伤了，走路很疼。", "explanation": "这里应该用〈大脚趾〉。大指指手上的拇指，脚上的拇趾要说大脚趾。"}, {"text": "他的右手有一只大指受伤了。", "explanation": "这里应该用〈根〉。手指的量词是“根”，“只”用于动物或成对的东西，说“一只大指”不对。"}, {"text": "他握紧大指，朝我打了一拳。", "explanation": "这里应该用〈拳头〉。大指只是一根手指，不能单独握成拳头打人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95829, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大指", "is_correct": true, "explanation": "大指：手上最粗最短的那个手指，即大拇指。"}, {"text": "大齿", "is_correct": false, "explanation": "ch 与 zh 声母不同，声调相同，意思是大的牙齿或大齿轮。"}, {"text": "大使", "is_correct": false, "explanation": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。"}, {"text": "大智", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大智慧。"}], "explanations": {"大指": "大指：手上最粗最短的那个手指，即大拇指。", "大齿": "ch 与 zh 声母不同，声调相同，意思是大的牙齿或大齿轮。", "大使": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。", "大智": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大智慧。"}, "sentence_index": null, "correct_answer": "大指"}, "level_3": {"options": [{"text": "大指", "is_correct": true, "explanation": "语义：大指是手指，竖起大指表示满意，符合句意。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚向上不是表示满意的手势，与句意不符。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：尾巴不属于人的手，无法“向上”表示满意。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”不能作为“向上”这一手势的对象，搭配不当。"}], "explanations": {"大指": "语义：大指是手指，竖起大指表示满意，符合句意。", "脚": "语义：脚向上不是表示满意的手势，与句意不符。", "尾巴": "语义：尾巴不属于人的手，无法“向上”表示满意。", "眼睛": "搭配：“眼睛”不能作为“向上”这一手势的对象，搭配不当。"}, "sentence_index": 6, "correct_answer": "大指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把刀的大指很锋利，切菜很方便。", "explanation": "〈大指〉指人手上的拇指，不指刀上的部件，这里词义用错了。"}, {"text": "这根香蕉的大指很甜。", "explanation": "这里应该用〈果肉〉。大指只指人手上的拇指，不能用来指香蕉的部分，词义用错了。"}, {"text": "他把大指剪得很短。", "explanation": "这里应该用〈指甲〉。指甲才能剪，大指是手指，不能剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用一只大指按住了纸角。", "corrected_sentence": "她用一根大指按住了纸角。", "error_description": "量词错误：手指应用“根”计量。“一只大指”应改为“一根大指”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天我的大指冻发红。", "corrected_sentence": "冬天我的大指冻得发红。", "error_description": "补语错误：“冻”后应用“得”引出补语“发红”，应说“冻得发红”，不能说“冻发红”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
