INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大拇指，手指中最粗最短的一个。", "primary_collocate": null, "pronunciation": "dà zhǐ", "ipa": "ta˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大指是手上最粗的手指。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出大指，说我们做得好。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的大指受伤了，不能写字。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大指比别的手指短一些。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用大指按住了纸。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戴手套时，大指要伸进单独的指套里。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的大指上贴着一块布。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用大指在这里按一下。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了孩子的大指。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五个手指中，大指最粗。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大拇指，手指中最粗最短的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大指", "is_correct": true, "explanation": "大指：手指中最粗最短的一个，即大拇指。"}, {"text": "大志", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是远大的志向。"}, {"text": "大使", "is_correct": false, "explanation": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。"}, {"text": "大致", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大概、大体上。"}], "explanations": {"大指": "大指：手指中最粗最短的一个，即大拇指。", "大志": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是远大的志向。", "大使": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。", "大致": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大概、大体上。"}, "sentence_index": null, "correct_answer": "大指"}, "level_3": {"options": [{"text": "大指", "is_correct": true, "explanation": "语义：大指即大拇指，正是手上最粗的手指，符合句意。"}, {"text": "小指", "is_correct": false, "explanation": "语义：小指是手指中最细的一个，与句中的“最粗”正相反。"}, {"text": "食指", "is_correct": false, "explanation": "语义：食指在拇指旁边，但并不是手上最粗的手指，与句意不符。"}, {"text": "手腕", "is_correct": false, "explanation": "搭配：“手腕”不是手指，无法与“手上最粗的手指”构成同类比较。"}], "explanations": {"大指": "语义：大指即大拇指，正是手上最粗的手指，符合句意。", "小指": "语义：小指是手指中最细的一个，与句中的“最粗”正相反。", "食指": "语义：食指在拇指旁边，但并不是手上最粗的手指，与句意不符。", "手腕": "搭配：“手腕”不是手指，无法与“手上最粗的手指”构成同类比较。"}, "sentence_index": 0, "correct_answer": "大指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的大指扭伤了，走路很疼。", "explanation": "这里应该用〈大脚趾〉。大指指手上的拇指，脚上的拇趾要说大脚趾。"}, {"text": "他的右手有一只大指受伤了。", "explanation": "这里应该用〈根〉。手指的量词是“根”，“只”用于动物或成对的东西，说“一只大指”不对。"}, {"text": "他把大指关掉了，屋里就暗了。", "explanation": "〈大指〉只指手上的拇指，不能当作开关。这里把它当成电器来用，不符合词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大指", "is_correct": true, "explanation": "大指：手指中最粗最短的一个，即大拇指。"}, {"text": "大齿", "is_correct": false, "explanation": "ch 与 zh 声母不同，声调相同，意思是大的牙齿或大齿轮。"}, {"text": "大智", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大智慧。"}, {"text": "大使", "is_correct": false, "explanation": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。"}], "explanations": {"大指": "大指：手指中最粗最短的一个，即大拇指。", "大齿": "ch 与 zh 声母不同，声调相同，意思是大的牙齿或大齿轮。", "大智": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是大智慧。", "大使": "sh 与 zh 声母不同，声调相同，意思是派驻外国的代表。"}, "sentence_index": null, "correct_answer": "大指"}, "level_3": {"options": [{"text": "大指", "is_correct": true, "explanation": "语义：大指是手指，可以贴上一块布，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称谓，不是实物，无法贴上一块布。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的投影，无法贴上一块布。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“贴”需要有形的载体，“声音”是听觉对象，与“贴着一块布”搭配不当。"}], "explanations": {"大指": "语义：大指是手指，可以贴上一块布，符合句意。", "名字": "语义：名字是称谓，不是实物，无法贴上一块布。", "影子": "语义：影子是光线形成的投影，无法贴上一块布。", "声音": "搭配：“贴”需要有形的载体，“声音”是听觉对象，与“贴着一块布”搭配不当。"}, "sentence_index": 6, "correct_answer": "大指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他握紧大指，朝我打了一拳。", "explanation": "这里应该用〈拳头〉。大指只是一根手指，不能单独握成拳头打人。"}, {"text": "这把刀的大指很锋利，切菜很方便。", "explanation": "〈大指〉指人手上的拇指，不指刀上的部件，这里词义用错了。"}, {"text": "这块蛋糕的大指很甜。", "explanation": "这里应该用〈边角〉。大指只指人手上的拇指，不能用来指蛋糕的部分，词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他竖起一只大指，夸我做得好。", "corrected_sentence": "他竖起一根大指，夸我做得好。", "error_description": "量词错误：手指应用“根”计量。“一只大指”应改为“一根大指”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的大指疼厉害。", "corrected_sentence": "他的大指疼得厉害。", "error_description": "补语错误：“疼”后应用“得”引出补语“厉害”，应说“疼得厉害”，不能说“疼厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
