INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95831, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "差不多都是，大部分都是。", "primary_collocate": null, "pronunciation": "dà dōu", "ipa": "ta˥˩ tou˥", "syllable_count": 2, "sentences": [{"text": "我们班的同学大都是北方人。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上的店大都是卖吃的。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来开会的人大都是老人，只有两个年轻人。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他书架上的书大都是小说。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的房子大都是红色的。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友大都住在城东。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的鸟大都是从南方来的。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的衣服大都很便宜。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的信大都很短。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的人大都在跳舞。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "差不多都是，大部分都是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大都", "is_correct": true, "explanation": "正确：“大都”表示大多数，与“同学大都是北方人”相符。"}, {"text": "常常", "is_correct": false, "explanation": "搭配：“常常”表示频率，一般修饰动作，不直接修饰“是”。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示少数情况，与“大多数同学是北方人”矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻，与“是北方人”这种身份判断不搭。"}], "explanations": {"大都": "正确：“大都”表示大多数，与“同学大都是北方人”相符。", "常常": "搭配：“常常”表示频率，一般修饰动作，不直接修饰“是”。", "偶尔": "语义：“偶尔”表示少数情况，与“大多数同学是北方人”矛盾。", "马上": "语义：“马上”表示即刻，与“是北方人”这种身份判断不搭。"}, "sentence_index": 0, "correct_answer": "大都"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个同学大都带了书。", "explanation": "这里应该用〈都〉。“每个”指全体，与“大都”的大多数意思矛盾，指全体应说“每个同学都带了书”。"}, {"text": "饭菜大都吃光了，一点也没剩。", "explanation": "这里应该用〈全部〉。“大都”表示大部分，与“一点也没剩”的全部意思矛盾。"}, {"text": "学校规定，全体学生大都穿校服。", "explanation": "这里应该用〈一律〉。“一律”表示无例外，与“全体”搭配；“大都”表示多数，与“全体”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大都", "is_correct": true, "explanation": "正确：“大都”表示大多数，与“鸟大都是从南方来的”相符。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”修饰即时的动作，不修饰“是……的”这种判断。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“是从南方来的”这一既定事实不符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，修饰形容词或心理动词，不能修饰“是从南方来的”这种判断。"}], "explanations": {"大都": "正确：“大都”表示大多数，与“鸟大都是从南方来的”相符。", "立刻": "搭配：“立刻”修饰即时的动作，不修饰“是……的”这种判断。", "忽然": "语义：“忽然”表示突然发生，与“是从南方来的”这一既定事实不符。", "很": "语法：“很”是程度副词，修饰形容词或心理动词，不能修饰“是从南方来的”这种判断。"}, "sentence_index": 6, "correct_answer": "大都"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些书大都搬走了，屋里一本也不剩。", "explanation": "这里应该用〈全都〉。“大都”表示大部分，与“一本也不剩”的全部意思矛盾。"}, {"text": "这次考试的学生大都及格了，没有一个不及格的。", "explanation": "这里应该用〈都〉。“大都”表示大多数，与“没有一个不及格的”的全部意思矛盾，指全部应说“都及格了”。"}, {"text": "我们的作业大都交了，老师说一份也不缺。", "explanation": "这里应该用〈都〉。“大都”表示大部分，与“一份也不缺”的全部意思矛盾，应说“作业都交了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区的住户是大都是老人。", "corrected_sentence": "这个小区的住户大都是老人。", "error_description": "错误：“是大都是”不通。“大都”是副词，应放在主语“住户”之后、谓语“是老人”之前，说“住户大都是老人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校里的老师大都都是本地人。", "corrected_sentence": "学校里的老师大都是本地人。", "error_description": "错误：“大都”本身已表示大多数，后面不能再加“都”，应说“大都是本地人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
