INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95832, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大多数；多半。", "primary_collocate": null, "pronunciation": "dà dōu", "ipa": "ta˥˩ tou˥", "syllable_count": 2, "sentences": [{"text": "班上的学生大都喜欢踢球。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这儿的人大都认识我。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的树叶大都变黄了。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买的水果大都是苹果。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的同事大都比他年轻。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题大都不难。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的人大都是学生。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上的人大都没说话。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的菜大都有点辣。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过的城市大都很干净。", "target_word": "大都", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大多数，多半", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大都", "is_correct": true, "explanation": "正确：“大都”表示大多数，与“学生大都喜欢踢球”相符。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”修饰即时的动作，不修饰“喜欢”这类心理状态。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与“喜欢踢球”这种持续的状态不搭。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同，与“大多数学生喜欢”的句意不符。"}], "explanations": {"大都": "正确：“大都”表示大多数，与“学生大都喜欢踢球”相符。", "马上": "搭配：“马上”修饰即时的动作，不修饰“喜欢”这类心理状态。", "忽然": "语义：“忽然”表示突然，与“喜欢踢球”这种持续的状态不搭。", "一起": "语义：“一起”表示共同，与“大多数学生喜欢”的句意不符。"}, "sentence_index": 0, "correct_answer": "大都"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全体职工大都要参加。", "explanation": "这里应该用〈都〉。“全体”指所有人，与“大都”的大多数意思矛盾，应说“全体职工都要参加”。"}, {"text": "那些书大都被卖掉了，一本也没留下。", "explanation": "这里应该用〈全部〉。“大都”表示大多数，与“一本也没留下”的全部意思矛盾。"}, {"text": "所有的门大都锁上了。", "explanation": "这里应该用〈一律〉。“所有”指全部，与“大都”的大多数意思矛盾；全部无例外应说“一律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大都", "is_correct": true, "explanation": "正确：“大都”表示大多数，与“参加比赛的人大都是学生”相符。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”修饰即时的动作，不修饰“是学生”这样的判断。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生而未发生，与“是学生”的判断不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示少数情况，与“大多数参赛者是学生”矛盾。"}], "explanations": {"大都": "正确：“大都”表示大多数，与“参加比赛的人大都是学生”相符。", "立即": "搭配：“立即”修饰即时的动作，不修饰“是学生”这样的判断。", "差点": "语义：“差点”表示几乎发生而未发生，与“是学生”的判断不符。", "偶尔": "语义：“偶尔”表示少数情况，与“大多数参赛者是学生”矛盾。"}, "sentence_index": 6, "correct_answer": "大都"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批梨大都带回家了，一个也没剩下。", "explanation": "这里应该用〈全都〉。“大都”表示大部分，与“一个也没剩下”的全部意思矛盾。"}, {"text": "全班同学大都交了作业，没有一个例外。", "explanation": "这里应该用〈全都〉。“大都”表示大多数，与“没有一个例外”的全部意思矛盾，指全部应说“全都”。"}, {"text": "我的朋友大都到了，没有一个缺席。", "explanation": "这里应该用〈都〉。“大都”表示大多数，与“没有一个缺席”的全部意思矛盾，应说“朋友都到了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社区的老人是大都喜欢散步。", "corrected_sentence": "这个社区的老人大都喜欢散步。", "error_description": "错误：副词“大都”不能用“是”引出，“是大都喜欢”不通。应把“大都”放在主语“老人”之后、谓语之前，说“老人大都喜欢散步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
