INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "妥协是两个人想法不同，各让一点，不再吵了。", "primary_collocate": null, "pronunciation": "tuǒ xié", "ipa": "tʰwo˨˩ ɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他们吵了很久，最后都妥协了。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你让一点，我也让一点，我们妥协吧。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人想法不同，可是谁也不妥协。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈和我互相妥协，就不吵了。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不吵架，他决定向朋友妥协。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都妥协了，所以不再吵了。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不喜欢妥协，每次都要听他的。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李终于妥协了。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们妥协以后，又成了好朋友。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻俩想法不同，有时要互相妥协。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妥协了", "label": "完成体"}, {"form": "妥协过", "label": "经历体"}, {"form": "不妥协", "label": "否定式"}], "register": "中性", "sense_fingerprint": "想法不同的人各让一步不再争吵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95833, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妥协", "is_correct": true, "explanation": "正确：吵了很久之后，双方各让一步，最后都妥协了。"}, {"text": "开始", "is_correct": false, "explanation": "语义：“最后”指争吵结束时的结果，“开始”与“最后”矛盾，句意不通。"}, {"text": "戴", "is_correct": false, "explanation": "配价：“戴”需要带具体的宾语，“都……了”后面没有宾语，句子不成立。"}, {"text": "咬", "is_correct": false, "explanation": "配价：“咬”需要带具体的宾语，“都……了”后面没有宾语，句子不成立。"}], "explanations": {"妥协": "正确：吵了很久之后，双方各让一步，最后都妥协了。", "开始": "语义：“最后”指争吵结束时的结果，“开始”与“最后”矛盾，句意不通。", "戴": "配价：“戴”需要带具体的宾语，“都……了”后面没有宾语，句子不成立。", "咬": "配价：“咬”需要带具体的宾语，“都……了”后面没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "妥协"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个人想法完全一样，所以他们妥协了。", "explanation": "这里应该用〈同意〉。妥协要求双方想法不同、各让一步；想法一样时应该说“同意”，不需要让步。"}, {"text": "大家的看法相同，没有任何分歧，却突然妥协了。", "explanation": "这里应该用〈一致〉。妥协需要双方有分歧；看法没有分歧时应该说“达成一致”，不说“妥协”。"}, {"text": "两人并肩工作，一起完成了任务，最后妥协了。", "explanation": "这里应该用〈合作〉。妥协是双方各让一步、化解分歧，不是共同做事；共同完成任务应该说“合作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妥协", "is_correct": true, "explanation": "正确：爸爸不喜欢妥协，所以每次都要听他的。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”与“每次都要听他的”的听从关系无关，句意不通。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：“旅行”与句中的家庭听从关系无关，句意不通。"}, {"text": "做主", "is_correct": false, "explanation": "语义：“做主”与“每次都要听他的”的主导关系相冲突，句意不通。"}], "explanations": {"妥协": "正确：爸爸不喜欢妥协，所以每次都要听他的。", "表扬": "语义：“表扬”与“每次都要听他的”的听从关系无关，句意不通。", "旅行": "语义：“旅行”与句中的家庭听从关系无关，句意不通。", "做主": "语义：“做主”与“每次都要听他的”的主导关系相冲突，句意不通。"}, "sentence_index": 6, "correct_answer": "妥协"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一局他输得很惨，却马上妥协了，不再争辩。", "explanation": "这里应该用〈认输〉。妥协要双方各让一步；输了比赛、承认失败应该说“认输”。"}, {"text": "孩子们玩得很开心，没有人吵架，最后却都妥协了。", "explanation": "这里应该用〈和睦〉。没有争执时大家只是相处融洽，不存在各让一步，不能说妥协。"}, {"text": "他一个人在家，没有人反对他，却仍然妥协了。", "explanation": "这里应该用〈坚持〉。妥协说的是让步、达成协议；没有人反对、只是坚持自己时，要说“坚持”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司以前没有妥协了。", "corrected_sentence": "两家公司以前没有妥协过。", "error_description": "错误：“没有”后面不能用“了”，写成“没有妥协了”。正确：“没有妥协过”，“过”表示从来没有过这种经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们最后被妥协了。", "corrected_sentence": "他们最后妥协了。", "error_description": "错误：“妥协”是不及物动词，不能用“被”构成被动句，写成“被妥协了”。正确：“他们最后妥协了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
