INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95834, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在争执中双方各让一步，或一方放弃部分主张而达成协议。", "primary_collocate": null, "pronunciation": "tuǒ xié", "ipa": "tʰwo˨˩ ɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "双方经过谈判，终于妥协了。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司向工人妥协，同意加工资。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在价钱上妥协，达成了协议。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈了三天，两国都妥协了一些。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖家不肯妥协，生意没有谈成。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了签合同，我们必须妥协。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃一部分要求，向对方妥协。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方各自妥协，才达成了协议。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不能再妥协了。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板最后妥协，答应了我们的条件。", "target_word": "妥协", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "妥协了", "label": "完成体"}, {"form": "妥协过", "label": "经历体"}, {"form": "不妥协", "label": "否定式"}], "register": "中性", "sense_fingerprint": "争执中让步以达成协议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妥协", "is_correct": true, "explanation": "正确：双方经过谈判，终于在争执中各让一步，妥协了。"}, {"text": "吃", "is_correct": false, "explanation": "语义：谈判之后说“吃”，与谈判达成让步的语境无关，句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：谈判的结果不能是“洗澡”，与句中的谈判语境不符。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要带具体的宾语，“终于……了”后面没有宾语，句子不成立。"}], "explanations": {"妥协": "正确：双方经过谈判，终于在争执中各让一步，妥协了。", "吃": "语义：谈判之后说“吃”，与谈判达成让步的语境无关，句意不通。", "洗澡": "语义：谈判的结果不能是“洗澡”，与句中的谈判语境不符。", "扔": "配价：“扔”需要带具体的宾语，“终于……了”后面没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "妥协"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们没有任何争议，却一起妥协了。", "explanation": "这里应该用〈一致〉。妥协需要双方有争议、各让一步；没有争议时应该说“达成一致”，不说“妥协”。"}, {"text": "两位同事一起编写程序，分工明确，配合得很默契，两人都妥协了。", "explanation": "这里应该用〈合作〉。妥协需要双方有分歧、各让一步；分工明确、配合默契时没有让步，不能说妥协。"}, {"text": "这次比赛没有分出胜负，两队却都妥协了。", "explanation": "这里应该用〈对抗〉。妥协是双方让步、达成协议；比赛中的双方处于对抗，不说妥协。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妥协", "is_correct": true, "explanation": "正确：他放弃一部分要求，向对方妥协。"}, {"text": "坚持", "is_correct": false, "explanation": "语义：“放弃一部分要求”与“坚持”相矛盾，句意不通。"}, {"text": "进攻", "is_correct": false, "explanation": "语义：放弃要求之后向对方进攻，与句中的让步语境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“向对方睡觉”不成话，与放弃要求、让步的语境不符。"}], "explanations": {"妥协": "正确：他放弃一部分要求，向对方妥协。", "坚持": "语义：“放弃一部分要求”与“坚持”相矛盾，句意不通。", "进攻": "语义：放弃要求之后向对方进攻，与句中的让步语境不符。", "睡觉": "语义：“向对方睡觉”不成话，与放弃要求、让步的语境不符。"}, "sentence_index": 6, "correct_answer": "妥协"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一场比赛他输得很惨，赛后马上妥协了。", "explanation": "这里应该用〈认输〉。妥协是双方各让一步或一方放弃部分主张达成协议；输了比赛、承认失败应该说“认输”。"}, {"text": "两位同事一起工作，从没有分歧，却突然妥协了。", "explanation": "这里应该用〈默契〉。妥协是有分歧后各让一步；彼此配合默契时没有让步，不能说妥协。"}, {"text": "这件事他没有任何意见，却还是要妥协。", "explanation": "这里应该用〈同意〉。没有分歧、没有意见时只需表示同意，不需要让步，不能说妥协。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工会和公司都没有妥协了。", "corrected_sentence": "工会和公司都没有妥协过。", "error_description": "错误：“没有”后面不能用“了”，写成“没有妥协了”。正确：“没有妥协过”，“过”表示从来没有过这种经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "双方最后都被妥协了。", "corrected_sentence": "双方最后都妥协了。", "error_description": "错误：“妥协”是不及物动词，不能用“被”构成被动句，写成“被妥协了”。正确：“双方最后都妥协了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
