INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95835, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "存储是把东西放起来，以后还能再拿出来用。", "primary_collocate": null, "pronunciation": "cún chǔ", "ipa": "tsʰwən˧˥ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "冬天，农民把粮食存储在地下。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间用来存储旧家具。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把水存储起来，干旱时用。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把苹果存储在凉快的地方。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大仓库能存储很多米。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天他存储了很多木柴，冬天用。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里存储着村里的粮食。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把药存储在冰箱里，可以放久一点。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了过冬，小动物存储食物。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果存储好以后，明年还能吃。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存储了", "label": "完成体"}, {"form": "存储过", "label": "经历体"}, {"form": "存储着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "把物品收存起来留待以后使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存储", "is_correct": true, "explanation": "正确：“存储”表示把粮食放起来备用，与“冬天”“地下”相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”指栽培植物，不用于把粮食放在地下保存。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：“烘烤”需要加热，与把粮食放在地下的意思不符。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”是把物体弄干净，不能表示把粮食放在地下。"}], "explanations": {"存储": "正确：“存储”表示把粮食放起来备用，与“冬天”“地下”相符。", "种植": "搭配：“种植”指栽培植物，不用于把粮食放在地下保存。", "烘烤": "语义：“烘烤”需要加热，与把粮食放在地下的意思不符。", "清洗": "语义：“清洗”是把物体弄干净，不能表示把粮食放在地下。"}, "sentence_index": 0, "correct_answer": "存储"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天都把地板存储一遍。", "explanation": "这里应该用〈擦〉。把地板弄干净要说〈擦〉；“存储”指把东西收存起来备用。"}, {"text": "他把自己存储在屋里。", "explanation": "这里应该用〈藏〉。人躲在屋里要说〈藏〉；“存储”的对象是物品或数据，不能用于人。"}, {"text": "院子里存储着一大片玫瑰。", "explanation": "这里应该用〈栽种〉。花要用〈栽种〉或〈种植〉；“存储”指把物品或数据收存起来备用，不指种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存储", "is_correct": true, "explanation": "正确：“存储”表示把粮食收存在山洞里，与“山洞里”和“粮食”相符。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”的对象是人，不能招待粮食。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”的主体须是人，山洞不能批评。"}, {"text": "讲述", "is_correct": false, "explanation": "语义：“讲述”需要讲话的人和讲述的内容，粮食不能被讲述。"}], "explanations": {"存储": "正确：“存储”表示把粮食收存在山洞里，与“山洞里”和“粮食”相符。", "招待": "搭配：“招待”的对象是人，不能招待粮食。", "批评": "语义：“批评”的主体须是人，山洞不能批评。", "讲述": "语义：“讲述”需要讲话的人和讲述的内容，粮食不能被讲述。"}, "sentence_index": 6, "correct_answer": "存储"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上存储着一幅山水画。", "explanation": "这里应该用〈悬挂〉。挂在墙上要说〈悬挂〉；“存储”指收存备用，不指挂在墙上展示。"}, {"text": "他每天早上给花存储一次水。", "explanation": "这里应该用〈浇〉。给植物供水要说〈浇〉；“存储”指把东西收存起来备用。"}, {"text": "孩子被存储在奶奶家。", "explanation": "这里应该用〈寄养〉。把孩子托给别人照顾要说〈寄养〉；“存储”只用于物品或数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里存储了着全村的种子。", "corrected_sentence": "仓库里存储着全村的种子。", "error_description": "错误形式：“了”和“着”同时用在“存储”后。“着”表示状态持续，不能再加“了”；正确形式：“存储着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把雨水存储起去，夏天用。", "corrected_sentence": "他们把雨水存储起来，夏天用。", "error_description": "错误形式：“存储起去”，结果补语方向用错。表示物品收存到一起，应用“来”；正确形式：“存储起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
