INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95836, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把数据、文件等保存在电子设备里备用。", "primary_collocate": null, "pronunciation": "cún chǔ", "ipa": "tsʰwən˧˥ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这台电脑能存储很多照片。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把文件存储在这个盘里。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的空间满了，不能再存储视频。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小盘可以存储一万首歌。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据存储起来以后，下次还能用。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工作资料存储在网上。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种卡存储着我们全家的照片。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬盘用来存储电脑里的数据。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先存储文件，再关电脑。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的数据都存储在一台机器里。", "target_word": "存储", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存储了", "label": "完成体"}, {"form": "存储过", "label": "经历体"}, {"form": "存储着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "把数据、文件等保存在设备里备用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存储", "is_correct": true, "explanation": "正确：“存储”表示把数据或文件存进设备里，与“电脑”和“照片”相符。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：电脑没有撕碎照片的部件，“撕碎”不能用于电脑。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”是使东西着火，电脑不能点燃照片。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：“晾晒”是把物体放在阳光下，电脑不能晾晒照片。"}], "explanations": {"存储": "正确：“存储”表示把数据或文件存进设备里，与“电脑”和“照片”相符。", "撕碎": "语义：电脑没有撕碎照片的部件，“撕碎”不能用于电脑。", "点燃": "语义：“点燃”是使东西着火，电脑不能点燃照片。", "晾晒": "语义：“晾晒”是把物体放在阳光下，电脑不能晾晒照片。"}, "sentence_index": 0, "correct_answer": "存储"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影在大屏幕上存储了一个小时。", "explanation": "这里应该用〈播放〉。影片在屏幕上放映要说〈播放〉；“存储”指把东西保存起来备用，不指放映。"}, {"text": "屏幕上存储着一张照片。", "explanation": "这里应该用〈显示〉。屏幕呈现画面要说〈显示〉；“存储”指保存起来备用，不指屏幕呈现。"}, {"text": "他把文件存储给了同事。", "explanation": "这里应该用〈发送〉。把文件交给别人要说〈发送〉；“存储”是保存在设备里，不表示交给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存储", "is_correct": true, "explanation": "正确：“存储”表示把照片保存在卡里，与“这种卡”和“照片”相符。"}, {"text": "翻阅", "is_correct": false, "explanation": "语义：“翻阅”的主体须是人，卡不能翻阅照片。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”的主体须是有意识的人，卡不能嘲笑照片。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：“清洁”的主体须是人或清洁工具，卡不能清洁照片。"}], "explanations": {"存储": "正确：“存储”表示把照片保存在卡里，与“这种卡”和“照片”相符。", "翻阅": "语义：“翻阅”的主体须是人，卡不能翻阅照片。", "嘲笑": "语义：“嘲笑”的主体须是有意识的人，卡不能嘲笑照片。", "清洁": "语义：“清洁”的主体须是人或清洁工具，卡不能清洁照片。"}, "sentence_index": 6, "correct_answer": "存储"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件能把视频的画面存储得更亮。", "explanation": "这里应该用〈调亮〉。让画面变亮要说〈调亮〉；“存储”只是把数据保存备用，不改变画面亮度。"}, {"text": "这根线存储着电脑和显示器。", "explanation": "这里应该用〈连接〉。线缆把设备接在一起要说〈连接〉；“存储”指保存备用，不指把设备接在一起。"}, {"text": "他存储了一个朋友，和他聊天。", "explanation": "这里应该用〈结交〉。认识朋友要说〈结交〉；“存储”的对象是物品或数据，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个移动硬盘能存储得很多视频。", "corrected_sentence": "这个移动硬盘能存储很多视频。", "error_description": "错误形式：“能存储得很多视频”，在“存储”后多加了补语标记“得”，句子不成立；正确形式：“能存储很多视频”，“存储”后直接接宾语，不加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧文件我都存储在起来了。", "corrected_sentence": "这些旧文件我都存储起来了。", "error_description": "错误形式：“存储在起来”，多加了介词“在”。正确形式：“存储起来”，“起来”前不加“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
