INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审理是法官听两边怎么说，再决定谁对谁错。", "primary_collocate": null, "pronunciation": "shěn lǐ", "ipa": "ʂən˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "法官正在审理这个案子。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官会认真审理每一个案子。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子下周开始审理。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官审理案子时，要听两边怎么说。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子已经审理了三天。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的案子由王法官审理。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官审理完案子，说小李没有错。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "审理这个案子的法官很认真。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官审理过很多家庭的案子。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家吵了很久，只好请法官来审理。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审理了", "label": "完成体"}, {"form": "审理过", "label": "经历体"}, {"form": "正在审理", "label": "进行体"}], "register": "正式", "sense_fingerprint": "法官听双方陈述后判断是非", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审理", "is_correct": true, "explanation": "语义：审理是法院或法官听取双方陈述后对案件作出判断，符合“法官正在……这个案子”的句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：案子不能吃，“吃”与法官处理案件的动作不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：案子不能唱，“唱”与案件无关。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”的对象通常是布料、衣物，不与“案子”搭配。"}], "explanations": {"审理": "语义：审理是法院或法官听取双方陈述后对案件作出判断，符合“法官正在……这个案子”的句意。", "吃": "语义：案子不能吃，“吃”与法官处理案件的动作不符。", "唱": "语义：案子不能唱，“唱”与案件无关。", "缝": "搭配：“缝”的对象通常是布料、衣物，不与“案子”搭配。"}, "sentence_index": 0, "correct_answer": "审理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官审理了这首歌，觉得很好听。", "explanation": "这里应该用〈欣赏〉。审理是司法活动，欣赏歌曲不能说审理。"}, {"text": "专家审理了这份报告。", "explanation": "这里应该用〈审查〉。审理专用于司法案件，报告、材料应用审查。"}, {"text": "领导审理了这份申请。", "explanation": "这里应该用〈审批〉。审理是司法活动，申请应由领导审批。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审理", "is_correct": true, "explanation": "语义：审理是法官对案件进行审查判断，“审理完案子”后作出结论，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：案子不能煮，“煮完案子”说不通。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：“绣”的对象通常是布料、织物，不与“案子”搭配。"}, {"text": "刷", "is_correct": false, "explanation": "语义：案子不能刷，“刷完案子”与法官的工作无关。"}], "explanations": {"审理": "语义：审理是法官对案件进行审查判断，“审理完案子”后作出结论，符合句意。", "煮": "语义：案子不能煮，“煮完案子”说不通。", "绣": "搭配：“绣”的对象通常是布料、织物，不与“案子”搭配。", "刷": "语义：案子不能刷，“刷完案子”与法官的工作无关。"}, "sentence_index": 6, "correct_answer": "审理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察审理了这起抢劫案，很快就抓到了小偷。", "explanation": "这里应该用〈调查〉。审理由法院进行，警方办案只说调查或侦查。"}, {"text": "这把椅子审理了两家的纠纷，很公平。", "explanation": "这里误用了〈审理〉。它指法院依法查明案件并作出判断，只能由法院或法官进行；让椅子充当审理的主体，是把它用在了没有判断能力的物体上。"}, {"text": "妈妈审理了那个偷吃饼干的孩子，很生气。", "explanation": "这里应该用〈批评〉。审理多用于法律案件，家长管教孩子一般说批评。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官正在审理了那起离婚案。", "corrected_sentence": "法官正在审理那起离婚案。", "error_description": "体标冲突：“正在”表示动作进行，不能再加“了”表示完成；应说“法官正在审理那起离婚案”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官审理了过这个案子。", "corrected_sentence": "法官审理过这个案子。", "error_description": "体标冲突：“了”与“过”不能同时用在同一个动词后面；只说“审理过”，表示曾经有过这种经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
