INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法院对案件进行审查和判断。", "primary_collocate": null, "pronunciation": "shěn lǐ", "ipa": "ʂən˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "法院今天审理一起盗窃案。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案件由北京法院审理。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院已经审理了这个案件。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院公开审理了这起案件。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起案件审理了两个月。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院将在下周审理这件案子。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种案件，法院一般不公开审理。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院审理过很多交通案件。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "案件还在审理，还没有结果。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案件审理得很快，一天就结束了。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审理了", "label": "完成体"}, {"form": "审理过", "label": "经历体"}, {"form": "正在审理", "label": "进行体"}], "register": "正式", "sense_fingerprint": "法院依法审查并判断案件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97fe4c13-4834-4860-bdf7-8fe0ba852eb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审理", "is_correct": true, "explanation": "语义：审理即法院对案件进行审查判断，“审理一起盗窃案”符合句意。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”的对象是器物，不能用来处理案件。"}, {"text": "煮", "is_correct": false, "explanation": "语义：案件不能煮，“煮一起盗窃案”说不通。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”的对象通常是布料、衣物，不与“案件”搭配。"}], "explanations": {"审理": "语义：审理即法院对案件进行审查判断，“审理一起盗窃案”符合句意。", "修": "语义：“修”的对象是器物，不能用来处理案件。", "煮": "语义：案件不能煮，“煮一起盗窃案”说不通。", "缝": "搭配：“缝”的对象通常是布料、衣物，不与“案件”搭配。"}, "sentence_index": 0, "correct_answer": "审理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子审理了这起案件。", "explanation": "这里误用了〈审理〉。它指法院依法查明案件并作出判断，只能由法院或法官进行；让椅子充当审理的主体，是把它用在了没有判断能力的物体上。"}, {"text": "老师审理了学生的作文。", "explanation": "这里应该用〈审阅〉。审理专用于案件，作文应说审阅或批改。"}, {"text": "我们审理了这个问题，结果很好。", "explanation": "这里应该用〈讨论〉。审理是法院对案件的处理，日常讨论问题不用审理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审理", "is_correct": true, "explanation": "语义：审理即法院依法审查判断案件，“不公开审理”符合句意。"}, {"text": "出售", "is_correct": false, "explanation": "语义：案件不能出售，“不公开出售”与法院的工作不符。"}, {"text": "表演", "is_correct": false, "explanation": "语义：案件不能拿来表演，“不公开表演”说不通。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”的对象是食物，不能用来与“案件”搭配。"}], "explanations": {"审理": "语义：审理即法院依法审查判断案件，“不公开审理”符合句意。", "出售": "语义：案件不能出售，“不公开出售”与法院的工作不符。", "表演": "语义：案件不能拿来表演，“不公开表演”说不通。", "煎": "搭配：“煎”的对象是食物，不能用来与“案件”搭配。"}, "sentence_index": 6, "correct_answer": "审理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察审理了这起交通事故，很快就找到了司机。", "explanation": "这里应该用〈侦查〉。审理由法院进行，警方查案只说侦查。"}, {"text": "同学们审理了这道数学题，很快得出了答案。", "explanation": "这里应该用〈解答〉。审理专用于司法案件，数学题应说解答。"}, {"text": "医生审理了这个病人，给他开了药。", "explanation": "这里应该用〈治疗〉。审理是司法活动，病人应说治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院已经正在审理完了这起案件。", "corrected_sentence": "法院已经审理完了这起案件。", "error_description": "体标冲突：“正在”表示动作进行，不能与表示完成的“完了”同用；应说“法院已经审理完了这起案件”，用“已经”表示完成，去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这起案件审理了得很仔细。", "corrected_sentence": "这起案件审理得很仔细。", "error_description": "错误：“得”前面不能加“了”，“审理了得”不成立；应说“审理得很仔细”，“得”直接接在动词后引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83918d44-984f-46c8-a39c-dd07cef30c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95843, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "互生", "is_correct": true, "explanation": "互生指叶子在茎上一片一片交替着长，与对生的排列方式相反。"}, {"text": "狭长", "is_correct": false, "explanation": "狭长形容叶片细长，与叶子的排列方式无关，不是对生的反义词。"}, {"text": "光滑", "is_correct": false, "explanation": "光滑形容表面的触感，与叶子的排列方式无关。"}, {"text": "紧密", "is_correct": false, "explanation": "紧密形容结合或距离近，与叶子的排列方式无关。"}], "correct_answer": "互生", "explanations": {"互生": "互生指叶子在茎上一片一片交替着长，与对生的排列方式相反。", "狭长": "狭长形容叶片细长，与叶子的排列方式无关，不是对生的反义词。", "光滑": "光滑形容表面的触感，与叶子的排列方式无关。", "紧密": "紧密形容结合或距离近，与叶子的排列方式无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95843, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "互生", "is_correct": true, "explanation": "互生指叶子在茎上一片一片交替着长，与对生的排列方式相反。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面不平滑，与叶子的排列方式无关。"}, {"text": "圆润", "is_correct": false, "explanation": "圆润形容形状饱满或声音柔和，与叶子的排列方式无关。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰形容明白或分明，与叶子的排列方式无关。"}], "correct_answer": "互生", "explanations": {"互生": "互生指叶子在茎上一片一片交替着长，与对生的排列方式相反。", "粗糙": "粗糙形容表面不平滑，与叶子的排列方式无关。", "圆润": "圆润形容形状饱满或声音柔和，与叶子的排列方式无关。", "清晰": "清晰形容明白或分明，与叶子的排列方式无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95843, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对生是叶子在树枝上两片两片地面对面长。", "primary_collocate": null, "pronunciation": "duì shēng", "ipa": "tweɪ˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这棵树的叶子是对生的。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "薄荷的叶子在茎上对生。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，枫树的叶子是对生的。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树枝上的叶子两片两片对生。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这些叶子都是对生的。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小树的叶子对生，很整齐。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桂花的叶子也是对生的。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它的叶子对生，不是一片一片长。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对生的叶子，一片对着另一片。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在公园里看到一棵叶子对生的树。", "target_word": "对生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对生的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "叶子在树枝上两两面对面生长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对生", "is_correct": true, "explanation": "对生指叶子两两相对长在枝条上，符合句中说的叶子排列方式。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：叶子不会聪明，句中说的是叶子的生长方式。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：叶子不会吵闹，句中说的是叶子的排列方式。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：叶子没有情绪，句中描述的是叶子的排列，不是心情。"}], "explanations": {"对生": "对生指叶子两两相对长在枝条上，符合句中说的叶子排列方式。", "聪明": "语义：叶子不会聪明，句中说的是叶子的生长方式。", "吵闹": "语义：叶子不会吵闹，句中说的是叶子的排列方式。", "悲伤": "语义：叶子没有情绪，句中描述的是叶子的排列，不是心情。"}, "sentence_index": 0, "correct_answer": "对生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种植物的叶子是对生的，一节一片。", "explanation": "这里应该用〈互生〉。对生指每节两片，一节一片要用互生。"}, {"text": "这片叶子的左右两边是对生的。", "explanation": "这里应该用〈对称〉。左右两边相同用“对称”，“对生”指叶子在茎上的排列。"}, {"text": "这对鸽子是对生的。", "explanation": "这里应该用〈成对〉。鸽子是动物，说成对用“成对”，“对生”只用于植物叶子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对生", "is_correct": true, "explanation": "对生指叶子两两相对长在枝条上，符合句意。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：叶子不会高兴，句中说的是叶子的生长方式。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：勇敢是人的品质，叶子不会勇敢，句中说的是叶子的排列方式。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：狡猾是人的品性，不能用于描述桂花叶子。"}], "explanations": {"对生": "对生指叶子两两相对长在枝条上，符合句意。", "高兴": "语义：叶子不会高兴，句中说的是叶子的生长方式。", "勇敢": "语义：勇敢是人的品质，叶子不会勇敢，句中说的是叶子的排列方式。", "狡猾": "语义：狡猾是人的品性，不能用于描述桂花叶子。"}, "sentence_index": 6, "correct_answer": "对生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两座山对生在河的两岸。", "explanation": "这里应该用〈相对〉。两座山相对用“相对”，“对生”只用于植物叶子的排列。"}, {"text": "两条河在这里对生。", "explanation": "这里应该用〈交汇〉。河流汇合用“交汇”，“对生”只用于植物叶子的排列。"}, {"text": "两只耳朵对生在头的两侧。", "explanation": "这里应该用〈长〉。耳朵长在头的两侧用“长”，“对生”只用于植物叶子的排列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种树的叶子很对生。", "corrected_sentence": "这种树的叶子对生。", "error_description": "错误：“很对生”，“对生”描述叶子的排列方式，不能受程度副词“很”修饰。正确：“叶子对生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种树的叶子两个对生。", "corrected_sentence": "这种树的叶子两两对生。", "error_description": "错误：“两个对生”，数量表达不地道，应用副词“两两”修饰“对生”。正确：“两两对生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
