INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小子是对男孩子的叫法，有时有点亲热，有时有点看不起。", "primary_collocate": null, "pronunciation": "xiǎo zi", "ipa": "ɕjɑʊ˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "这小子真聪明！", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这小子，又迟到了。", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那小子跑得真快。", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "臭小子，快去写作业！", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小子是谁？", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷笑着说：“你这小子，真有办法。”", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那小子偷了我的东西。", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这小子才十岁，就会做饭了。", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你小子别想骗我。", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这小子今天又跟人打架了。", "target_word": "小子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "臭小子", "label": "复合"}], "register": "口语", "sense_fingerprint": "对男孩子的称呼，亲热或轻视", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95845, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小子", "is_correct": true, "explanation": "正确答案：小子，读作 xiǎo zi，指男孩子。"}, {"text": "孝子", "is_correct": false, "explanation": "xiào（第四声）与 xiǎo（第三声）声调不同，孝子指孝顺父母的儿子。"}, {"text": "小指", "is_correct": false, "explanation": "zhǐ 与 zi 声母不同（zh 与 z），小指指小手指。"}, {"text": "小组", "is_correct": false, "explanation": "zǔ 与 zi 韵母不同（u 与 i），小组指小团体。"}, {"text": "小字", "is_correct": false, "explanation": "zì（第四声）与 zi（轻声）声调不同，小字指小号的字。"}], "explanations": {"小子": "正确答案：小子，读作 xiǎo zi，指男孩子。", "孝子": "xiào（第四声）与 xiǎo（第三声）声调不同，孝子指孝顺父母的儿子。", "小指": "zhǐ 与 zi 声母不同（zh 与 z），小指指小手指。", "小组": "zǔ 与 zi 韵母不同（u 与 i），小组指小团体。", "小字": "zì（第四声）与 zi（轻声）声调不同，小字指小号的字。"}, "sentence_index": null, "correct_answer": "小子"}, "level_3": {"options": [{"text": "小子", "is_correct": true, "explanation": "小子：对男孩子的口语称呼，这里带有亲昵或夸赞的意味，与“这”搭配自然。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有智力，不能用“聪明”来形容。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是无生命的物体，不能说它真聪明。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是无生命的文具，不能说它真聪明。"}], "explanations": {"小子": "小子：对男孩子的口语称呼，这里带有亲昵或夸赞的意味，与“这”搭配自然。", "石头": "语义：石头没有智力，不能用“聪明”来形容。", "窗户": "语义：窗户是无生命的物体，不能说它真聪明。", "铅笔": "语义：铅笔是无生命的文具，不能说它真聪明。"}, "sentence_index": 0, "correct_answer": "小子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷，您这小子真会讲故事。", "explanation": "称呼错误：小子是对男孩或年轻男子的称呼，不能用来称呼长辈。对爷爷应该说“您”或“老人家”。"}, {"text": "我的妹妹很文静，她是个小子。", "explanation": "这里不能用〈小子〉。小子只指男孩或年轻男子，指女性应该用〈女孩〉或〈姑娘〉。"}, {"text": "各位领导，请这位小子上台讲话。", "explanation": "语域：小子是口语，带有亲昵或轻视意味，正式场合应该用〈先生〉或〈同志〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95845, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小子", "is_correct": true, "explanation": "正确答案：小子，读作 xiǎo zi，指男孩子。"}, {"text": "销子", "is_correct": false, "explanation": "xiāo（第一声）与 xiǎo（第三声）声调不同，销子指固定用的小栓子。"}, {"text": "小纸", "is_correct": false, "explanation": "zhǐ 与 zi 声母不同（zh 与 z），小纸指小张的纸。"}, {"text": "小崽", "is_correct": false, "explanation": "zǎi 与 zi 韵母不同（ai 与 i），小崽指幼小的动物或孩子。"}], "explanations": {"小子": "正确答案：小子，读作 xiǎo zi，指男孩子。", "销子": "xiāo（第一声）与 xiǎo（第三声）声调不同，销子指固定用的小栓子。", "小纸": "zhǐ 与 zi 声母不同（zh 与 z），小纸指小张的纸。", "小崽": "zǎi 与 zi 韵母不同（ai 与 i），小崽指幼小的动物或孩子。"}, "sentence_index": null, "correct_answer": "小子"}, "level_3": {"options": [{"text": "小子", "is_correct": true, "explanation": "小子：指男孩子，这里是对偷东西的男孩的口语称呼，带有轻视意味。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不会偷东西，不能作偷窃的主语。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能偷东西的人，句子不成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是人，不会偷东西，句子不成立。"}], "explanations": {"小子": "小子：指男孩子，这里是对偷东西的男孩的口语称呼，带有轻视意味。", "空气": "语义：空气不会偷东西，不能作偷窃的主语。", "天空": "语义：天空不是能偷东西的人，句子不成立。", "月亮": "语义：月亮不是人，不会偷东西，句子不成立。"}, "sentence_index": 6, "correct_answer": "小子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那辆自行车是个小子，骑起来很快。", "explanation": "语义：小子只指人，不能指物品。这里应该说〈辆〉〈车〉之类的物品词，不能用〈小子〉。"}, {"text": "这位退休的老工人，是我们厂里最年长的小子。", "explanation": "语义：小子指男孩或年轻男子，不能用于年纪很大的人。这里应该用〈老人〉或〈师傅〉。"}, {"text": "门口站着一只小子，正在等我。", "explanation": "量词：小子指人，应该用〈个〉，不能用〈只〉（只多用于动物或成对的东西）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个小子们在门口玩。", "corrected_sentence": "两个小子在门口玩。", "error_description": "“们”的错误：数量词“两个”后面的名词不能再加“们”，应说“两个小子”，不能说“两个小子们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小子偷了我的书包。", "corrected_sentence": "那个小子偷了我的书包。", "error_description": "量词错误：“小子”指人，应该用“个”，不能用“只”。正确说法是“那个小子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
