INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95850, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "面积单位，边长为一公里的正方形的面积。", "primary_collocate": null, "pronunciation": "píng fāng gōng lǐ", "ipa": "pʰiŋ˧˥ faŋ˥ kʊŋ˥ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个湖的面积是三平方公里。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一平方公里等于一百万平方米。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小岛只有两平方公里。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园有五平方公里大。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一平方公里比一个足球场大得多。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城市有一千多平方公里。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片森林有十平方公里。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上写着：面积二十平方公里。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子不到一平方公里。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片海有三百平方公里。", "target_word": "平方公里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "面积单位，边长一公里的正方形的面积", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13e40e28-eddb-4b26-84f8-93c953de069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平方公里", "is_correct": true, "explanation": "正确。平方公里是面积单位，与“这个湖的面积是三”相符。"}, {"text": "吨", "is_correct": false, "explanation": "语义：吨是重量单位，不能用来计量面积。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”是通用量词，不能作为面积的计量单位。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：公斤是重量单位，与“面积”的说法不合。"}], "explanations": {"平方公里": "正确。平方公里是面积单位，与“这个湖的面积是三”相符。", "吨": "语义：吨是重量单位，不能用来计量面积。", "个": "搭配：“个”是通用量词，不能作为面积的计量单位。", "公斤": "语义：公斤是重量单位，与“面积”的说法不合。"}, "sentence_index": 0, "correct_answer": "平方公里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路有五平方公里长。", "explanation": "这里应该用长度单位〈千米〉。平方公里是面积单位，不能用来描述路的长度。"}, {"text": "这场会议开了三平方公里。", "explanation": "这里应该用〈小时〉。平方公里只用来计量面积，会议是有时长的活动，不能这样计量。"}, {"text": "他身高有五平方公里。", "explanation": "这里应该用〈米〉。平方公里是面积单位，不能用来计量人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平方公里", "is_correct": true, "explanation": "正确。平方公里是面积单位，与“这片森林有十”相符。"}, {"text": "升", "is_correct": false, "explanation": "语义：升是容积单位，不能用来计量森林的面积。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”用于计数次数，不能用来计量森林的面积。"}, {"text": "元", "is_correct": false, "explanation": "语义：元是货币单位，与森林的面积无关。"}], "explanations": {"平方公里": "正确。平方公里是面积单位，与“这片森林有十”相符。", "升": "语义：升是容积单位，不能用来计量森林的面积。", "次": "搭配：“次”用于计数次数，不能用来计量森林的面积。", "元": "语义：元是货币单位，与森林的面积无关。"}, "sentence_index": 6, "correct_answer": "平方公里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果有五平方公里重。", "explanation": "这里应该用〈公斤〉。平方公里是面积单位，不能用来称重量。"}, {"text": "这本书有三百平方公里厚。", "explanation": "这里应该用〈厘米〉。平方公里是面积单位，不能用来描述书的厚度。"}, {"text": "他今年二十平方公里了。", "explanation": "这里应该用〈岁〉。平方公里是面积单位，不能用来表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县城大约有八的平方公里。", "corrected_sentence": "这个县城大约有八平方公里。", "error_description": "错误形式是“八的平方公里”，正确形式是“八平方公里”。数词与“平方公里”之间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个岛屿大约有五平方公里长。", "corrected_sentence": "这个岛屿大约有五平方公里大。", "error_description": "错误形式是“五平方公里长”，正确形式是“五平方公里大”。平方公里是面积单位，后面要用“大”，不能用表示长度的“长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
