INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95854, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "佛教指修行的人领悟真理，达到觉悟。", "primary_collocate": null, "pronunciation": "chéng dào", "ipa": "ʈʂʰɤŋ˧˥ tɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "佛教认为，人只要觉悟就能成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相传释迦牟尼三十五岁时成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在寺里打坐多年，最后成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座寺庙是师父成道的地方。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，成道的人心里很平静。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这位老和尚昨晚打坐时成道了。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放下一切，专心修行，希望早日成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成道之后，他把自己的经验告诉大家。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "佛教徒相信，用心修行的人会成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己还没成道，要继续学习。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成道了", "label": "体标"}], "register": "书面", "sense_fingerprint": "佛教指领悟真理达到觉悟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9cbe6ac-6e27-417b-92b2-2981f60beb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成道", "is_correct": true, "explanation": "正确。佛教指觉悟真理为成道，符合“只要觉悟就能”的语境。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是身体生病的表现，与“觉悟”无关，句子不通。"}, {"text": "变胖", "is_correct": false, "explanation": "搭配：“变胖”不能作为“觉悟”的结果，二者不搭配。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病与佛教的觉悟无关，不符合句意。"}], "explanations": {"成道": "正确。佛教指觉悟真理为成道，符合“只要觉悟就能”的语境。", "发烧": "语义：发烧是身体生病的表现，与“觉悟”无关，句子不通。", "变胖": "搭配：“变胖”不能作为“觉悟”的结果，二者不搭配。", "生病": "语义：生病与佛教的觉悟无关，不符合句意。"}, "sentence_index": 0, "correct_answer": "成道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在高考中终于成道了。", "explanation": "这里应该用〈考上〉。成道是佛教用语，指修行者觉悟，不能用于考试。"}, {"text": "这条新马路终于成道了。", "explanation": "这里应该用〈修好〉。成道的主体必须是修行的人，马路不能成道。"}, {"text": "他的病终于成道了。", "explanation": "这里应该用〈治好〉。成道指觉悟真理，不能用于疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成道", "is_correct": true, "explanation": "正确。成道指修行者觉悟真理，符合“放下一切，专心修行”的目标。"}, {"text": "赚钱", "is_correct": false, "explanation": "语义：赚钱与“放下一切，专心修行”的语境相矛盾。"}, {"text": "发财", "is_correct": false, "explanation": "语义：发财是追求物质利益，与“放下一切”的修行态度矛盾。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“希望早日”后接的动词应是可以期盼的目标，“咳嗽”不符合。"}], "explanations": {"成道": "正确。成道指修行者觉悟真理，符合“放下一切，专心修行”的目标。", "赚钱": "语义：赚钱与“放下一切，专心修行”的语境相矛盾。", "发财": "语义：发财是追求物质利益，与“放下一切”的修行态度矛盾。", "咳嗽": "搭配：“希望早日”后接的动词应是可以期盼的目标，“咳嗽”不符合。"}, "sentence_index": 6, "correct_answer": "成道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经过四年努力，终于成道了。", "explanation": "这里应该用〈毕业〉。成道指修行者觉悟真理，与学业无关。"}, {"text": "他在外面跑了一天，终于成道了。", "explanation": "这里应该用〈回家〉。成道是佛教用语，不能用于一个人回到住处。"}, {"text": "这家饭店终于成道了。", "explanation": "这里应该用〈开业〉。成道的主体必须是修行的人，饭店不能成道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老僧坐禅多年，终于被成道了。", "corrected_sentence": "那位老僧坐禅多年，终于成道了。", "error_description": "“被”字句不能用于不及物动词“成道”，应为“那位老僧坐禅多年，终于成道了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位师父成道着后，开始收徒弟。", "corrected_sentence": "这位师父成道后，开始收徒弟。", "error_description": "“着”表示动作进行，不能插在“成道”后面表示先后关系，应为“这位师父成道后，开始收徒弟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
