INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于空战的军用飞机，速度快、机动性强。", "primary_collocate": null, "pronunciation": "zhàn dòu jī", "ipa": "tʂan˥˩ tou˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "天上飞过去三架战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机的速度比客机快得多。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架战斗机能在空中打仗。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是战斗机飞行员。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军新买了一批战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机起飞时声音很大。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一架旧战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机在空中追上了敌机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员开着战斗机飞向蓝天。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空母舰上停着很多战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "战斗机飞行员", "label": "复合"}, {"form": "舰载战斗机", "label": "复合"}, {"form": "戰鬥機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战斗机：空军用来空战、速度快的军用飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '981d0e3c-e2be-4751-af4a-301b1d651d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战斗机", "is_correct": true, "explanation": "“三架”是飞机的量词，天上飞过去的正是战斗机。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车在地面上行驶，不会飞过天空。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：火车的量词是“列”，不用“架”。"}, {"text": "气球", "is_correct": false, "explanation": "搭配：气球的量词是“个”，不用“架”。"}], "explanations": {"战斗机": "“三架”是飞机的量词，天上飞过去的正是战斗机。", "汽车": "语义：汽车在地面上行驶，不会飞过天空。", "火车": "搭配：火车的量词是“列”，不用“架”。", "气球": "搭配：气球的量词是“个”，不用“架”。"}, "sentence_index": 0, "correct_answer": "战斗机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的爸爸是战斗机。", "explanation": "这里应该用〈飞行员〉。战斗机是飞机，不能指人，指职业要说飞行员。"}, {"text": "机场上停着一只战斗机。", "explanation": "量词错误：战斗机应说“一架”，不说“一只”，“只”多用于动物。"}, {"text": "天上飞过一辆战斗机。", "explanation": "量词错误：战斗机是飞机，应说“一架”，不说“一辆”，“辆”用于陆上的车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战斗机", "is_correct": true, "explanation": "“一架”配飞机，博物馆里展出的旧飞机就是战斗机。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“架”不用于花瓶，花瓶的量词是“个”。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“架”不用于鞋，鞋的量词是“双”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“架”不用于房子，房子的量词是“座”。"}], "explanations": {"战斗机": "“一架”配飞机，博物馆里展出的旧飞机就是战斗机。", "花瓶": "搭配：“架”不用于花瓶，花瓶的量词是“个”。", "鞋": "搭配：“架”不用于鞋，鞋的量词是“双”。", "房子": "搭配：“架”不用于房子，房子的量词是“座”。"}, "sentence_index": 6, "correct_answer": "战斗机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书包里有一把战斗机。", "explanation": "量词错误：战斗机应说“一架”，“把”用于有柄的器具，不用于飞机。"}, {"text": "妈妈给我买了一条战斗机。", "explanation": "量词错误：战斗机应说“一架”，“条”用于细长的东西，不用于飞机。"}, {"text": "停机坪上有一头战斗机。", "explanation": "量词错误：战斗机应说“一架”，“头”一般用于牲畜，不用于战斗机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上飞过去两只战斗机。", "corrected_sentence": "天上飞过去两架战斗机。", "error_description": "量词错误：战斗机应用“架”，不用“只”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机场上停着一辆新战斗机。", "corrected_sentence": "机场上停着一架新战斗机。", "error_description": "量词错误：战斗机是飞机，应用“架”，不用“辆”，“辆”用于陆上的车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "“反对”与“提倡”意思相反，表示不赞成、阻止。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“提倡”没有反义关系，只是普通的日常活动。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“提倡”没有反义关系，只是一种体育运动。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“提倡”没有反义关系，只是一种行为。"}], "correct_answer": "反对", "explanations": {"反对": "“反对”与“提倡”意思相反，表示不赞成、阻止。", "散步": "“散步”与“提倡”没有反义关系，只是普通的日常活动。", "游泳": "“游泳”与“提倡”没有反义关系，只是一种体育运动。", "唱歌": "“唱歌”与“提倡”没有反义关系，只是一种行为。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "“反对”与“提倡”意思相反，表示不赞成、阻止。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”与“提倡”没有反义关系，只是一种体育活动。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”与“提倡”没有反义关系，只是一种爱好。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”与“提倡”没有反义关系，只是一种日常行为。"}], "correct_answer": "反对", "explanations": {"反对": "“反对”与“提倡”意思相反，表示不赞成、阻止。", "跑步": "“跑步”与“提倡”没有反义关系，只是一种体育活动。", "画画": "“画画”与“提倡”没有反义关系，只是一种爱好。", "睡觉": "“睡觉”与“提倡”没有反义关系，只是一种日常行为。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提倡是说一件事很好，请大家都这样做。", "primary_collocate": null, "pronunciation": "tí chàng", "ipa": "tʰi˧˥ ʈʂʰaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师提倡大家每天早起读书。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区提倡垃圾分类。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸提倡全家人一起吃晚饭。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院提倡病人多休息。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站提倡大家排队上车。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆提倡安静看书。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里提倡不乱扔垃圾。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈提倡我们自己的事自己做。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里提倡工人注意安全。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提倡我们用普通话交流。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提倡了", "label": "完成体"}, {"form": "提倡过", "label": "经验体"}, {"form": "大力提倡", "label": "复合"}], "register": "中性", "sense_fingerprint": "提倡：说某事很好，请大家都这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4cfc666-8119-44d9-9cb1-da1cda7a5a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提倡", "is_correct": true, "explanation": "“提倡”表示说某事很好并请大家这样做，与“早起读书”的语境相符，是正确答案。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”表示不许做，与老师希望大家早起读书的意思相反。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不能带“大家每天早起读书”这样的小句作宾语。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与老师认为早起读书是好事的语境不符。"}], "explanations": {"提倡": "“提倡”表示说某事很好并请大家这样做，与“早起读书”的语境相符，是正确答案。", "禁止": "语义：“禁止”表示不许做，与老师希望大家早起读书的意思相反。", "扔": "搭配：“扔”不能带“大家每天早起读书”这样的小句作宾语。", "讨厌": "语义：“讨厌”表示不喜欢，与老师认为早起读书是好事的语境不符。"}, "sentence_index": 0, "correct_answer": "提倡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市正在提倡一种新饮料。", "explanation": "这里应该用〈推广〉。提倡指说某事很好、请大家去做，不能用来指把具体商品铺开销售。"}, {"text": "老师提倡了这次考试。", "explanation": "这里应该用〈组织〉。提倡是鼓励大家去做某种做法，不能用来指安排举办一次考试；安排考试要用〈组织〉。"}, {"text": "学校提倡了三十名新生。", "explanation": "这里应该用〈录取〉。提倡的对象是某种做法或观念，不能指一批人；录取新生要用〈录取〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提倡", "is_correct": true, "explanation": "“提倡”表示鼓励大家去做，与“不乱扔垃圾”这种好习惯相符，是正确答案。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误，与公园鼓励文明行为的语境不符。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象多为具体物品，不能用于“不乱扔垃圾”这样的行为。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不赞成，与公园倡导文明的意思相反。"}], "explanations": {"提倡": "“提倡”表示鼓励大家去做，与“不乱扔垃圾”这种好习惯相符，是正确答案。", "批评": "语义：“批评”是指出错误，与公园鼓励文明行为的语境不符。", "收藏": "搭配：“收藏”的对象多为具体物品，不能用于“不乱扔垃圾”这样的行为。", "反对": "语义：“反对”表示不赞成，与公园倡导文明的意思相反。"}, "sentence_index": 6, "correct_answer": "提倡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居委会提倡了乱扔垃圾。", "explanation": "这里应该用〈制止〉。提倡是赞成并鼓励做某事，乱扔垃圾应当用〈制止〉。"}, {"text": "我们每天都提倡地板。", "explanation": "这里应该用〈打扫〉。提倡的对象是某种做法或观念，不能指具体的物体；打扫地板要用〈打扫〉。"}, {"text": "妈妈提倡了我的爱好。", "explanation": "这里应该用〈培养〉。提倡的对象是值得大家去做的事，爱好要靠培养，不能说提倡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸大量提倡全家人吃健康的早餐。", "corrected_sentence": "爸爸大力提倡全家人吃健康的早餐。", "error_description": "用词搭配错误：“提倡”通常由表示力度的“大力”修饰；“大量”强调数量多，与“提倡”搭配不自然，应说“大力提倡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校正在提倡了文明用餐。", "corrected_sentence": "学校正在提倡文明用餐。", "error_description": "动态助词错误：“正在”表示动作进行，不能与“了”同时用在“提倡”上，应去掉“了”，说“正在提倡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95858, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "“反对”与“提倡”意思相反，表示不赞成、阻止。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“提倡”没有反义关系，只是普通的日常活动。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”与“提倡”没有反义关系，只是一种体育运动。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“提倡”没有反义关系，只是一种行为。"}], "correct_answer": "反对", "explanations": {"反对": "“反对”与“提倡”意思相反，表示不赞成、阻止。", "散步": "“散步”与“提倡”没有反义关系，只是普通的日常活动。", "游泳": "“游泳”与“提倡”没有反义关系，只是一种体育运动。", "唱歌": "“唱歌”与“提倡”没有反义关系，只是一种行为。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
