INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某种事物表示重视，并鼓励大家去做。", "primary_collocate": null, "pronunciation": "tí chàng", "ipa": "tʰi˧˥ ʈʂʰaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校提倡同学们多读书。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府大力提倡节约用水。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们提倡少用塑料袋，保护环境。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司提倡员工骑自行车上班。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一直提倡大家说话要有礼貌。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生提倡每天多喝水，多运动。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在社会提倡低碳生活。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区提倡大家把旧衣服送给需要的人。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校提倡学生每天锻炼一小时。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的班级提倡互相帮助。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提倡了", "label": "完成体"}, {"form": "提倡过", "label": "经验体"}, {"form": "大力提倡", "label": "复合"}], "register": "中性", "sense_fingerprint": "提倡：重视某种做法并鼓励大家去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4cfc666-8119-44d9-9cb1-da1cda7a5a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提倡", "is_correct": true, "explanation": "“提倡”表示重视并鼓励大家去做，与“多读书”的语境相符，是正确答案。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”表示不许做，与学校希望学生多读书的意思相反。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是具体物品，不能带“同学们多读书”这样的小句作宾语。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出缺点或错误，与学校鼓励读书的做法不符。"}], "explanations": {"提倡": "“提倡”表示重视并鼓励大家去做，与“多读书”的语境相符，是正确答案。", "禁止": "语义：“禁止”表示不许做，与学校希望学生多读书的意思相反。", "扔": "搭配：“扔”的对象是具体物品，不能带“同学们多读书”这样的小句作宾语。", "批评": "语义：“批评”是指出缺点或错误，与学校鼓励读书的做法不符。"}, "sentence_index": 0, "correct_answer": "提倡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司正在提倡新的手机。", "explanation": "这里应该用〈推广〉。提倡指鼓励大家去做某种行为或观念，不能用来指把具体商品铺开销售。"}, {"text": "学校提倡了一场比赛。", "explanation": "这里应该用〈举办〉。提倡指鼓励大家去做某种行为或观念，不能用来指组织一场活动；办比赛要用〈举办〉。"}, {"text": "老师提倡了一个认真的学生。", "explanation": "这里应该用〈表扬〉。提倡的对象是某种做法或观念，不能指一个人；称赞具体的人要用〈表扬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提倡", "is_correct": true, "explanation": "“提倡”表示鼓励大家去做，与“低碳生活”这种被推崇的生活方式相符，是正确答案。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不赞成，与社会推崇低碳生活的语境相反。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与社会鼓励低碳生活的意思不符。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象多为具体物品，不能用于“低碳生活”这样的生活方式。"}], "explanations": {"提倡": "“提倡”表示鼓励大家去做，与“低碳生活”这种被推崇的生活方式相符，是正确答案。", "反对": "语义：“反对”表示不赞成，与社会推崇低碳生活的语境相反。", "讨厌": "语义：“讨厌”表示不喜欢，与社会鼓励低碳生活的意思不符。", "收藏": "搭配：“收藏”的对象多为具体物品，不能用于“低碳生活”这样的生活方式。"}, "sentence_index": 6, "correct_answer": "提倡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈提倡我们熬夜看书。", "explanation": "这里应该用〈劝阻〉。提倡是赞成并鼓励做某事，熬夜这类有害健康的做法应当用〈劝阻〉。"}, {"text": "我们每天都提倡教室。", "explanation": "这里应该用〈打扫〉。提倡的对象是某种做法或观念，不能指具体的场所；打扫教室要用〈打扫〉。"}, {"text": "他提倡了我的兴趣。", "explanation": "这里应该用〈培养〉。提倡的对象是值得大家去做的事，兴趣要靠培养，不能说提倡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
