INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同的东西组合在一起后，看起来或用起来很合适的效果。", "primary_collocate": null, "pronunciation": "dā pèi", "ipa": "ta˥ pʰei̯˥˩", "syllable_count": 2, "sentences": [{"text": "这种搭配看起来很舒服。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色和绿色的搭配很特别。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对今天的衣服搭配很满意。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个很好的搭配。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭和青菜是简单的搭配。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得这个颜色搭配怎么样？", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套家具的搭配很合适。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡和蛋糕是最好的搭配。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服搭配总是很好看。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种水果的搭配很少见，但是很好吃。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "搭配·名词：不同东西放在一起后合适的组合效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搭配", "is_correct": true, "explanation": "“搭配”指事物配合在一起的组合效果，“这种搭配看起来很舒服”符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要靠味觉感受，不能用“看起来”形容。"}, {"text": "配方", "is_correct": false, "explanation": "语义：配方指制作某物的成分与比例，不能用“看起来很舒服”形容。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音靠听觉感知，不能用“看起来”形容。"}], "explanations": {"搭配": "“搭配”指事物配合在一起的组合效果，“这种搭配看起来很舒服”符合句意。", "味道": "语义：味道要靠味觉感受，不能用“看起来”形容。", "配方": "语义：配方指制作某物的成分与比例，不能用“看起来很舒服”形容。", "声音": "语义：声音靠听觉感知，不能用“看起来”形容。"}, "sentence_index": 0, "correct_answer": "搭配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一把很好的搭配。", "explanation": "这里应该用〈个〉或〈种〉。量词“把”用于有柄的东西，抽象的组合要用“个”或“种”。"}, {"text": "这个箱子的搭配很重。", "explanation": "这里应该用〈重量〉。搭配指事物的组合，箱子的轻重要用重量。"}, {"text": "他的汉语搭配很高。", "explanation": "这里应该用〈水平〉。搭配指事物的组合，能力的高低要用水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搭配", "is_correct": true, "explanation": "“搭配”指家具各部分的组合效果，“这套家具的搭配很合适”符合句意。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：口味多用于饮食，不能用于家具。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格属于人，家具没有性格。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于人或动物，家具没有脾气。"}], "explanations": {"搭配": "“搭配”指家具各部分的组合效果，“这套家具的搭配很合适”符合句意。", "口味": "搭配：口味多用于饮食，不能用于家具。", "性格": "语义：性格属于人，家具没有性格。", "脾气": "语义：脾气属于人或动物，家具没有脾气。"}, "sentence_index": 6, "correct_answer": "搭配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的搭配很快。", "explanation": "这里应该用〈速度〉。搭配指事物配合的效果，车的快慢要用速度。"}, {"text": "这道题的搭配很大。", "explanation": "这里应该用〈难度〉。搭配指事物的组合，题目的难易要用难度。"}, {"text": "这家店的搭配很高。", "explanation": "这里应该用〈人气〉。搭配指事物的组合，店铺受欢迎的程度要用人气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一把搭配很特别。", "corrected_sentence": "这一种搭配很特别。", "error_description": "错误：“搭配”不用量词“把”，“把”用于有柄的东西。正确：抽象的组合用“种”或“个”，应说“这一种搭配”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子的搭配了很合适。", "corrected_sentence": "这张桌子的搭配很合适。", "error_description": "错误：名词“搭配”后不能加“了”。正确：去掉“了”，说“这张桌子的搭配很合适”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95860, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95860, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的事物按一定要求配合在一起。", "primary_collocate": null, "pronunciation": "dā pèi", "ipa": "ta˥ pʰei̯˥˩", "syllable_count": 2, "sentences": [{"text": "这件白衬衫可以和黑裤子搭配。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把青菜和鱼搭配着做成午饭。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色外套你想搭配什么裤子？", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条围巾和你的帽子搭配得很好。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会搭配衣服，每天都很好看。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们来搭配一下今天的午饭吧。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包可以搭配牛奶一起吃。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么搭配颜色。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把蓝色的鞋和白色的袜子搭配了一下。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋我搭配过很多条裙子。", "target_word": "搭配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搭配了", "label": "体标"}, {"form": "搭配着", "label": "体标"}, {"form": "搭配过", "label": "体标"}], "register": "中性", "sense_fingerprint": "搭配·动词：把不同的衣服、食物、颜色等按要求配合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搭配", "is_correct": true, "explanation": "“搭配”指把衣物按要求配在一起，与白衬衫、黑裤子相合，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚的对象必须是人，衣裤不能与人结婚。"}, {"text": "道歉", "is_correct": false, "explanation": "搭配：道歉要说“向…道歉”，且对象是人，不能说“和黑裤子道歉”。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛需要参赛的人或队伍，衣裤不能参加比赛。"}], "explanations": {"搭配": "“搭配”指把衣物按要求配在一起，与白衬衫、黑裤子相合，符合句意。", "结婚": "语义：结婚的对象必须是人，衣裤不能与人结婚。", "道歉": "搭配：道歉要说“向…道歉”，且对象是人，不能说“和黑裤子道歉”。", "比赛": "语义：比赛需要参赛的人或队伍，衣裤不能参加比赛。"}, "sentence_index": 0, "correct_answer": "搭配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把花瓶搭配在窗台上。", "explanation": "这里应该用〈摆放〉。搭配指把东西按要求配在一起，不表示放置的位置，把花瓶放在窗台上要用摆放。"}, {"text": "她把房间搭配得干干净净。", "explanation": "这里应该用〈打扫〉。搭配指把东西按要求配在一起，不表示清洁，把房间弄干净要用打扫。"}, {"text": "工人把零件搭配成了一台机器。", "explanation": "这里应该用〈组装〉。搭配不指把零件装配成整体，把零件装成机器要用组装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搭配", "is_correct": true, "explanation": "“搭配”指把食物按要求配在一起，“面包可以搭配牛奶一起吃”符合句意。"}, {"text": "批评", "is_correct": false, "explanation": "语义：批评的对象应是人或其行为，牛奶不能被批评。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：拥抱的对象是人或动物，牛奶不能被拥抱。"}, {"text": "搭乘", "is_correct": false, "explanation": "搭配：搭乘后接的是交通工具，“牛奶”不能被搭乘。"}], "explanations": {"搭配": "“搭配”指把食物按要求配在一起，“面包可以搭配牛奶一起吃”符合句意。", "批评": "语义：批评的对象应是人或其行为，牛奶不能被批评。", "拥抱": "语义：拥抱的对象是人或动物，牛奶不能被拥抱。", "搭乘": "搭配：搭乘后接的是交通工具，“牛奶”不能被搭乘。"}, "sentence_index": 6, "correct_answer": "搭配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府搭配了一个新机构。", "explanation": "这里应该用〈设立〉。搭配指把东西按要求配在一起，成立机构要用设立。"}, {"text": "他们搭配了新的计划。", "explanation": "这里应该用〈制定〉。搭配指东西配合在一起，拟订计划要用制定。"}, {"text": "他去银行搭配了存款手续。", "explanation": "这里应该用〈办理〉。搭配不用于手续，办理存款手续要用办理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋和那条裙子搭配得好很。", "corrected_sentence": "这双鞋和那条裙子搭配得很好。", "error_description": "错误：副词“很”放在补语“好”后，成了“得好很”。正确：“很”应放在“好”前，说“搭配得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把红色和黄色搭配了很好。", "corrected_sentence": "他把红色和黄色搭配得很好。", "error_description": "错误：“搭配”后用“了”，并直接接“很好”。正确：应用结构助词“得”引出补语，说“搭配得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放心", "is_correct": true, "explanation": "放心：心里不再挂念、安定，与“担忧”构成反义。"}, {"text": "同意", "is_correct": false, "explanation": "同意：表示赞成，与“担忧”不构成反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "无关：“读书”指阅读学习，与“担忧”没有对立关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指悠闲地走路，与“担忧”没有对立关系。"}], "correct_answer": "放心", "explanations": {"放心": "放心：心里不再挂念、安定，与“担忧”构成反义。", "同意": "同意：表示赞成，与“担忧”不构成反义关系。", "读书": "无关：“读书”指阅读学习，与“担忧”没有对立关系。", "散步": "散步：指悠闲地走路，与“担忧”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
