INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "担忧是心里害怕会出事，不放心。", "primary_collocate": null, "pronunciation": "dān yōu", "ipa": "tan˥ joʊ˥", "syllable_count": 2, "sentences": [{"text": "妈妈很担忧我一个人出远门。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨了，大家都担忧河水会涨起来。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担忧着女儿的安全，一夜没睡。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还没回家，妈妈十分担忧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说没事，你不用担忧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我担忧飞机会晚点，早早去了机场。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人担忧地看着窗外的大雨。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没担忧过考试的结果。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸担忧孩子会在路上出事。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越来越冷，我担忧家里的老人。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担忧了", "label": "了体标"}, {"form": "担忧着", "label": "着体标"}, {"form": "担忧过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "害怕会出事而不放心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d993711-fcb6-4ae5-84ed-b24535ccaac2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：为孩子出远门的安全而挂心，与“很”的修饰及句意相合。"}, {"text": "爱护", "is_correct": false, "explanation": "配价：“爱护”的对象是人或物，不能接“我一个人出远门”这类事件作宾语。"}, {"text": "尊敬", "is_correct": false, "explanation": "配价：“尊敬”要求以人为对象，不能接事件小句。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”指对他人的优势心生不满，与母亲为孩子安全挂心的语境不符。"}], "explanations": {"担忧": "担忧：为孩子出远门的安全而挂心，与“很”的修饰及句意相合。", "爱护": "配价：“爱护”的对象是人或物，不能接“我一个人出远门”这类事件作宾语。", "尊敬": "配价：“尊敬”要求以人为对象，不能接事件小句。", "嫉妒": "语义：“嫉妒”指对他人的优势心生不满，与母亲为孩子安全挂心的语境不符。"}, "sentence_index": 0, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全家人都在担忧老师的帮助。", "explanation": "这里应该用〈感谢〉。担忧表示担心会出坏事，对别人的帮助表示谢意应说感谢。"}, {"text": "我担忧这次比赛能顺利进行。", "explanation": "这里应该用〈盼望〉。担忧指担心坏事发生，希望事情顺利应当用盼望。"}, {"text": "我们担忧新来的客人光临。", "explanation": "这里应该用〈欢迎〉。担忧表示担心，不能用来表达对客人光临的欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：心里挂着事，与老人凝望窗外大雨的神情相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清扫的动作，不能用“地”修饰“看着”，与老人看雨的神情无关。"}, {"text": "拥抱", "is_correct": false, "explanation": "配价：“拥抱”的对象是人，不能用来描述老人看雨的动作。"}, {"text": "膜拜", "is_correct": false, "explanation": "语域：“膜拜”是宗教或仪式性用语，用来描述看雨显得很不自然。"}], "explanations": {"担忧": "担忧：心里挂着事，与老人凝望窗外大雨的神情相合。", "打扫": "语义：“打扫”是清扫的动作，不能用“地”修饰“看着”，与老人看雨的神情无关。", "拥抱": "配价：“拥抱”的对象是人，不能用来描述老人看雨的动作。", "膜拜": "语域：“膜拜”是宗教或仪式性用语，用来描述看雨显得很不自然。"}, "sentence_index": 6, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我担忧你生日快乐。", "explanation": "这里应该用〈祝〉。担忧指担心坏事会发生，表达生日的美好祝愿要用祝。"}, {"text": "我担忧你一路平安。", "explanation": "这里应该用〈祝福〉。担忧是担心会出事，给出行的人送去平安的祝愿应用祝福。"}, {"text": "大家都担忧他的诚实。", "explanation": "这里应该用〈赞美〉。担忧用于令人担心的事，称赞他人的品质应用赞美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶担忧得看着天气预报，怕我感冒。", "corrected_sentence": "奶奶担忧地看着天气预报，怕我感冒。", "error_description": "“担忧”在此修饰后面的动词“看着”，作状语，应用“地”连接，写作“担忧地看着”；“得”用于动词之后引出补语，不能接在“担忧”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在担忧过孩子的成绩，常常失眠。", "corrected_sentence": "她正在担忧着孩子的成绩，常常失眠。", "error_description": "“正在”表示动作正在进行，应与“着”搭配，不能与表示经历过的“过”同用；应把“过”改为“着”，写作“正在担忧着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
