INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "发愁，忧虑，不放心。", "primary_collocate": null, "pronunciation": "dān yōu", "ipa": "tan˥ joʊ˥", "syllable_count": 2, "sentences": [{"text": "失业以后，他整天担忧生活怎么办。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都担忧公司明年会不会赚钱。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为孩子的学习担忧了很久。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价这么高，年轻人担忧买不起房。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要为小事担忧，先吃饭吧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担忧着下个月的房租，睡不着觉。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母最担忧的是孩子找不到工作。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作还没有着落，他十分担忧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是担忧钱不够用。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们担忧过很多次，可是问题还在。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担忧了", "label": "了体标"}, {"form": "担忧着", "label": "着体标"}, {"form": "担忧过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "为生活工作等事发愁忧虑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d993711-fcb6-4ae5-84ed-b24535ccaac2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：对生活出路发愁、忧虑，与失业后整天发愁的语境相合。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”针对喜事，与失业后的忧虑正好相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的对象是人或活动，不能接“生活怎么办”这样的问题。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”用于人或作品，不说“赞美生活怎么办”。"}], "explanations": {"担忧": "担忧：对生活出路发愁、忧虑，与失业后整天发愁的语境相合。", "庆祝": "语义：“庆祝”针对喜事，与失业后的忧虑正好相反。", "欢迎": "配价：“欢迎”的对象是人或活动，不能接“生活怎么办”这样的问题。", "赞美": "搭配：“赞美”用于人或作品，不说“赞美生活怎么办”。"}, "sentence_index": 0, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都担忧明年的工资能涨一涨。", "explanation": "这里应该用〈期待〉。担忧表示担心不好的结果，工资上涨是值得期待的好事。"}, {"text": "他担忧朋友送的生日礼物。", "explanation": "这里应该用〈珍惜〉。担忧表示担心会出坏事，对朋友心意的重视应说珍惜。"}, {"text": "我们担忧你明年来公司实习。", "explanation": "这里应该用〈盼望〉。担忧表示担心，对对方来实习这件好事应用盼望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：为孩子找不到工作而发愁，与“最”和句中的担心语境相合。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”寄托的是好结果，与“找不到工作”这种坏情况相反。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的对象是人或帮助，不接“找不到工作”这样的情况。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”用于人、作品或优点，不用于“找不到工作”这类困境。"}], "explanations": {"担忧": "担忧：为孩子找不到工作而发愁，与“最”和句中的担心语境相合。", "盼望": "语义：“盼望”寄托的是好结果，与“找不到工作”这种坏情况相反。", "感谢": "配价：“感谢”的对象是人或帮助，不接“找不到工作”这样的情况。", "欣赏": "搭配：“欣赏”用于人、作品或优点，不用于“找不到工作”这类困境。"}, "sentence_index": 6, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我担忧孩子每天都健康快乐。", "explanation": "这里应该用〈希望〉。担忧指担心坏事会发生，对孩子健康快乐的美好期望应用希望。"}, {"text": "我们担忧新婚夫妇幸福美满。", "explanation": "这里应该用〈祝福〉。担忧是担心会出事，对新人幸福美满的良好祝愿应用祝福。"}, {"text": "老师担忧这次考试的进步。", "explanation": "这里应该用〈表扬〉。担忧用于令人担心的事，称赞学生的进步应用表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为房租担忧地睡不着觉。", "corrected_sentence": "他为房租担忧得睡不着觉。", "error_description": "“睡不着觉”是“担忧”的结果补语，需要用“得”连接，应为“担忧得睡不着觉”；用“地”会把“担忧”当作修饰语，句意不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在担忧了一个晚上，还是没想出办法。", "corrected_sentence": "他们担忧了一个晚上，还是没想出办法。", "error_description": "“正在”表示动作进行中，与表示完成的“了”矛盾；应去掉“正在”，写作“担忧了一个晚上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
