INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95863, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95863, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改名是把原来的名字换成新的名字。", "primary_collocate": null, "pronunciation": "gǎi míng", "ipa": "kai̯˨˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他不喜欢这个名字，想改名。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚以后，她决定改名。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友改名叫小海了。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店改名以后，生意好多了。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想改名，因为同学总笑他。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么要改名？", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改名要去派出所办手续。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她改名之后，大家都叫她新名字。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街改名了，现在叫中山路。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不同意我改名。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改了名", "label": "体标（了）"}, {"form": "改过名", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把原来的名字换成新的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95863, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改名", "is_correct": true, "explanation": "正确：“改名”指更换名字，符合“不喜欢这个名字”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“不喜欢这个名字”的原因无关，句子前后不连贯。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”与“不喜欢这个名字”的原因无关，句子前后不连贯。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热做饭，与“名字”的语义不合。"}], "explanations": {"改名": "正确：“改名”指更换名字，符合“不喜欢这个名字”的语境。", "吃": "语义：“吃”与“不喜欢这个名字”的原因无关，句子前后不连贯。", "穿": "语义：“穿”与“不喜欢这个名字”的原因无关，句子前后不连贯。", "煮": "语义：“煮”指用水加热做饭，与“名字”的语义不合。"}, "sentence_index": 0, "correct_answer": "改名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他辞职后改名做了老师。", "explanation": "这里应该用〈改行〉。改名指更换名字，换职业要说〈改行〉。"}, {"text": "这座旧楼改名以后很漂亮。", "explanation": "这里应该用〈改造〉。改名只更换名字，不能让建筑变漂亮；让旧楼变好看要说〈改造〉。"}, {"text": "这个月的天气改名了。", "explanation": "这里应该用〈变〉。改名只用于有名字的人或事物，天气没有名字，应说“变”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改名", "is_correct": true, "explanation": "正确：“改名”可以作主语，且与“办手续”的语境相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与去派出所办手续无关，句子不合逻辑。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与派出所办手续无关。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”必须带受事和接受者，单独作主语时语义不完整。"}], "explanations": {"改名": "正确：“改名”可以作主语，且与“办手续”的语境相符。", "吃饭": "语义：“吃饭”与去派出所办手续无关，句子不合逻辑。", "游泳": "语义：“游泳”与派出所办手续无关。", "送": "配价：“送”必须带受事和接受者，单独作主语时语义不完整。"}, "sentence_index": 6, "correct_answer": "改名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近空气质量改名了很多。", "explanation": "这里应该用〈改善〉。改名只更换名字，空气质量不能改名，应说〈改善〉。"}, {"text": "他临时改名说明天不去了。", "explanation": "这里应该用〈改口〉。改名指更换名字，不能用来表示改变说法。"}, {"text": "这辆车改名以后很酷。", "explanation": "这里应该用〈改装〉。改名只更换名字，不能让车变得更酷；改装才是改变车的部件或外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从国外回来后就了改名。", "corrected_sentence": "他从国外回来后就改了名。", "error_description": "了的位置错误：“改名”是离合词，“了”应放在“改”和“名”之间，应说“改了名”，不能放在“改名”前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候改名过。", "corrected_sentence": "我小时候改过名。", "error_description": "离合词错误：“改名”是离合词，“过”应放在“改”和“名”之间，应说“改过名”，不能说“改名过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
