INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "更改名字。", "primary_collocate": null, "pronunciation": "gǎi míng", "ipa": "kai̯˨˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "想改名的人要先填一张表。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外读书时改名，用了英文名。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王改名后，朋友们都不习惯。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校改名叫第一中学。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算明年改名。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改名是一件大事，要想清楚。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他改名是为了重新开始。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听说那位歌手改名了。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的名字不好听，妈妈带他去改名。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你改名的话，要先告诉家人。", "target_word": "改名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改了名", "label": "体标（了）"}, {"form": "改过名", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "更改人或事物的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改名", "is_correct": true, "explanation": "正确：“改名”作“想……的人”的谓语，符合填表的语境。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪，与填表无关，句子不合逻辑。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”指发怒，与填表无关，句子不合逻辑。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”需要带受事和处所，此处缺少宾语和地点。"}], "explanations": {"改名": "正确：“改名”作“想……的人”的谓语，符合填表的语境。", "哭": "语义：“哭”指流泪，与填表无关，句子不合逻辑。", "生气": "语义：“生气”指发怒，与填表无关，句子不合逻辑。", "放": "配价：“放”需要带受事和处所，此处缺少宾语和地点。"}, "sentence_index": 0, "correct_answer": "改名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她辞职后改名做了护士。", "explanation": "这里应该用〈改行〉。改名指更换名字，换职业要说〈改行〉。"}, {"text": "这个方法改名以后效果很好。", "explanation": "这里应该用〈改进〉。改名只更换名字，不能让方法的效果变好；改善方法要说〈改进〉。"}, {"text": "他临时改名说不去了。", "explanation": "这里应该用〈改口〉。改名指更换名字，不能用来表示改变说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改名", "is_correct": true, "explanation": "正确：“改名”作主语，表示目的的句子成立，符合句意。"}, {"text": "发火", "is_correct": false, "explanation": "语义：“发火”指发怒，与“重新开始”的意思不合。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”需要带受事（煮什么），单独作谓语时缺少宾语。"}, {"text": "教室", "is_correct": false, "explanation": "语法：“教室”是名词，不能作“他……”的谓语，句子不通。"}], "explanations": {"改名": "正确：“改名”作主语，表示目的的句子成立，符合句意。", "发火": "语义：“发火”指发怒，与“重新开始”的意思不合。", "煮": "配价：“煮”需要带受事（煮什么），单独作谓语时缺少宾语。", "教室": "语法：“教室”是名词，不能作“他……”的谓语，句子不通。"}, "sentence_index": 6, "correct_answer": "改名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩改名了许多。", "explanation": "这里应该用〈改善〉。改名只更换名字，成绩不能被改名，应说〈改善〉。"}, {"text": "这辆车改名以后很酷。", "explanation": "这里应该用〈改装〉。改名只更换名字，不能让车变酷；改装才是改变车的部件或外观。"}, {"text": "他的性格改名了很多。", "explanation": "这里应该用〈改变〉。改名只更换名字，性格不能改名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候改着两次名。", "corrected_sentence": "他小时候改过两次名。", "error_description": "体标错误：说过去的经历要用“过”，应说“改过两次名”，不能用表示持续的“着”说“改着两次名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅年轻时了改名。", "corrected_sentence": "我舅舅年轻时改了名。", "error_description": "了的位置错误：“了”应紧接在“改”之后，说“改了名”，不能放在“改名”前说“了改名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
