INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "景点是风景好、大家爱去看的地方。", "primary_collocate": null, "pronunciation": "jǐng diǎn", "ipa": "tɕiŋ˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "北京有很多有名的景点。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景点每天都有很多游客。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天去哪个景点玩？", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景点的门票只要三十块。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从酒店到景点坐地铁就行。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末景点里人太多，我不想去。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游带我们参观了三个景点。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西湖是杭州最有名的景点。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景点的风景特别美。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在手机上查了附近的景点。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "处", "label": "量词"}, {"form": "景點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "风景好、大家爱去看的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9cbe6ac-6e27-417b-92b2-2981f60beb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "景点", "is_correct": true, "explanation": "景点：风景好、供人游览的地方，正是这个词的意思。"}, {"text": "经典", "is_correct": false, "explanation": "声调不同：jīng（第一声）与 jǐng（第三声）声调不同，“经典”指有代表性、被推崇的作品或事物，不是游览地。"}, {"text": "顶点", "is_correct": false, "explanation": "声母不同：dǐng 与 jǐng 的声母 d 与 j 不同，“顶点”指最高处或发展的最高阶段。"}, {"text": "检点", "is_correct": false, "explanation": "韵尾不同：jiǎn 收 -n，jǐng 收 -ng，韵母 ian 与 ing 不同；“检点”指注意自己的言行，不是游览地。"}], "explanations": {"景点": "景点：风景好、供人游览的地方，正是这个词的意思。", "经典": "声调不同：jīng（第一声）与 jǐng（第三声）声调不同，“经典”指有代表性、被推崇的作品或事物，不是游览地。", "顶点": "声母不同：dǐng 与 jǐng 的声母 d 与 j 不同，“顶点”指最高处或发展的最高阶段。", "检点": "韵尾不同：jiǎn 收 -n，jǐng 收 -ng，韵母 ian 与 ing 不同；“检点”指注意自己的言行，不是游览地。"}, "sentence_index": null, "correct_answer": "景点"}, "level_3": {"options": [{"text": "景点", "is_correct": true, "explanation": "景点：风景好、大家爱去看的地方，与“北京”“有名”相符。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：“扫帚”是打扫用具，不是供人游览的地方。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“螺丝”是紧固件，不能说“有名的螺丝”。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：“抽屉”是家具的部件，不是可以游览的地方。"}], "explanations": {"景点": "景点：风景好、大家爱去看的地方，与“北京”“有名”相符。", "扫帚": "语义：“扫帚”是打扫用具，不是供人游览的地方。", "螺丝": "搭配：“螺丝”是紧固件，不能说“有名的螺丝”。", "抽屉": "语义：“抽屉”是家具的部件，不是可以游览的地方。"}, "sentence_index": 0, "correct_answer": "景点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去了一只景点。", "explanation": "这里应该用〈个〉。“只”多用于动物，景点是地方，不能用“只”来计量。"}, {"text": "这本景点很有名。", "explanation": "这里应该用〈个〉。“本”用于书籍等，景点不能用“本”来计量。"}, {"text": "我昨天吃了一个景点。", "explanation": "这里应该用〈苹果〉。“吃”的对象要用食物，景点是供人游览的地方，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景点", "is_correct": true, "explanation": "景点：风景好、供人游览的地方，与“导游带我们参观”相符。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：“饺子”是食物，不能被参观。"}, {"text": "药片", "is_correct": false, "explanation": "搭配：“参观”的对象是地方或场所，不能说参观药片。"}, {"text": "乌鸦", "is_correct": false, "explanation": "语义：“乌鸦”是鸟类，不是可以参观的地方。"}], "explanations": {"景点": "景点：风景好、供人游览的地方，与“导游带我们参观”相符。", "饺子": "语义：“饺子”是食物，不能被参观。", "药片": "搭配：“参观”的对象是地方或场所，不能说参观药片。", "乌鸦": "语义：“乌鸦”是鸟类，不是可以参观的地方。"}, "sentence_index": 6, "correct_answer": "景点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的景点定在体育馆。", "explanation": "这里应该用〈地点〉。景点专指风景优美、供人游览的地方，不用于比赛场所。"}, {"text": "我们坐了一辆景点。", "explanation": "这里应该用〈个〉。“辆”用于车辆，景点不能用“辆”来计量。"}, {"text": "这张景点很大。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，景点不能用“张”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只景点周末人特别多。", "corrected_sentence": "这个景点周末人特别多。", "error_description": "量词错误：“景点”应用“个”，“只”多用于动物，不能修饰景点。正确说法是“这个景点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些景点们都很美。", "corrected_sentence": "这些景点都很美。", "error_description": "“们”多用于指人的名词，“景点”指地方，不能加“们”。应说“这些景点都很美”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4694cb59-6c59-4bd2-8959-886ed3eb4448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
