INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机遇是一个很好的机会，正好让你碰上。", "primary_collocate": null, "pronunciation": "jī yù", "ipa": "tɕi˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "这次比赛是一个难得的机遇。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路上碰到了一个好机遇。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李抓住机遇，开了自己的店。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机遇来了，你一定要把握住。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到会遇到这样的机遇。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她错过了那次机遇，心里很难过。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好机遇不会一直等着你。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作对我来说是个大机遇。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师给了我一次学习的机遇。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正好碰上了出国的机遇。", "target_word": "机遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "機遇", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "恰好碰上的好机会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机遇", "is_correct": true, "explanation": "机遇：恰好碰上的好机会，与“难得的”搭配自然，句子通顺。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不是机会，不能用“难得的”来修饰，句子意思不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是机会，“这次比赛是一个难得的名字”意思不通。"}, {"text": "哨子", "is_correct": false, "explanation": "搭配：“难得的”一般修饰机会或事物，“哨子”与“难得的”不搭配，句子不通。"}], "explanations": {"机遇": "机遇：恰好碰上的好机会，与“难得的”搭配自然，句子通顺。", "脚步": "语义：脚步不是机会，不能用“难得的”来修饰，句子意思不通。", "名字": "语义：名字不是机会，“这次比赛是一个难得的名字”意思不通。", "哨子": "搭配：“难得的”一般修饰机会或事物，“哨子”与“难得的”不搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "机遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从这次比赛中学到了很多机遇。", "explanation": "这里应该用〈经验〉。机遇指恰好碰上的好机会，不能说“学到机遇”；学到的知识和体会要说〈经验〉。"}, {"text": "他练就了一身机遇，大家都很佩服。", "explanation": "这里应该用〈本领〉。机遇是外部的机会，不能“练就”；练就的是〈本领〉。"}, {"text": "他抓住了一把机遇。", "explanation": "量词：机遇是抽象的，不能用“把”。这里应该用〈次〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机遇", "is_correct": true, "explanation": "机遇：好的机会，与“好”搭配，且机会会等人，句子通顺。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“好”与“垃圾”意思矛盾，不能说“好垃圾”。"}, {"text": "病毒", "is_correct": false, "explanation": "搭配：“病毒”不能用“好”修饰，也不会一直等人，句子不通。"}, {"text": "灾难", "is_correct": false, "explanation": "搭配：“好灾难”自相矛盾，句子不通。"}], "explanations": {"机遇": "机遇：好的机会，与“好”搭配，且机会会等人，句子通顺。", "垃圾": "语义：“好”与“垃圾”意思矛盾，不能说“好垃圾”。", "病毒": "搭配：“病毒”不能用“好”修饰，也不会一直等人，句子不通。", "灾难": "搭配：“好灾难”自相矛盾，句子不通。"}, "sentence_index": 6, "correct_answer": "机遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他交了一个好机遇，常常一起吃饭。", "explanation": "这里应该用〈朋友〉。机遇指恰好碰上的好机会，不是人，不能说“交”。"}, {"text": "妈妈想出了一个好机遇，很快解决了问题。", "explanation": "这里应该用〈办法〉。机遇是机会，不能说“想出”；想出的是〈办法〉。"}, {"text": "他把机遇装进了箱子里。", "explanation": "语义：这里把机遇当成了可以装进箱子的实物。机遇指恰好碰上的好机会，是抽象的，不能说“装”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我抓住了一件机遇。", "corrected_sentence": "我抓住了一次机遇。", "error_description": "量词错误：「机遇」应搭配量词「次」，「件」多用于具体事物，不能用来修饰「机遇」。正确说法是「抓住了一次机遇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他错过着那次机遇，后来很后悔。", "corrected_sentence": "他错过了那次机遇，后来很后悔。", "error_description": "体貌错误：表示已经发生的“错过”要用“了”，不能用“着”。正确说法是“错过了那次机遇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95869, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有办法", "is_correct": true, "explanation": "反义：「有办法」与「没办法」相对，表示想得出解决的办法。"}, {"text": "答应", "is_correct": false, "explanation": "无关：「答应」表示同意去做，与想不出主意不构成反义。"}, {"text": "帮助", "is_correct": false, "explanation": "无关：「帮助」表示给予支持，与「想不出主意」没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：「思考」表示动脑筋想，与「没办法」并不相反。"}], "correct_answer": "有办法", "explanations": {"有办法": "反义：「有办法」与「没办法」相对，表示想得出解决的办法。", "答应": "无关：「答应」表示同意去做，与想不出主意不构成反义。", "帮助": "无关：「帮助」表示给予支持，与「想不出主意」没有反义关系。", "思考": "无关：「思考」表示动脑筋想，与「没办法」并不相反。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95869, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有办法", "is_correct": true, "explanation": "反义：「有办法」与「没办法」相对，表示想得出解决的办法。"}, {"text": "同意", "is_correct": false, "explanation": "无关：「同意」表示赞成或答应，与想不出主意不构成反义。"}, {"text": "决定", "is_correct": false, "explanation": "无关：「决定」表示作出选择，与「没办法」没有反义关系。"}, {"text": "解释", "is_correct": false, "explanation": "无关：「解释」表示说明道理，与想不出主意没有反义关系。"}], "correct_answer": "有办法", "explanations": {"有办法": "反义：「有办法」与「没办法」相对，表示想得出解决的办法。", "同意": "无关：「同意」表示赞成或答应，与想不出主意不构成反义。", "决定": "无关：「决定」表示作出选择，与「没办法」没有反义关系。", "解释": "无关：「解释」表示说明道理，与想不出主意没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95869, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没办法是不知道该怎么做，想不出主意。", "primary_collocate": null, "pronunciation": "méi bàn fǎ", "ipa": "mei˧˥ pan˥˩ fa˨˩˦", "syllable_count": 3, "sentences": [{"text": "这道题太难了，我真没办法。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个问题没办法，你帮帮我。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑坏了，我没办法修。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不说话，我也没办法猜。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我怎么做，我一下子没办法回答。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想帮他，可是没办法开口。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太复杂了，我实在没办法，你能帮帮我吗？", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着这个难题，大家都没办法。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器坏得很奇怪，我没办法，只好请人来看。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不吃饭，我没办法让他吃。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有办法", "label": "完整形式"}, {"form": "沒辦法", "label": "繁体"}], "register": "口语", "sense_fingerprint": "想不出主意，不知怎么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没办法", "is_correct": true, "explanation": "正确：「没办法」表示想不出解决的办法，与「这道题太难了」相合。"}, {"text": "没时间", "is_correct": false, "explanation": "语义：「没时间」说的是时间不够，与题目太难无关。"}, {"text": "没胃口", "is_correct": false, "explanation": "语义：「没胃口」说的是不想吃东西，与题目太难无关。"}, {"text": "没道理", "is_correct": false, "explanation": "搭配：「没道理」形容事情不合情理，不用来说自己想不出办法。"}], "explanations": {"没办法": "正确：「没办法」表示想不出解决的办法，与「这道题太难了」相合。", "没时间": "语义：「没时间」说的是时间不够，与题目太难无关。", "没胃口": "语义：「没胃口」说的是不想吃东西，与题目太难无关。", "没道理": "搭配：「没道理」形容事情不合情理，不用来说自己想不出办法。"}, "sentence_index": 0, "correct_answer": "没办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题很简单，我没办法做。", "explanation": "这里应该用〈会〉。「没办法」表示想不出办法，题目简单说明我知道怎么做，应说「我会做」。"}, {"text": "他已经把答案告诉我了，我没办法回答。", "explanation": "这里应该用〈知道〉。前一句已经给出答案，说明并非想不出办法，「没办法」与语境矛盾。"}, {"text": "这件事我能处理，我没办法处理。", "explanation": "这里应该用〈有办法〉。「没办法」表示想不出办法，而前半句说这件事有能力处理，两者相反，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没办法", "is_correct": true, "explanation": "正确：「没办法」表示想不出办法，与「问题太复杂」和「请你帮忙」相合。"}, {"text": "没兴趣", "is_correct": false, "explanation": "语义：「没兴趣」表示不喜欢，与请人帮忙的语境相悖。"}, {"text": "没心情", "is_correct": false, "explanation": "语义：「没心情」表示情绪不好，与「你能帮帮我吗」的求助不符。"}, {"text": "没胃口", "is_correct": false, "explanation": "语义：「没胃口」说的是不想吃东西，与请人帮忙解题的语境毫不相关。"}], "explanations": {"没办法": "正确：「没办法」表示想不出办法，与「问题太复杂」和「请你帮忙」相合。", "没兴趣": "语义：「没兴趣」表示不喜欢，与请人帮忙的语境相悖。", "没心情": "语义：「没心情」表示情绪不好，与「你能帮帮我吗」的求助不符。", "没胃口": "语义：「没胃口」说的是不想吃东西，与请人帮忙解题的语境毫不相关。"}, "sentence_index": 6, "correct_answer": "没办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的解法我已经全部想出来了，所以我没办法做。", "explanation": "这里用错了〈没办法〉：它表示想不出怎么做，而句中说解法已经全部想出，应表示〈已经会做〉，前后矛盾。"}, {"text": "这台机器的毛病我都查清楚了，所以我没办法修。", "explanation": "这里用错了〈没办法〉：它表示想不出怎么做，而句中说毛病已经查清，应表示〈知道怎么修〉，两者相反。"}, {"text": "电脑已经修好了，我没办法修。", "explanation": "这里不能用〈没办法〉，应表示有能力做到，即〈能〉。电脑已经修好，再说没办法修与事实矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没办法着，只能问老师。", "corrected_sentence": "我没办法，只能问老师。", "error_description": "体貌错误：「没办法」不能带体标「着」，应删去「着」。正确说法是「我没办法，只能问老师」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题我实在不没办法解决。", "corrected_sentence": "这个问题我实在没办法解决。", "error_description": "错误：「不没办法」。正确：「没办法」。多出的「不」形成双重否定，句意变得矛盾，母语者不这样说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95870, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有办法", "is_correct": true, "explanation": "反义：「有办法」与「没办法」相对，表示有解决问题的办法。"}, {"text": "出发", "is_correct": false, "explanation": "无关：「出发」表示动身，与「没办法」没有反义关系。"}, {"text": "同意", "is_correct": false, "explanation": "无关：「同意」表示赞成，与无计可施不构成反义。"}, {"text": "检查", "is_correct": false, "explanation": "无关：「检查」表示仔细查看，与「没办法」没有反义关系。"}], "correct_answer": "有办法", "explanations": {"有办法": "反义：「有办法」与「没办法」相对，表示有解决问题的办法。", "出发": "无关：「出发」表示动身，与「没办法」没有反义关系。", "同意": "无关：「同意」表示赞成，与无计可施不构成反义。", "检查": "无关：「检查」表示仔细查看，与「没办法」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95870, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有办法", "is_correct": true, "explanation": "反义：「有办法」与「没办法」相对，表示有解决问题的办法。"}, {"text": "散步", "is_correct": false, "explanation": "无关：「散步」表示随意走动，与「没办法」没有反义关系。"}, {"text": "陪伴", "is_correct": false, "explanation": "无关：「陪伴」表示与人相随，与「没办法」没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "无关：「参加」表示加入某项活动，与无计可施不构成反义。"}], "correct_answer": "有办法", "explanations": {"有办法": "反义：「有办法」与「没办法」相对，表示有解决问题的办法。", "散步": "无关：「散步」表示随意走动，与「没办法」没有反义关系。", "陪伴": "无关：「陪伴」表示与人相随，与「没办法」没有反义关系。", "参加": "无关：「参加」表示加入某项活动，与无计可施不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示事情无计可施，只能无可奈何地接受。", "primary_collocate": null, "pronunciation": "méi bàn fǎ", "ipa": "mei˧˥ pan˥˩ fa˨˩˦", "syllable_count": 3, "sentences": [{"text": "雨下得太大了，没办法出门。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情已经这样了，没办法。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没办法，我只好自己去。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏在路上，我们没办法，只能走回家。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不能回头，没办法改变过去。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司太忙，他没办法请假。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是规定，我也没办法。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没办法，谁让我是哥哥呢？", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机晚点了，大家都没办法。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太多，我没办法陪你去玩。", "target_word": "没办法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有办法", "label": "完整形式"}, {"form": "沒辦法", "label": "繁体"}], "register": "口语", "sense_fingerprint": "无计可施，只能接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0aa27f-22fc-4bb2-b50a-1b53150bdc16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没办法", "is_correct": true, "explanation": "正确：「没办法」表示无计可施，与「雨下得太大」这一原因相合。"}, {"text": "没意思", "is_correct": false, "explanation": "配价：「没意思」是形容词，不能直接带动词宾语「出门」。"}, {"text": "没规矩", "is_correct": false, "explanation": "搭配：「没规矩」形容人行为不端，不能用来解释因雨不能出门。"}, {"text": "没完", "is_correct": false, "explanation": "配价：「没完」作谓语不能直接带动词「出门」，组合不成立。"}], "explanations": {"没办法": "正确：「没办法」表示无计可施，与「雨下得太大」这一原因相合。", "没意思": "配价：「没意思」是形容词，不能直接带动词宾语「出门」。", "没规矩": "搭配：「没规矩」形容人行为不端，不能用来解释因雨不能出门。", "没完": "配价：「没完」作谓语不能直接带动词「出门」，组合不成立。"}, "sentence_index": 0, "correct_answer": "没办法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题我们已经有了三个解决办法，所以我们都没办法了。", "explanation": "这里用错了〈没办法〉：它表示无计可施，而前句说已有三个解决办法，应表示〈有办法〉，两者相反。"}, {"text": "我们手里有钱，没办法，可以打车回家。", "explanation": "前后矛盾：有钱可以打车，说明有办法，「没办法」与「可以打车」相矛盾。"}, {"text": "坐车回家很方便，我们没办法。", "explanation": "前后矛盾：句中说坐车很方便，已经有办法，不应说「没办法」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没办法", "is_correct": true, "explanation": "正确：「没办法」表示无计可施，只能接受规定，与句意相合。"}, {"text": "没关系", "is_correct": false, "explanation": "语义：「没关系」表示无妨，与「这是规定」的无奈语气不符。"}, {"text": "没胃口", "is_correct": false, "explanation": "语义：「没胃口」指不想吃东西，与「这是规定」的无奈语气无关。"}, {"text": "没面子", "is_correct": false, "explanation": "搭配：「没面子」指丢脸，不能用来表达对规定无计可施。"}], "explanations": {"没办法": "正确：「没办法」表示无计可施，只能接受规定，与句意相合。", "没关系": "语义：「没关系」表示无妨，与「这是规定」的无奈语气不符。", "没胃口": "语义：「没胃口」指不想吃东西，与「这是规定」的无奈语气无关。", "没面子": "搭配：「没面子」指丢脸，不能用来表达对规定无计可施。"}, "sentence_index": 6, "correct_answer": "没办法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工作很轻松，我没办法陪你去玩。", "explanation": "这里用错了〈没办法〉：它表示无计可施，而句中说工作很轻松，应表示〈有时间〉，两者相反，前后矛盾。"}, {"text": "我的假期很多，我没办法陪你去玩。", "explanation": "这里用错了〈没办法〉：它表示无计可施、只能接受，而假期很多，应表示〈有空〉，两者相反。"}, {"text": "我们都有空，我没办法陪你。", "explanation": "这里用错了〈没办法〉：它表示无法脱身，应表示〈有时间〉，句中说大家都空闲，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下这么大的雨，我们没办法着，只好待在家里。", "corrected_sentence": "下这么大的雨，我们没办法，只好待在家里。", "error_description": "体貌错误：「没办法」不能带体标「着」，应删去「着」。正确说法是「我们没办法，只好待在家里」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站的车都停运了，我不没办法，只能等。", "corrected_sentence": "车站的车都停运了，我没办法，只能等。", "error_description": "错误：「不没办法」。正确：「没办法」。多出的「不」形成双重否定，句意变得矛盾，母语者不这样说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f9f1d06-438c-450f-acc8-23dcf8dc232a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
