INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河水暴涨泛滥形成的大水。", "primary_collocate": null, "pronunciation": "hóng shuǐ", "ipa": "xʊŋ˧˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "今年夏天，南方发生了洪水。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水淹没了很多房子和农田。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水中，救援队用船救出了老人。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上下大雨，洪水很快冲下来。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在报道洪水的消息。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来的时候，河水高得吓人。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场洪水让几千人没有了家。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水冲坏了公路，车不能走了。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到雨季，人们都担心洪水。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水库能挡住洪水，保护下游的城市。", "target_word": "洪水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场洪水", "label": "量词"}, {"form": "一次洪水", "label": "量词"}, {"form": "洪水期", "label": "复合"}], "register": "中性", "sense_fingerprint": "河水暴涨泛滥形成的大水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洪水", "is_correct": true, "explanation": "正确：“发生”后接自然灾害，洪水符合句意。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“发生”指事件，饭菜不是事件。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“发生”一般搭配事件或灾害，不搭配手机。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是事件，南方不会发生黑板。"}], "explanations": {"洪水": "正确：“发生”后接自然灾害，洪水符合句意。", "饭菜": "语义：“发生”指事件，饭菜不是事件。", "手机": "搭配：“发生”一般搭配事件或灾害，不搭配手机。", "黑板": "语义：黑板不是事件，南方不会发生黑板。"}, "sentence_index": 0, "correct_answer": "洪水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洪水清澈见底，鱼在水里自由地游。", "explanation": "这里应该用〈溪水〉。洪水是浑浊的大水，不会清澈见底。"}, {"text": "这口井的洪水很甜，村里人每天都来打水。", "explanation": "这里应该用〈井水〉。洪水不从井里来，也不是甜的。"}, {"text": "屋檐下的洪水一滴一滴落下来。", "explanation": "这里应该用〈雨水〉。洪水是成片的大水，不会一滴一滴地从屋檐落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洪水", "is_correct": true, "explanation": "正确：洪水让几千人失去家园，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不会让几千人没有家。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“场”多修饰事件，不修饰桌子。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不会造成几千人无家可归。"}], "explanations": {"洪水": "正确：洪水让几千人失去家园，符合句意。", "作业": "语义：作业是学习任务，不会让几千人没有家。", "桌子": "搭配：量词“场”多修饰事件，不修饰桌子。", "课本": "语义：课本是书，不会造成几千人无家可归。"}, "sentence_index": 6, "correct_answer": "洪水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片洪水很咸，游泳时要小心。", "explanation": "这里应该用〈海水〉。洪水是河水暴涨泛滥形成的大水，不是海里的水，也不咸。"}, {"text": "村口的商店里卖洪水，很便宜。", "explanation": "这里应该用〈矿泉水〉。洪水是河水暴涨泛滥形成的大水，不是商店里卖的饮用水。"}, {"text": "洪水很新鲜，早上喝最好。", "explanation": "这里应该用〈牛奶〉。洪水是浑浊的大水，不新鲜，也不适合早上喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个月，一场洪水的冲坏了这条公路。", "corrected_sentence": "上个月，一场洪水冲坏了这条公路。", "error_description": "结构错误：“洪水”后面不能加“的”再接动词，应说“一场洪水冲坏了这条公路”，不能说“一场洪水的冲坏了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年，一条洪水把整个村子都淹了。", "corrected_sentence": "去年，一场洪水把整个村子都淹了。", "error_description": "量词错误：洪水应说“一场”，“条”多用于细长的东西，不能用于洪水。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
