INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95874, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "歌手当众演唱的音乐会。", "primary_collocate": null, "pronunciation": "yǎn chàng huì", "ipa": "jɛn˨˩˦ ʈʂʰaŋ˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "周末我去看了一场演唱会。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手明年要开演唱会。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会八点开始，我们早点出发吧。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了两张演唱会的票。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会上，歌迷一起唱起了歌。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次开演唱会，非常紧张。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会结束后，大家慢慢走出体育馆。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都去看一次演唱会。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场演唱会的门票很快就卖完了。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐地铁去体育馆看演唱会。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "个人演唱会", "label": "复合"}, {"form": "演唱會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "演唱会:歌手当众演唱的音乐会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演唱会", "is_correct": true, "explanation": "正确：演唱会是歌手唱歌给观众听的活动，量词用“场”。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“场”用于活动，报纸应以“份”计，“看了一场报纸”不成立。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是可以“去看”的活动，与“周末去看了”不相容。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学是机构，不是可以“去看”的一场活动。"}], "explanations": {"演唱会": "正确：演唱会是歌手唱歌给观众听的活动，量词用“场”。", "报纸": "搭配：“场”用于活动，报纸应以“份”计，“看了一场报纸”不成立。", "蛋糕": "语义：蛋糕不是可以“去看”的活动，与“周末去看了”不相容。", "大学": "语义：大学是机构，不是可以“去看”的一场活动。"}, "sentence_index": 0, "correct_answer": "演唱会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们听了交响乐团的演唱会。", "explanation": "这里应该用〈音乐会〉。演唱会指歌手的演出，乐团的演奏要说“音乐会”。"}, {"text": "这次演唱会的及格率很高。", "explanation": "这里应该用〈考试〉。演唱会是歌手的演出，没有“及格率”，及格率属于考试。"}, {"text": "这场演唱会由著名教授主讲。", "explanation": "这里应该用〈讲座〉。演唱会是歌手的演出，不能由人“主讲”，主讲是讲座的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演唱会", "is_correct": true, "explanation": "正确：演唱会结束后，观众陆续离场。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是可以“结束”的活动，与“走出体育馆”的场景不符。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能“结束”，与句意不相容。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：菜谱是书面材料，不能作“结束”的主语。"}], "explanations": {"演唱会": "正确：演唱会结束后，观众陆续离场。", "感冒": "语义：感冒是疾病，不是可以“结束”的活动，与“走出体育馆”的场景不符。", "沙发": "语义：沙发是家具，不能“结束”，与句意不相容。", "菜谱": "搭配：菜谱是书面材料，不能作“结束”的主语。"}, "sentence_index": 6, "correct_answer": "演唱会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演唱会的展台前排了很长的队。", "explanation": "这里应该用〈展览〉。展台属于展览，演唱会是歌手的演出，没有展台。"}, {"text": "这场演唱会只有钢琴独奏，没有歌手。", "explanation": "这里应该用〈音乐会〉。演唱会需要歌手演唱，只有独奏、没有歌手的演出应说“音乐会”。"}, {"text": "下午的演唱会我们讨论了预算。", "explanation": "这里应该用〈会议〉。演唱会是歌手的演出，不能用来讨论预算，讨论预算应说会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天看了一张演唱会。", "corrected_sentence": "我们昨天看了一场演唱会。", "error_description": "错误形式：“一张演唱会”；正确形式：“一场演唱会”。“张”用于票、纸等平面的东西，演唱会的量词是“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹昨天去看着一场演唱会。", "corrected_sentence": "我妹妹昨天去看了一场演唱会。", "error_description": "错误形式：“看着一场演唱会”；正确形式：“看了一场演唱会”。已完成的一次观看要用动态助词“了”，“着”表示动作持续进行，不用于昨天已发生的演出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有关", "is_correct": true, "explanation": "有关：与…有联系，是“无干”的反义词，符合“与…无干”的对立关系。"}, {"text": "辞职", "is_correct": false, "explanation": "辞职与“无干”没有对立关系，不是反义词。"}, {"text": "参加", "is_correct": false, "explanation": "参加与“无干”没有对立关系，不是反义词。"}, {"text": "决定", "is_correct": false, "explanation": "决定与“无干”没有对立关系，不是反义词。"}], "correct_answer": "有关", "explanations": {"有关": "有关：与…有联系，是“无干”的反义词，符合“与…无干”的对立关系。", "辞职": "辞职与“无干”没有对立关系，不是反义词。", "参加": "参加与“无干”没有对立关系，不是反义词。", "决定": "决定与“无干”没有对立关系，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
