INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "无干是和这件事没有关系。", "primary_collocate": null, "pronunciation": "wú gān", "ipa": "u˧˥ kan˥", "syllable_count": 2, "sentences": [{"text": "这个问题与天气无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事与旁人无干，请大家不要议论。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的错和别人无干，不用怪大家。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她离开公司，与你无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书与考试无干，你可以不看。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只想说，这件事跟孩子无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来当队长与我无干，我只管做好自己的事。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架，和我们无干，我们走吧。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事与学校无干，是家里的问题。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请放心，这次失败与你无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "和这件事没有关系，用来撇清责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1736f8c-b416-42c2-9d2b-c556b9cf59db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某人某事没有关联，是本题的正确答案。"}, {"text": "鱼干", "is_correct": false, "explanation": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），意思是“鱼干”（晒干或晾干的鱼），不是“无干”。"}, {"text": "无根", "is_correct": false, "explanation": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。"}, {"text": "五感", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）、gǎn（第三声）与 gān（第一声）声调不同，意思是“五感”（视、听、嗅、味、触五种感觉）。"}], "explanations": {"无干": "无干：与某人某事没有关联，是本题的正确答案。", "鱼干": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），意思是“鱼干”（晒干或晾干的鱼），不是“无干”。", "无根": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。", "五感": "wǔ（第三声）与 wú（第二声）、gǎn（第三声）与 gān（第一声）声调不同，意思是“五感”（视、听、嗅、味、触五种感觉）。"}, "sentence_index": null, "correct_answer": "无干"}, "level_3": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某事没有关系，符合“这个问题与天气没有关系”的句意。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”要求双方都是人，“这个问题”不能与“天气”见面。"}, {"text": "分手", "is_correct": false, "explanation": "语义：“分手”说关系断开，用在“这个问题”和“天气”之间说不通。"}, {"text": "相识", "is_correct": false, "explanation": "语义：“相识”说人与人互相认识，“这个问题”与“天气”不能相识。"}], "explanations": {"无干": "无干：与某事没有关系，符合“这个问题与天气没有关系”的句意。", "见面": "配价：“见面”要求双方都是人，“这个问题”不能与“天气”见面。", "分手": "语义：“分手”说关系断开，用在“这个问题”和“天气”之间说不通。", "相识": "语义：“相识”说人与人互相认识，“这个问题”与“天气”不能相识。"}, "sentence_index": 0, "correct_answer": "无干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湿毛巾还无干，先别拿走。", "explanation": "这里应该用〈没干〉。无干表示“与…没有关联”，不能用来说毛巾没有干。"}, {"text": "今天放假，我无干，只能在家躺着。", "explanation": "这里应该用〈没事干〉。无干表示与某事没有关联，不表示没有事情做。"}, {"text": "他一整天都无干，什么也不想做。", "explanation": "这里应该用〈没精神〉。无干表示“与…没有关联”，不能用来形容一个人没有精神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某人某事没有关联，是本题的正确答案。"}, {"text": "鱼竿", "is_correct": false, "explanation": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），gān 相同，意思是“鱼竿”（钓鱼用的竿子）。"}, {"text": "无根", "is_correct": false, "explanation": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。"}, {"text": "无感", "is_correct": false, "explanation": "gǎn（第三声）与 gān（第一声）声调不同，意思是“无感”（没有感觉、不在意）。"}], "explanations": {"无干": "无干：与某人某事没有关联，是本题的正确答案。", "鱼竿": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），gān 相同，意思是“鱼竿”（钓鱼用的竿子）。", "无根": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。", "无感": "gǎn（第三声）与 gān（第一声）声调不同，意思是“无感”（没有感觉、不在意）。"}, "sentence_index": null, "correct_answer": "无干"}, "level_3": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某人某事没有关联，符合“谁来当队长和我没有关系”的句意。"}, {"text": "相连", "is_correct": false, "explanation": "语义：“相连”说事物在空间或结构上连在一起，用来说“谁当队长”与“我”不合。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”要求双方都是人，且要成为配偶，“谁来当队长”与“我”之间说不通。"}, {"text": "同居", "is_correct": false, "explanation": "语义：“同居”说共同生活，与“谁来当队长”的语境完全不合。"}], "explanations": {"无干": "无干：与某人某事没有关联，符合“谁来当队长和我没有关系”的句意。", "相连": "语义：“相连”说事物在空间或结构上连在一起，用来说“谁当队长”与“我”不合。", "结婚": "配价：“结婚”要求双方都是人，且要成为配偶，“谁来当队长”与“我”之间说不通。", "同居": "语义：“同居”说共同生活，与“谁来当队长”的语境完全不合。"}, "sentence_index": 6, "correct_answer": "无干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路上堵车，让你久等了。——无干，我刚到。", "explanation": "这里应该用〈没关系〉。表示不介意、不要紧时要说没关系，无干不能用来回应对方的道歉。"}, {"text": "这件湿衬衫还无干，先别穿。", "explanation": "这里应该用〈没干〉。无干表示“与…没有关联”，不能用来说衣服没有干。"}, {"text": "这件事已经交给无干部门跟进了。", "explanation": "这里应该用〈有关〉。有关部门指与事情相关的机构，无干不能修饰“部门”，只能表示没有关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那件事无干，你别再来问了。", "corrected_sentence": "那件事与我无干，你别再来问了。", "error_description": "错误：省略了“与我”。正确：“与我无干”。“无干”前面要用“与…”引出关联的对象，不能单独说“无干”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱无干，你别替他着急。", "corrected_sentence": "这笔钱与你无干，你别替他着急。", "error_description": "错误：省略了“与你”。正确：“与你无干”。“无干”前面要用“与…”引出关联的对象，不能单独说“无干”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95877, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有线", "is_correct": true, "explanation": "正确：「有线」与「无线」互为反义，指靠线连接的。"}, {"text": "红", "is_correct": false, "explanation": "「红」是颜色词，与「无线」没有反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "「圆」是形状词，与「无线」没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "「慢」与「快」是反义，与「无线」没有反义关系。"}], "correct_answer": "有线", "explanations": {"有线": "正确：「有线」与「无线」互为反义，指靠线连接的。", "红": "「红」是颜色词，与「无线」没有反义关系。", "圆": "「圆」是形状词，与「无线」没有反义关系。", "慢": "「慢」与「快」是反义，与「无线」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95877, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有线", "is_correct": true, "explanation": "正确：「有线」与「无线」互为反义，指靠线连接的。"}, {"text": "白", "is_correct": false, "explanation": "「白」是颜色词，与「无线」没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "「高」是高度词，与「无线」没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "「整齐」形容排列或样子，与「无线」没有反义关系。"}], "correct_answer": "有线", "explanations": {"有线": "正确：「有线」与「无线」互为反义，指靠线连接的。", "白": "「白」是颜色词，与「无线」没有反义关系。", "高": "「高」是高度词，与「无线」没有反义关系。", "整齐": "「整齐」形容排列或样子，与「无线」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95877, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无线是不用线连着，也能用。", "primary_collocate": null, "pronunciation": "wú xiàn", "ipa": "u˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我买了一个无线耳机。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个无线鼠标很好用。", "target_word": "无线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家的无线键盘用了两年，一直没坏。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无线音箱不用插线，放哪儿都行。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我新买的吸尘器是无线的，打扫客厅很方便。", "target_word": "无线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢用无线话筒唱歌。", "target_word": "无线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台无线打印机放在客厅里。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门时我带着无线充电器。", "target_word": "无线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无线的东西方便，但是要充电。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想换一个无线门铃，不想拉线。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "無線", "label": "繁体"}, {"form": "无线网", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常设备不用线连接也能使用：无线耳机、无线鼠标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无线", "is_correct": true, "explanation": "正确：「无线耳机」指不用线连接的耳机，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，耳机不能是甜的，「我买了一个甜耳机」说不通。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：「害羞」形容人的心情，耳机不会害羞，句子说不通。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：「饱」用于吃饱、饱满等，不用来修饰耳机。"}], "explanations": {"无线": "正确：「无线耳机」指不用线连接的耳机，符合句意。", "甜": "语义：「甜」形容味道，耳机不能是甜的，「我买了一个甜耳机」说不通。", "害羞": "语义：「害羞」形容人的心情，耳机不会害羞，句子说不通。", "饱": "搭配：「饱」用于吃饱、饱满等，不用来修饰耳机。"}, "sentence_index": 0, "correct_answer": "无线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宇宙是无线的。", "explanation": "这里应该用〈无限〉。「无线」指不用线连接，表示没有界限要用「无限」。"}, {"text": "这根电线是无线的，可以直接插在插座上。", "explanation": "「无线」用于形容不用线连接的设备，电线本身就是线，不能说它无线，这里用法不对。"}, {"text": "我的心情很无线。", "explanation": "「无线」只形容设备的连接方式，不能用来形容心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无线", "is_correct": true, "explanation": "正确：「无线打印机」指不用线连接的打印机，放在客厅里符合句意。"}, {"text": "辣", "is_correct": false, "explanation": "语义：「辣」形容味道，打印机不能是辣的，句子说不通。"}, {"text": "懒", "is_correct": false, "explanation": "语义：「懒」形容人的性格，打印机不会懒，句子说不通。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：「湿」形容含水的状态，打印机一般不说湿。"}], "explanations": {"无线": "正确：「无线打印机」指不用线连接的打印机，放在客厅里符合句意。", "辣": "语义：「辣」形容味道，打印机不能是辣的，句子说不通。", "懒": "语义：「懒」形容人的性格，打印机不会懒，句子说不通。", "湿": "搭配：「湿」形容含水的状态，打印机一般不说湿。"}, "sentence_index": 6, "correct_answer": "无线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果是无线的，很好吃。", "explanation": "「无线」只形容不用线连接的设备，苹果不是设备，不能说它无线。"}, {"text": "我的耳朵是无线的，听得很清楚。", "explanation": "「无线」只形容设备的连接方式，不能用来形容人的身体部位。"}, {"text": "这台冰箱的温度很无线。", "explanation": "「无线」只形容设备的连接方式，不能用来形容温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种键盘是无线。", "corrected_sentence": "这种键盘是无线的。", "error_description": "错误：「无线」作表语时漏了「的」。正确说法是「这种键盘是无线的」，形容词作表语后面要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台很无线打印机很好用。", "corrected_sentence": "这台无线打印机很好用。", "error_description": "错误：「无线」前面加了程度副词「很」。「无线」是表示连接方式的属性词，不能受「很」修饰。正确说法是「这台无线打印机很好用」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95878, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有线", "is_correct": true, "explanation": "正确：「有线」与「无线」互为反义，指靠线路传送信号的。"}, {"text": "深", "is_correct": false, "explanation": "「深」是程度或深浅词，与「无线」没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "「轻」是重量词，与「无线」没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "「亮」是明暗词，与「无线」没有反义关系。"}], "correct_answer": "有线", "explanations": {"有线": "正确：「有线」与「无线」互为反义，指靠线路传送信号的。", "深": "「深」是程度或深浅词，与「无线」没有反义关系。", "轻": "「轻」是重量词，与「无线」没有反义关系。", "亮": "「亮」是明暗词，与「无线」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
