INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95878, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不用导线的；利用电波传送信号的。", "primary_collocate": null, "pronunciation": "wú xiàn", "ipa": "u˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "无线信号在空中传送。", "target_word": "无线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机用无线通信，不用电线。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种无线电话可以在山里用。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在学无线通信技术。", "target_word": "无线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "无线网络靠电波传送信号。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里没有无线信号，打不了电话。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察用无线对讲机联系同事。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无线广播不用电线，也能传到远方。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市有免费的无线网络覆盖。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机上不能使用无线通信设备。", "target_word": "无线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "無線", "label": "繁体"}, {"form": "无线电", "label": "复合"}], "register": "书面", "sense_fingerprint": "通信技术中利用电波传送信号：无线通信、无线信号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无线", "is_correct": true, "explanation": "正确：「无线信号」指利用电波传送的信号，与「在空中传送」相合。"}, {"text": "有线", "is_correct": false, "explanation": "语义：「有线信号」靠线路传送，不在空中传送，与句意矛盾。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」是形状词，信号不能是圆形的，句子说不通。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：「饱」用于吃饱、饱满等，不用来修饰信号。"}], "explanations": {"无线": "正确：「无线信号」指利用电波传送的信号，与「在空中传送」相合。", "有线": "语义：「有线信号」靠线路传送，不在空中传送，与句意矛盾。", "圆": "语义：「圆」是形状词，信号不能是圆形的，句子说不通。", "饱": "搭配：「饱」用于吃饱、饱满等，不用来修饰信号。"}, "sentence_index": 0, "correct_answer": "无线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电话线路是无线的，所以不用拉线。", "explanation": "这里应该用〈有线〉。电话线路靠线连接，说它无线与事实矛盾。"}, {"text": "时间是无线的。", "explanation": "这里应该用〈无限〉。「无线」指不用线连接，表示没有界限要用「无限」。"}, {"text": "他的声音很无线，大家都听得见。", "explanation": "「无线」只描述通信设备的连接方式，不能用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无线", "is_correct": true, "explanation": "正确：「无线对讲机」利用电波联系，符合句意。"}, {"text": "辣", "is_correct": false, "explanation": "语义：「辣」形容味道，对讲机不能是辣的，句子说不通。"}, {"text": "懒", "is_correct": false, "explanation": "语义：「懒」形容人的性格，对讲机不会懒，句子说不通。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：「瘦」一般形容人或动物，对讲机不说瘦。"}], "explanations": {"无线": "正确：「无线对讲机」利用电波联系，符合句意。", "辣": "语义：「辣」形容味道，对讲机不能是辣的，句子说不通。", "懒": "语义：「懒」形容人的性格，对讲机不会懒，句子说不通。", "瘦": "搭配：「瘦」一般形容人或动物，对讲机不说瘦。"}, "sentence_index": 6, "correct_answer": "无线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根网线是无线的，插在路由器上。", "explanation": "「无线」指不用线连接，网线本身就是线，说它无线与事实矛盾，这里用法不对。"}, {"text": "我的耳朵是无线的，听得很清楚。", "explanation": "「无线」只描述通信设备的连接方式，不能用来形容人的身体部位。"}, {"text": "他很无线地回答了问题。", "explanation": "「无线」是描述设备连接方式的形容词，不能修饰动词作状语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
