INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "价值高、稀少而宝贵。", "primary_collocate": null, "pronunciation": "zhēn guì", "ipa": "ʈʂən˥ kweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这件古画非常珍贵。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多珍贵的文物。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫是珍贵的动物。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片对我来说很珍贵。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶留下了一对珍贵的玉镯。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很珍贵，全世界只有三本。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的森林里有很多珍贵的树。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一份珍贵的礼物，我会好好收着。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料非常珍贵，请不要弄丢。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "珍贵的药材很难在市场上买到。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "价值高、稀少而宝贵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d993711-fcb6-4ae5-84ed-b24535ccaac2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "珍贵", "is_correct": true, "explanation": "珍贵修饰古画，表示价值高、稀少，符合句意。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”说能透光的东西，不能用来评价古画的价值。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”说空间、道路，不用来形容古画。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”说声音，不说画。"}], "explanations": {"珍贵": "珍贵修饰古画，表示价值高、稀少，符合句意。", "透明": "语义：“透明”说能透光的东西，不能用来评价古画的价值。", "狭窄": "搭配：“狭窄”说空间、道路，不用来形容古画。", "响亮": "搭配：“响亮”说声音，不说画。"}, "sentence_index": 0, "correct_answer": "珍贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种白菜很珍贵，菜市场随处都有。", "explanation": "这里应该用〈便宜〉。珍贵说稀少、价值高，普通蔬菜不能用珍贵形容。"}, {"text": "这种鸟很珍贵，公园里到处都是。", "explanation": "这里应该用〈常见〉。珍贵指稀少，常见的鸟不能用珍贵形容。"}, {"text": "这把塑料尺很珍贵，文具店里摆满了。", "explanation": "这里应该用〈常见〉。珍贵指稀少、值钱，文具店里摆满的塑料尺只能说常见，不能用珍贵形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "珍贵", "is_correct": true, "explanation": "珍贵修饰“树”，表示稀少、值钱，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”说刀具、刀口，不说树林里的树。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音或食物口感，不能修饰树。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，与树无关。"}], "explanations": {"珍贵": "珍贵修饰“树”，表示稀少、值钱，符合句意。", "锋利": "搭配：“锋利”说刀具、刀口，不说树林里的树。", "清脆": "语义：“清脆”形容声音或食物口感，不能修饰树。", "嘹亮": "语义：“嘹亮”形容声音，与树无关。"}, "sentence_index": 6, "correct_answer": "珍贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些废纸很珍贵，我们每天都扔进垃圾桶。", "explanation": "这里应该用〈常见〉。珍贵指稀少、值钱；每天随手扔进垃圾桶的废纸只能说常见，不能用珍贵形容。"}, {"text": "这把雨伞很珍贵，他每次下雨都把它丢在公园。", "explanation": "这里应该用〈普通〉。珍贵指稀少、值钱，常丢在公园的雨伞只能说普通。"}, {"text": "这盒火柴很珍贵，我们一天要用掉十盒。", "explanation": "这里应该用〈常用〉。珍贵指稀少，一天用掉十盒的火柴属于常用之物，不能用珍贵形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很珍贵这幅古画，不肯随便借人。", "corrected_sentence": "我很珍惜这幅古画，不肯随便借人。", "error_description": "“珍贵”是形容词，不能带宾语；表示爱惜的动作要用动词“珍惜”，应说“很珍惜这幅古画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那对玉镯很珍贵地，我们要好好收着。", "corrected_sentence": "那对玉镯很珍贵，我们要好好收着。", "error_description": "“珍贵”作谓语，后面的“地”多余。应说“很珍贵，我们要好好收着”，不能加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
