INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95881, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "生就是生下来就是这样的。", "primary_collocate": null, "pronunciation": "shēng jiù", "ipa": "ʂɤŋ˥ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他生就一副好嗓子。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子生就一张笑脸。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生就一个急性子。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生就一双大手。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫生就一身白毛。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟生就一副瘦小的身子。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生就一张圆脸。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王生就一双巧手。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子生就一副聪明相。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生就一副好身体。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "生下来就是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生就", "is_correct": true, "explanation": "“生就”表示生下来就具有，与“一副好嗓子”搭配，符合句中的语境。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”多搭配眼镜、手套等，不能与“嗓子”组合。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是用布除去污物，与“嗓子”的意思不合。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象应是可以洗的东西，与“好嗓子”无关。"}], "explanations": {"生就": "“生就”表示生下来就具有，与“一副好嗓子”搭配，符合句中的语境。", "戴": "搭配：“戴”多搭配眼镜、手套等，不能与“嗓子”组合。", "擦": "语义：“擦”是用布除去污物，与“嗓子”的意思不合。", "洗": "语义：“洗”的对象应是可以洗的东西，与“好嗓子”无关。"}, "sentence_index": 0, "correct_answer": "生就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的好嗓子是后天生就的，练了好几年才有。", "explanation": "这里应该用〈练就〉。生就指生下来就具有，与“后天”“练了好几年”矛盾；靠练习获得的要用“练就”。"}, {"text": "这位画家的画技是他在大学里生就的。", "explanation": "这里应该用〈学会〉。生就指天生具有，不能用于大学里的学习过程。"}, {"text": "他这身力气是后来干活时生就的。", "explanation": "这里应该用〈练出来〉。生就指生来具有，与“后来干活时”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生就", "is_correct": true, "explanation": "“生就”表示生来就是这样，与“一张圆脸”搭配，符合句中的语境。"}, {"text": "贴", "is_correct": false, "explanation": "语义：“贴”指把东西附着在表面，人的脸不能被“贴”。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂”多接颜料、油漆，不能与“圆脸”这样的形状搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“圆脸”的描述完全不合。"}], "explanations": {"生就": "“生就”表示生来就是这样，与“一张圆脸”搭配，符合句中的语境。", "贴": "语义：“贴”指把东西附着在表面，人的脸不能被“贴”。", "涂": "搭配：“涂”多接颜料、油漆，不能与“圆脸”这样的形状搭配。", "扔": "语义：“扔”是丢弃，与“圆脸”的描述完全不合。"}, "sentence_index": 6, "correct_answer": "生就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他生就一副好身体，是去年才开始锻炼出来的。", "explanation": "这里应该用〈练出来〉。生就指生来具有，与“去年才开始锻炼”矛盾。"}, {"text": "他生就一副好身体，是吃了很多补品才变成的。", "explanation": "这里应该用〈调养〉。生就指生来具有，与“吃了很多补品才变成的”矛盾。"}, {"text": "他生就一副好身体，是医生治好的。", "explanation": "这里应该用〈治疗〉。生就指生来具有，身体好是天生的，不能说是医生治疗后才有的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她生就过一双灵巧的手。", "corrected_sentence": "她生就一双灵巧的手。", "error_description": "体标用错：“生就”表示生来就具有，是一直存在的状态，不能加表示经历的“过”。应去掉“过”，改为“她生就一双灵巧的手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这孩子生就着一副好脾气。", "corrected_sentence": "这孩子生就一副好脾气。", "error_description": "体标用错：“生就”表示生来具有，不说“生就着”。应去掉“着”，改为“这孩子生就一副好脾气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
