INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95882, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "生来就具有，天生就是。", "primary_collocate": null, "pronunciation": "shēng jiù", "ipa": "ʂɤŋ˥ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "她生就一副好心肠。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李生就这样的脾气，别生气。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥生就一身好力气。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生就一副内向的性格。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹马生就四条长腿。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生就一双巧手。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生就一副当老师的样子。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子生就一双大眼睛。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗生就一身黄毛。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生就一头黑发。", "target_word": "生就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "生来就具有，天生如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生就", "is_correct": true, "explanation": "“生就”表示生来就具有，与“一副好心肠”搭配，符合句中的语境。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”是用手掌击打，与“心肠”的意思不合。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球或脚，不能与“一副心肠”搭配。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连接，不能用于性格或品质。"}], "explanations": {"生就": "“生就”表示生来就具有，与“一副好心肠”搭配，符合句中的语境。", "拍": "语义：“拍”是用手掌击打，与“心肠”的意思不合。", "踢": "搭配：“踢”的对象是球或脚，不能与“一副心肠”搭配。", "缝": "语义：“缝”指用针线连接，不能用于性格或品质。"}, "sentence_index": 0, "correct_answer": "生就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生就一副好口才，是练出来的。", "explanation": "这里应该用〈练就〉。生就指生来具有，与“练出来”矛盾。"}, {"text": "她生就一副好心肠，是后来慢慢培养的。", "explanation": "这里应该用〈养成〉。生就指生来具有，后来慢慢形成的品质应说“养成”，不能说生就。"}, {"text": "这匹马生就跑得快，是训练了两年才这样的。", "explanation": "这里应该用〈练出来〉。生就指生来具有，靠两年训练才有的速度应说“练出来”，不能说生就。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生就", "is_correct": true, "explanation": "“生就”表示生来如此，与“一副当老师的样子”搭配，符合句中的语境。"}, {"text": "割", "is_correct": false, "explanation": "语义：“割”指切断，与“样子”的意思不合。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”指长时间煮或忍耐，不能与“样子”搭配。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”多接地面、灰尘等，不能与“样子”组合。"}], "explanations": {"生就": "“生就”表示生来如此，与“一副当老师的样子”搭配，符合句中的语境。", "割": "语义：“割”指切断，与“样子”的意思不合。", "熬": "语义：“熬”指长时间煮或忍耐，不能与“样子”搭配。", "扫": "搭配：“扫”多接地面、灰尘等，不能与“样子”组合。"}, "sentence_index": 6, "correct_answer": "生就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她生就一头黑发，是后来染成的。", "explanation": "这里矛盾：生就指生来如此，黑发本色是天生的，不能说后来染成。应删去“是后来染成的”。"}, {"text": "她生就一头黑发，是去年才留起来的。", "explanation": "这里应该用〈留长〉。生就指生来如此，头发是后来留长的，不能说生就。"}, {"text": "这只小狗生就一身白毛，是染的。", "explanation": "这里应该用〈染成〉。生就指生来如此，颜色是人为染成的，不能说生就。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟生就过一副好歌喉。", "corrected_sentence": "我弟弟生就一副好歌喉。", "error_description": "体标用错：“生就”表示生来就具有，是一直存在的状态，不能加表示经历的“过”。应去掉“过”，改为“我弟弟生就一副好歌喉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐生就着一副好记性。", "corrected_sentence": "姐姐生就一副好记性。", "error_description": "体标用错：“生就”表示生来具有，不说“生就着”。应去掉“着”，改为“姐姐生就一副好记性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95883, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夜晚", "is_correct": true, "explanation": "反义：“夜晚”与“白天”相对，指天黑的时段。"}, {"text": "早晨", "is_correct": false, "explanation": "“早晨”是白天的一部分，与“白天”不构成反义。"}, {"text": "中午", "is_correct": false, "explanation": "“中午”也在白天之内，与“白天”不构成反义。"}, {"text": "清晨", "is_correct": false, "explanation": "“清晨”是白天开始的时段，与“白天”不构成反义。"}], "correct_answer": "夜晚", "explanations": {"夜晚": "反义：“夜晚”与“白天”相对，指天黑的时段。", "早晨": "“早晨”是白天的一部分，与“白天”不构成反义。", "中午": "“中午”也在白天之内，与“白天”不构成反义。", "清晨": "“清晨”是白天开始的时段，与“白天”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95883, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夜晚", "is_correct": true, "explanation": "反义：“夜晚”与“白天”相对，指天黑的时段。"}, {"text": "上午", "is_correct": false, "explanation": "“上午”是白天的一部分，与“白天”不构成反义。"}, {"text": "正午", "is_correct": false, "explanation": "“正午”在白天之内，与“白天”不构成反义。"}, {"text": "午后", "is_correct": false, "explanation": "“午后”在白天之内，与“白天”不构成反义。"}], "correct_answer": "夜晚", "explanations": {"夜晚": "反义：“夜晚”与“白天”相对，指天黑的时段。", "上午": "“上午”是白天的一部分，与“白天”不构成反义。", "正午": "“正午”在白天之内，与“白天”不构成反义。", "午后": "“午后”在白天之内，与“白天”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95883, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "白天是有太阳、天亮的时候。", "primary_collocate": null, "pronunciation": "bái tiān", "ipa": "pai˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "白天有太阳，晚上有月亮。", "target_word": "白天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我白天上班，晚上回家。", "target_word": "白天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天白天很长，晚上很短。", "target_word": "白天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "白天太热，我们晚上再出去。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他白天睡觉，晚上工作。", "target_word": "白天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "白天的时候，街上人很多。", "target_word": "白天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天白天短，天黑得早。", "target_word": "白天", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子白天在学校，我很放心。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白天开着灯太浪费了。", "target_word": "白天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们白天去公园，晚上看电影。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大白天", "label": "复合"}], "register": "口语", "sense_fingerprint": "日常口语中与晚上相对、有太阳天亮的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”指天黑的时段，“夜晚有太阳”与句意矛盾。"}, {"text": "白天", "is_correct": true, "explanation": "正确：“白天”指有太阳、天亮的时候，与“晚上有月亮”相对。"}, {"text": "黑夜", "is_correct": false, "explanation": "搭配：“黑夜”指漆黑的夜间，不能与“有太阳”搭配。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：“午夜”是深夜的时刻，与“有太阳”矛盾。"}], "explanations": {"夜晚": "语义：“夜晚”指天黑的时段，“夜晚有太阳”与句意矛盾。", "白天": "正确：“白天”指有太阳、天亮的时候，与“晚上有月亮”相对。", "黑夜": "搭配：“黑夜”指漆黑的夜间，不能与“有太阳”搭配。", "午夜": "语义：“午夜”是深夜的时刻，与“有太阳”矛盾。"}, "sentence_index": 0, "correct_answer": "白天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "白天好，王老师！", "explanation": "这里应该用〈下午〉。问候要说“下午好”，“白天好”不是问候用语。"}, {"text": "白天天上有很多星星和月亮。", "explanation": "这里应该用〈夜里〉。白天有太阳，天上看不到很多星星，星星是夜里才看得到的。"}, {"text": "我们白天吃夜宵吧。", "explanation": "这里应该用〈夜里〉。“夜宵”指深夜吃的小吃，白天不说吃夜宵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夏天", "is_correct": false, "explanation": "搭配：“冬天”后面不能再接“夏天”，两个季节叠用不搭配。"}, {"text": "白天", "is_correct": true, "explanation": "正确：“冬天白天短”指冬季白昼时间短，与“天黑得早”相符。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：“冬天深夜短”与“天黑得早”矛盾，夜晚应当更长。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：“冬天半夜短”与“天黑得早”矛盾，冬夜是长的。"}], "explanations": {"夏天": "搭配：“冬天”后面不能再接“夏天”，两个季节叠用不搭配。", "白天": "正确：“冬天白天短”指冬季白昼时间短，与“天黑得早”相符。", "深夜": "语义：“冬天深夜短”与“天黑得早”矛盾，夜晚应当更长。", "半夜": "语义：“冬天半夜短”与“天黑得早”矛盾，冬夜是长的。"}, "sentence_index": 6, "correct_answer": "白天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我白天上夜班。", "explanation": "这里应该用〈深夜〉。夜班是在夜间值的班，“白天”与“夜班”矛盾。"}, {"text": "他上白天，晚上回家。", "explanation": "这里应该用〈白班〉。上白班是固定说法，“上白天”不能这样说。"}, {"text": "天黑了，白天来了。", "explanation": "这里应该用〈夜晚〉。天黑以后是夜晚，不是白天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "白天上，院子里很安静。", "corrected_sentence": "白天，院子里很安静。", "error_description": "“白天”可以直接作时间状语，后面不能加方位词“上”。应说“白天，院子里很安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我整白天都在工作。", "corrected_sentence": "我整个白天都在工作。", "error_description": "“整”后要加量词“个”，应说“整个白天”，漏掉“个”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
