INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从日出到日落天亮的这段时间。", "primary_collocate": null, "pronunciation": "bái tiān", "ipa": "pai˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "白天是从日出到日落的时间。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春分那天，白天和黑夜一样长。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北极夏天几乎整天都是白天。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏至这天，白天最长，夜里最短。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳升起后，白天就开始了。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白天的温度比夜里高很多。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鸟白天休息，夜里出来找吃的。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日落以后，白天就结束了。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬至那天，白天只有九个小时。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白天看不到星星，因为太阳太亮。", "target_word": "白天", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大白天", "label": "复合"}], "register": "中性", "sense_fingerprint": "从日出到日落这一段时间，指昼夜中的昼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜晚", "is_correct": false, "explanation": "语义：“从日出到日落的时间”是白天，“夜晚”正相反，定义不符。"}, {"text": "白天", "is_correct": true, "explanation": "正确：“白天”指从日出到日落天亮的这段时间，符合定义。"}, {"text": "黑夜", "is_correct": false, "explanation": "语义：“黑夜”是日落后的时段，与“从日出到日落”的定义相反。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：“午夜”是深夜的时刻，不是从日出到日落的时间。"}], "explanations": {"夜晚": "语义：“从日出到日落的时间”是白天，“夜晚”正相反，定义不符。", "白天": "正确：“白天”指从日出到日落天亮的这段时间，符合定义。", "黑夜": "语义：“黑夜”是日落后的时段，与“从日出到日落”的定义相反。", "午夜": "语义：“午夜”是深夜的时刻，不是从日出到日落的时间。"}, "sentence_index": 0, "correct_answer": "白天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她下周上白天。", "explanation": "这里应该用〈白班〉。上班次要说“上白班”，“上白天”不这样说。"}, {"text": "白天有二十四小时。", "explanation": "这里应该用〈一天〉。“白天”只指日出到日落的时段，不能指一整天的二十四小时。"}, {"text": "白天好，各位同学！", "explanation": "这里应该用〈下午〉。问候要说“下午好”，“白天好”不是问候用语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半夜", "is_correct": false, "explanation": "语义：“半夜休息”与“夜里出来”同在夜间，形不成对比。"}, {"text": "白天", "is_correct": true, "explanation": "正确：“白天休息，夜里出来找吃的”形成昼夜对比，符合句意。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：“深夜休息”与“夜里出来找吃的”同在夜间，句意矛盾。"}, {"text": "夜间", "is_correct": false, "explanation": "语义：“夜间休息”与“夜里出来”同在夜间，无法与“白天”形成对比。"}], "explanations": {"半夜": "语义：“半夜休息”与“夜里出来”同在夜间，形不成对比。", "白天": "正确：“白天休息，夜里出来找吃的”形成昼夜对比，符合句意。", "深夜": "语义：“深夜休息”与“夜里出来找吃的”同在夜间，句意矛盾。", "夜间": "语义：“夜间休息”与“夜里出来”同在夜间，无法与“白天”形成对比。"}, "sentence_index": 6, "correct_answer": "白天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他白天值夜班。", "explanation": "这里应该用〈深夜〉。夜班是在夜间值的班，“白天”与“夜班”矛盾。"}, {"text": "他常做白天梦。", "explanation": "这里应该用〈白日〉。固定说法是“白日梦”，“白天梦”不成词。"}, {"text": "白天好，老师们！", "explanation": "这里应该用〈晚上〉。问候要说“晚上好”，“白天好”不是问候用语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的白天过很快。", "corrected_sentence": "我的白天过得很快。", "error_description": "“过”后作程度补语要用“得”，应说“过得很快”，漏掉“得”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我整白天都在屋里看书。", "corrected_sentence": "我整个白天都在屋里看书。", "error_description": "“整”后要加量词“个”，应说“整个白天”，漏掉“个”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
