INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "真人是真的人，不是画出来的，也不是假的。", "primary_collocate": null, "pronunciation": "zhēn rén", "ipa": "ʈʂən˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影里有真人，也有动画。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的小孩是真人，不是画的。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里的人物看起来很像真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看真人演的电影，不想看动画片。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人做得太逼真了，我差点以为它是真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩偶做得太像了，像真人一样。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的那个人很逼真，我走近才发现不是真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起动画，我更喜欢看真人演的戏。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩站在那里不动，我以为他不是真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，网上聊天的人不一定是真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "真实存在的人，不是画的也不是假的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1736f8c-b416-42c2-9d2b-c556b9cf59db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真人", "is_correct": true, "explanation": "真人：真实存在的人，不是画出来的，也不是假的，是本题的正确答案。"}, {"text": "整人", "is_correct": false, "explanation": "zhěng（第三声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“整人”（捉弄、折磨别人）。"}, {"text": "神人", "is_correct": false, "explanation": "shén（第二声）与 zhēn（第一声）声母不同（sh 与 zh）且声调不同，意思是“神人”（超乎常人的人）。"}, {"text": "正人", "is_correct": false, "explanation": "zhèng（第四声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“正人”（正直的人）。"}], "explanations": {"真人": "真人：真实存在的人，不是画出来的，也不是假的，是本题的正确答案。", "整人": "zhěng（第三声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“整人”（捉弄、折磨别人）。", "神人": "shén（第二声）与 zhēn（第一声）声母不同（sh 与 zh）且声调不同，意思是“神人”（超乎常人的人）。", "正人": "zhèng（第四声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“正人”（正直的人）。"}, "sentence_index": null, "correct_answer": "真人"}, "level_3": {"options": [{"text": "真人", "is_correct": true, "explanation": "真人：真实存在的人，与“动画”相对，符合“这部电影里有真人，也有动画”的句意。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：“白菜”不是电影中可以与“动画”并列的一类内容，句意说不通。"}, {"text": "手表", "is_correct": false, "explanation": "语义：“手表”不是电影的组成类别，与“也有动画”并列说不通。"}, {"text": "棋子", "is_correct": false, "explanation": "搭配：“有…也有动画”要求并列的是影像类别，“棋子”不能与“动画”并列。"}], "explanations": {"真人": "真人：真实存在的人，与“动画”相对，符合“这部电影里有真人，也有动画”的句意。", "白菜": "语义：“白菜”不是电影中可以与“动画”并列的一类内容，句意说不通。", "手表": "语义：“手表”不是电影的组成类别，与“也有动画”并列说不通。", "棋子": "搭配：“有…也有动画”要求并列的是影像类别，“棋子”不能与“动画”并列。"}, "sentence_index": 0, "correct_answer": "真人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧组请来了一部真人，专门演那个老爷爷。", "explanation": "这里应该用〈位〉或〈个〉。真人指人，量词“部”用于电影、书等，不能用于真人。"}, {"text": "他对她的感情是真人的，不是装的。", "explanation": "这里应该用〈真实〉。真人指真实存在的人，不能用来修饰感情。"}, {"text": "这只小狗是真人，很聪明。", "explanation": "这里应该用〈动物〉。真人只指真实存在的人，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真人", "is_correct": true, "explanation": "真人：真实存在的人，符合“我走近才发现不是真人”的句意。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“墙上的那个人”不可能是猫，“我走近才发现不是猫”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“墙上的那个人”和窗户不是同类事物，“不是窗户”与句子的语境不合。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“不是数字”一般不用来描述一个人，“数字”与“那个人”搭配不当。"}], "explanations": {"真人": "真人：真实存在的人，符合“我走近才发现不是真人”的句意。", "猫": "语义：“墙上的那个人”不可能是猫，“我走近才发现不是猫”说不通。", "窗户": "语义：“墙上的那个人”和窗户不是同类事物，“不是窗户”与句子的语境不合。", "数字": "搭配：“不是数字”一般不用来描述一个人，“数字”与“那个人”搭配不当。"}, "sentence_index": 6, "correct_answer": "真人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画是真人，线条很细。", "explanation": "这里应该用〈作品〉。真人指真实存在的人，不能用来指一幅画。"}, {"text": "这部动画的角色都是真人，很可爱。", "explanation": "这里应该用〈人物〉。动画里的人物是画出来的，不是真人。"}, {"text": "我家的鹦鹉是真人，很会说话。", "explanation": "这里应该用〈动物〉。真人只指真实存在的人，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "剧组请来一只真人，演那个老爷爷。", "corrected_sentence": "剧组请来一位真人，演那个老爷爷。", "error_description": "错误：量词“只”。正确：“位”。“只”用于动物，“真人”指人，要用“位”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个站在门口的人真人，不是模特。", "corrected_sentence": "那个站在门口的人是真人，不是模特。", "error_description": "错误：漏了“是”。正确：“是真人”。真人作谓语时要用“是”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95887, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "假意", "is_correct": true, "explanation": "正确答案。假意指虚假的心意，与“真心”相对，是这一义项的反义词。"}, {"text": "随便", "is_correct": false, "explanation": "表示不加考虑、不加限制，与“真心”的意思没有反义关系。"}, {"text": "慢慢", "is_correct": false, "explanation": "表示速度缓慢，与“真心”的心意无关，没有反义关系。"}, {"text": "轻易", "is_correct": false, "explanation": "表示不费力、不慎重，与“真心”没有反义关系。"}], "correct_answer": "假意", "explanations": {"假意": "正确答案。假意指虚假的心意，与“真心”相对，是这一义项的反义词。", "随便": "表示不加考虑、不加限制，与“真心”的意思没有反义关系。", "慢慢": "表示速度缓慢，与“真心”的心意无关，没有反义关系。", "轻易": "表示不费力、不慎重，与“真心”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95887, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "假意", "is_correct": true, "explanation": "正确答案。假意指虚假的心意，与“真心”相对，是这一义项的反义词。"}, {"text": "偶尔", "is_correct": false, "explanation": "表示间隔很久才发生一次，与“真心”的心意无关，没有反义关系。"}, {"text": "悄悄", "is_correct": false, "explanation": "表示不让人知道地进行，与“真心”没有反义关系。"}, {"text": "匆匆", "is_correct": false, "explanation": "表示急忙的样子，与“真心”没有反义关系。"}], "correct_answer": "假意", "explanations": {"假意": "正确答案。假意指虚假的心意，与“真心”相对，是这一义项的反义词。", "偶尔": "表示间隔很久才发生一次，与“真心”的心意无关，没有反义关系。", "悄悄": "表示不让人知道地进行，与“真心”没有反义关系。", "匆匆": "表示急忙的样子，与“真心”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95887, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "真心是心里真的这样想，不骗人。", "primary_collocate": null, "pronunciation": "zhēn xīn", "ipa": "ʈʂən˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "我真心喜欢这份工作。", "target_word": "真心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她真心想帮你，你别误会。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真心地向我道了歉。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我真心希望你明年能来看我。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友生病了，大家都真心地关心他。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真心觉得这个办法不错。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我真心感谢你昨天帮了我。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师真心为学生的进步高兴。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真心想学，我现在就教你。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真心不想去，所以没有答应。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "真心地", "label": "状语形式"}, {"form": "真心话", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里真的这样想，修饰动作，表示不是假装", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。真心（zhēn xīn）：心里真的这样想，不骗人。"}, {"text": "身心", "is_correct": false, "explanation": "shēn xīn 与 zhēn xīn 声母不同（sh 与 zh），声调相同，意思是身体和心灵。"}, {"text": "中心", "is_correct": false, "explanation": "zhōng xīn 与 zhēn xīn 韵母不同（ong 与 en），声调相同，意思是中央、核心。"}, {"text": "珍惜", "is_correct": false, "explanation": "zhēn xī 比 zhēn xīn 少了末尾的 n，声调相同，意思是珍惜、爱惜。"}], "explanations": {"真心": "正确答案。真心（zhēn xīn）：心里真的这样想，不骗人。", "身心": "shēn xīn 与 zhēn xīn 声母不同（sh 与 zh），声调相同，意思是身体和心灵。", "中心": "zhōng xīn 与 zhēn xīn 韵母不同（ong 与 en），声调相同，意思是中央、核心。", "珍惜": "zhēn xī 比 zhēn xīn 少了末尾的 n，声调相同，意思是珍惜、爱惜。"}, "sentence_index": null, "correct_answer": "真心"}, "level_3": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。“真心”作状语修饰“喜欢”，表示心里真的喜欢，符合句意。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”表示不热情，与“喜欢”的感情相矛盾。"}, {"text": "虚心", "is_correct": false, "explanation": "搭配：“虚心”修饰接受意见、学习的态度，不能修饰“喜欢”。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容态度庄重，与“喜欢”这种轻松的感情不符。"}], "explanations": {"真心": "正确答案。“真心”作状语修饰“喜欢”，表示心里真的喜欢，符合句意。", "冷淡": "语义：“冷淡”表示不热情，与“喜欢”的感情相矛盾。", "虚心": "搭配：“虚心”修饰接受意见、学习的态度，不能修饰“喜欢”。", "严肃": "语义：“严肃”形容态度庄重，与“喜欢”这种轻松的感情不符。"}, "sentence_index": 0, "correct_answer": "真心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他真心地骗了我，还说是为我好。", "explanation": "这里应该用〈故意〉。“真心”表示心里真的这样想、不骗人，与“骗”的意思相矛盾，不能修饰欺骗的行为。"}, {"text": "他真心地摔倒在路上。", "explanation": "这里应该用〈不小心〉。“真心地”只修饰出于本意的动作，“摔倒”是无意发生的，不能用“真心地”修饰。"}, {"text": "我去超市的时候真心买了牛奶。", "explanation": "这里应该用〈顺便〉。“真心”表示心里真的这样想，不能表示在做别的事时附带完成某事；这个意思要用“顺便”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95887, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。真心（zhēn xīn）：心里真的这样想，不骗人。"}, {"text": "真香", "is_correct": false, "explanation": "zhēn xiāng 与 zhēn xīn 韵母不同（iang 与 in），声调相同，意思是很香。"}, {"text": "真金", "is_correct": false, "explanation": "zhēn jīn 与 zhēn xīn 第二个字声母不同（j 与 x），声调相同，意思是纯金。"}, {"text": "振兴", "is_correct": false, "explanation": "zhèn xīng 与 zhēn xīn 第一个字声调不同，第二个字韵母不同（ing 与 in），意思是使兴盛起来。"}], "explanations": {"真心": "正确答案。真心（zhēn xīn）：心里真的这样想，不骗人。", "真香": "zhēn xiāng 与 zhēn xīn 韵母不同（iang 与 in），声调相同，意思是很香。", "真金": "zhēn jīn 与 zhēn xīn 第二个字声母不同（j 与 x），声调相同，意思是纯金。", "振兴": "zhèn xīng 与 zhēn xīn 第一个字声调不同，第二个字韵母不同（ing 与 in），意思是使兴盛起来。"}, "sentence_index": null, "correct_answer": "真心"}, "level_3": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。“真心”作状语修饰“感谢”，表示心里真的感激，符合句意。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”表示不关心、没有热情，与“感谢”的情感相矛盾。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：“粗鲁”是态度不礼貌，与“感谢”的礼貌态度相冲突。"}, {"text": "马虎", "is_correct": false, "explanation": "搭配：“马虎”描写做事不认真，不能修饰“感谢”。"}], "explanations": {"真心": "正确答案。“真心”作状语修饰“感谢”，表示心里真的感激，符合句意。", "冷漠": "语义：“冷漠”表示不关心、没有热情，与“感谢”的情感相矛盾。", "粗鲁": "语义：“粗鲁”是态度不礼貌，与“感谢”的礼貌态度相冲突。", "马虎": "搭配：“马虎”描写做事不认真，不能修饰“感谢”。"}, "sentence_index": 6, "correct_answer": "真心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个真心的情况。", "explanation": "这里应该用〈真实〉。“真心”指心里真的这样想，只修饰人的动作或心意，不能修饰“情况”这类事物。"}, {"text": "这道题真心地难。", "explanation": "这里应该用〈真的〉。“真心”修饰的是人的心意或动作，不能用来表示事情的程度；表示程度要用“真的”。"}, {"text": "他真心地忘了带钥匙。", "explanation": "这里应该用〈不留神〉。“真心地”只修饰出于本意的动作，“忘了”是无意的，不能用“真心地”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她真心得为朋友感到高兴。", "corrected_sentence": "她真心地为朋友感到高兴。", "error_description": "“真心”作状语修饰动词时要用“地”，不能用“得”，应说“真心地为朋友感到高兴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子真心了喜欢画画。", "corrected_sentence": "孩子真心地喜欢画画。", "error_description": "“真心”作状语修饰“喜欢”时要用“地”，不能用“了”，应说“孩子真心地喜欢画画”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
