INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真诚的心意；诚心诚意。", "primary_collocate": null, "pronunciation": "zhēn xīn", "ipa": "ʈʂən˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他用真心对待每一个朋友。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对你的一片真心，你要珍惜。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真心换真心，大家才会成为好朋友。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你，我感受到了你的真心。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他送的花虽然很便宜，但是有一份真心。", "target_word": "真心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把真心给了他，却没有得到回报。", "target_word": "真心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意也需要真心，不能只想着钱。", "target_word": "真心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的真心最让人感动。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的真心让大家都很感动。", "target_word": "真心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没有怀疑过你的真心。", "target_word": "真心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真心话", "label": "复合"}], "register": "中性", "sense_fingerprint": "真诚的心意，可以付出、感受、怀疑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。真心（zhēn xīn）：真诚的心意。"}, {"text": "身心", "is_correct": false, "explanation": "shēn xīn 与 zhēn xīn 声母不同（sh 与 zh），声调相同，意思是身体和心灵。"}, {"text": "中心", "is_correct": false, "explanation": "zhōng xīn 与 zhēn xīn 韵母不同（ong 与 en），声调相同，意思是中央、核心。"}, {"text": "重心", "is_correct": false, "explanation": "zhòng xīn 与 zhēn xīn 韵母不同（ong 与 en），声调也不同（第四声），意思是物体重量集中的点。"}, {"text": "珍惜", "is_correct": false, "explanation": "zhēn xī 比 zhēn xīn 少了末尾的 n，声调相同，意思是珍惜、爱惜。"}], "explanations": {"真心": "正确答案。真心（zhēn xīn）：真诚的心意。", "身心": "shēn xīn 与 zhēn xīn 声母不同（sh 与 zh），声调相同，意思是身体和心灵。", "中心": "zhōng xīn 与 zhēn xīn 韵母不同（ong 与 en），声调相同，意思是中央、核心。", "重心": "zhòng xīn 与 zhēn xīn 韵母不同（ong 与 en），声调也不同（第四声），意思是物体重量集中的点。", "珍惜": "zhēn xī 比 zhēn xīn 少了末尾的 n，声调相同，意思是珍惜、爱惜。"}, "sentence_index": null, "correct_answer": "真心"}, "level_3": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。“真心”作“对待”的宾语，指真诚的心意，符合句意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是挡雨的用具，不能用来对待朋友。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“对待”后接的是态度、方式，不能接“账单”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能用来对待朋友，句子不成立。"}], "explanations": {"真心": "正确答案。“真心”作“对待”的宾语，指真诚的心意，符合句意。", "雨伞": "语义：“雨伞”是挡雨的用具，不能用来对待朋友。", "账单": "搭配：“对待”后接的是态度、方式，不能接“账单”。", "桌子": "语义：“桌子”是家具，不能用来对待朋友，句子不成立。"}, "sentence_index": 0, "correct_answer": "真心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的真心跳得很快。", "explanation": "这里应该用〈心脏〉。“真心”指真诚的心意，不指心脏这一器官。"}, {"text": "他用真心洗干净了衣服。", "explanation": "这里应该用〈洗衣粉〉。“真心”指真诚的心意，不是能洗衣服的东西。"}, {"text": "我的真心去超市买菜了。", "explanation": "这里应该用〈我〉。“真心”指真诚的心意，不能作为施事去超市买菜，主语应是“我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95888, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。真心（zhēn xīn）：真诚的心意。"}, {"text": "真香", "is_correct": false, "explanation": "zhēn xiāng 与 zhēn xīn 韵母不同（iang 与 in），声调相同，意思是很香。"}, {"text": "真性", "is_correct": false, "explanation": "zhēn xìng 与 zhēn xīn 韵母不同（ing 与 in），声调也不同（第四声），意思是本来的性情。"}, {"text": "尘心", "is_correct": false, "explanation": "chén xīn 与 zhēn xīn 声母不同（ch 与 zh），声调也不同（第二声），意思是俗世的念头，书面语。"}], "explanations": {"真心": "正确答案。真心（zhēn xīn）：真诚的心意。", "真香": "zhēn xiāng 与 zhēn xīn 韵母不同（iang 与 in），声调相同，意思是很香。", "真性": "zhēn xìng 与 zhēn xīn 韵母不同（ing 与 in），声调也不同（第四声），意思是本来的性情。", "尘心": "chén xīn 与 zhēn xīn 声母不同（ch 与 zh），声调也不同（第二声），意思是俗世的念头，书面语。"}, "sentence_index": null, "correct_answer": "真心"}, "level_3": {"options": [{"text": "真心", "is_correct": true, "explanation": "正确答案。“真心”作“需要”的宾语，指真诚的心意，符合句意。"}, {"text": "童话", "is_correct": false, "explanation": "语义：“童话”是虚构的故事，与做生意所需的条件无关，句子不成立。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：“眼泪”是哭时流出的液体，不是做生意的条件。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“需要”后接的是资金、人脉、诚信等，“钢琴”不能作为做生意的条件。"}], "explanations": {"真心": "正确答案。“真心”作“需要”的宾语，指真诚的心意，符合句意。", "童话": "语义：“童话”是虚构的故事，与做生意所需的条件无关，句子不成立。", "眼泪": "语义：“眼泪”是哭时流出的液体，不是做生意的条件。", "钢琴": "搭配：“需要”后接的是资金、人脉、诚信等，“钢琴”不能作为做生意的条件。"}, "sentence_index": 6, "correct_answer": "真心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把真心放进了冰箱。", "explanation": "这里应该用〈牛奶〉。“真心”指真诚的心意，不是能放进冰箱的东西。"}, {"text": "今天我的真心很好。", "explanation": "这里应该用〈心情〉。“真心”指真诚的心意，描述心情好坏要用“心情”。"}, {"text": "这次比赛，他的真心拿了第一名。", "explanation": "这里应该用〈成绩〉。“真心”指真诚的心意，不能指比赛的名次，这里应该用“成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对我的一只真心让我很感动。", "corrected_sentence": "她对我的一份真心让我很感动。", "error_description": "“真心”作名词时常用量词“份”“片”“颗”，不能用“只”（“只”多用于动物或成对物品中的单个）。错误句用了“一只真心”，应改为“一份真心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很珍惜你真心。", "corrected_sentence": "我很珍惜你的真心。", "error_description": "名词“真心”前有修饰语“你”时，要用“你的”，不能省略“的”。错误句省略了“的”，应改为“我很珍惜你的真心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
