INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究机构是一群人在一起，专门学习和研究一件事的地方。", "primary_collocate": null, "pronunciation": "yán jiū jī gòu", "ipa": "jɛn˧˥ tɕjoʊ˥ tɕi˥ koʊ˥˩", "syllable_count": 4, "sentences": [{"text": "这家研究机构专门研究茶叶。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个研究机构工作。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究机构有二十个人。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去那个研究机构学习。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究机构的研究员都很忙。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里新建了一个研究机构。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究机构每天都有人做实验。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的朋友在研究机构研究鸟。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究机构离我家很近。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们成立了一个研究机构。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "一群人专门研究一件事的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究机构", "is_correct": true, "explanation": "“研究机构”是专门从事研究的单位，与“专门研究茶叶”相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店提供餐饮，不做研究，与“专门研究茶叶”矛盾。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是售卖商品的场所，不进行研究，与“专门研究茶叶”矛盾。"}, {"text": "铺子", "is_correct": false, "explanation": "语域：“铺子”偏口语、带旧称色彩，与“研究机构”的正式语域不一致，且店铺不做研究。"}], "explanations": {"研究机构": "“研究机构”是专门从事研究的单位，与“专门研究茶叶”相符。", "饭店": "语义：饭店提供餐饮，不做研究，与“专门研究茶叶”矛盾。", "超市": "语义：超市是售卖商品的场所，不进行研究，与“专门研究茶叶”矛盾。", "铺子": "语域：“铺子”偏口语、带旧称色彩，与“研究机构”的正式语域不一致，且店铺不做研究。"}, "sentence_index": 0, "correct_answer": "研究机构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街角新开了一只研究机构。", "explanation": "这里应该用〈家〉或〈个〉。“只”用于动物等，不用于机构。"}, {"text": "他是一名研究机构，每天都很忙。", "explanation": "这里应该用〈研究员〉。“研究机构”指单位，不能指人，“是一名”只能接指人的名词。"}, {"text": "我想去那个研究机构看病。", "explanation": "这里应该用〈医院〉。研究机构是科研单位，不提供诊疗服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究机构", "is_correct": true, "explanation": "“研究机构”是进行科学研究的单位，每天有人做实验，合乎语境。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，不做实验，与“做实验”矛盾。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅提供饮食，不做实验，与“做实验”矛盾。"}, {"text": "窝", "is_correct": false, "explanation": "语域：“窝”是口语，指巢穴或杂乱的藏身处，与正式语境不一致，且不能做实验。"}], "explanations": {"研究机构": "“研究机构”是进行科学研究的单位，每天有人做实验，合乎语境。", "超市": "语义：超市是卖东西的地方，不做实验，与“做实验”矛盾。", "餐厅": "语义：餐厅提供饮食，不做实验，与“做实验”矛盾。", "窝": "语域：“窝”是口语，指巢穴或杂乱的藏身处，与正式语境不一致，且不能做实验。"}, "sentence_index": 6, "correct_answer": "研究机构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们新建了一台研究机构。", "explanation": "这里应该用〈家〉或〈个〉。“台”用于机器设备，不用于机构。"}, {"text": "这家研究机构每天给客户办理存款。", "explanation": "这里应该用〈银行〉。研究机构是科研单位，不办理存款业务。"}, {"text": "他去研究机构剪头发。", "explanation": "这里应该用〈理发店〉。研究机构不提供理发服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只研究机构招了五个新研究员。", "corrected_sentence": "那家研究机构招了五个新研究员。", "error_description": "“研究机构”是单位，量词应用“家”或“个”，不能用“只”（“只”指动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两家研究机构们都招了三个新人。", "corrected_sentence": "这两家研究机构都招了三个新人。", "error_description": "“们”只用于指人的名词，“研究机构”是单位，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
