INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门从事科学研究工作的组织或单位。", "primary_collocate": null, "pronunciation": "yán jiū jī gòu", "ipa": "jɛn˧˥ tɕjoʊ˥ tɕi˥ koʊ˥˩", "syllable_count": 4, "sentences": [{"text": "这家研究机构做了很多科学实验。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家给研究机构很多钱。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究机构发表了新的研究报告。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在研究机构做了十年科学工作。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究机构研究天气和气候。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那所大学旁边有一家研究机构。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究机构的专家来学校讲课。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究机构做出了新药。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究机构需要很多钱。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去国外的研究机构工作。", "target_word": "研究机构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "专门从事科学研究的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_val