INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究机构", "is_correct": true, "explanation": "“研究机构”是专门从事科学研究的单位，做科学实验合乎语境。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅提供饮食，不从事科学实验，与“科学实验”矛盾。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店提供理发服务，不做科学实验，与“科学实验”矛盾。"}, {"text": "铺子", "is_correct": false, "explanation": "语域：“铺子”是口语化的小店称呼，与书面语境的“科学实验”不一致，且店铺不做实验。"}], "explanations": {"研究机构": "“研究机构”是专门从事科学研究的单位，做科学实验合乎语境。", "餐厅": "语义：餐厅提供饮食，不从事科学实验，与“科学实验”矛盾。", "理发店": "语义：理发店提供理发服务，不做科学实验，与“科学实验”矛盾。", "铺子": "语域：“铺子”是口语化的小店称呼，与书面语境的“科学实验”不一致，且店铺不做实验。"}, "sentence_index": 0, "correct_answer": "研究机构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街角新开了一条研究机构。", "explanation": "这里应该用〈家〉或〈个〉。“条”用于细长的物件，不用于机构。"}, {"text": "他是一名研究机构，做了十年科学工作。", "explanation": "这里应该用〈研究员〉。“研究机构”指单位，不能指人。"}, {"text": "那家研究机构每周给病人做手术。", "explanation": "这里应该用〈医院〉。研究机构是科研单位，不做手术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究机构", "is_correct": true, "explanation": "“研究机构”的专家来学校讲课，合乎语境。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是玩耍用的物品，不是单位，不会有专家来学校讲课。"}, {"text": "货架", "is_correct": false, "explanation": "语义：货架是陈列用具，不能派专家来学校讲课。"}, {"text": "窝", "is_correct": false, "explanation": "语域：“窝”是口语，指巢穴或藏身处，与正式语境不一致，且不能派专家讲课。"}], "explanations": {"研究机构": "“研究机构”的专家来学校讲课，合乎语境。", "玩具": "语义：“玩具”是玩耍用的物品，不是单位，不会有专家来学校讲课。", "货架": "语义：货架是陈列用具，不能派专家来学校讲课。", "窝": "语域：“窝”是口语，指巢穴或藏身处，与正式语境不一致，且不能派专家讲课。"}, "sentence_index": 6, "correct_answer": "研究机构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国外新建了一台研究机构。", "explanation": "这里应该用〈家〉或〈个〉。“台”用于机器设备，不用于机构。"}, {"text": "这家研究机构每天给客户办理贷款。", "explanation": "这里应该用〈银行〉。研究机构是科研单位，不办理贷款业务。"}, {"text": "她去研究机构剪头发。", "explanation": "这里应该用〈理发店〉。研究机构不提供理发服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只研究机构新建了一个实验室。", "corrected_sentence": "这家研究机构新建了一个实验室。", "error_description": "“研究机构”是单位，量词应用“家”或“个”，不能用“只”（“只”指动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那所研究机构们的专家下周来学校讲课。", "corrected_sentence": "那所研究机构的专家下周来学校讲课。", "error_description": "“们”只用于指人的名词，“研究机构”是单位，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
