INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95893, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "礼拜就是一个星期，有七天。", "primary_collocate": null, "pronunciation": "lǐ bài", "ipa": "li˨˩˦ paɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我每个礼拜游两次泳。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个礼拜我很忙。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他上个礼拜去了北京。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们下个礼拜考试。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事要等一个礼拜。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一个礼拜有七天。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她每个礼拜给妈妈打电话。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经三个礼拜没见到他了。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书我看了两个礼拜。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个礼拜我要去旅行。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "礼拜天", "label": "复合"}, {"form": "禮拜", "label": "繁体"}], "register": "口语", "sense_fingerprint": "礼拜：星期，七天为一周的时间单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼拜", "is_correct": true, "explanation": "“礼拜”指一周，“每个礼拜”表示每周，与“游两次泳”相符。"}, {"text": "秒", "is_correct": false, "explanation": "语义：秒是极短的时间，“每秒游两次泳”不合常理。"}, {"text": "世纪", "is_correct": false, "explanation": "语义：世纪跨度太长，“每个世纪游两次泳”不成立。"}, {"text": "午夜", "is_correct": false, "explanation": "搭配：“午夜”是时刻，不能作“每个”后表示周期的单位，与“游两次泳”的周期不搭。"}], "explanations": {"礼拜": "“礼拜”指一周，“每个礼拜”表示每周，与“游两次泳”相符。", "秒": "语义：秒是极短的时间，“每秒游两次泳”不合常理。", "世纪": "语义：世纪跨度太长，“每个世纪游两次泳”不成立。", "午夜": "搭配：“午夜”是时刻，不能作“每个”后表示周期的单位，与“游两次泳”的周期不搭。"}, "sentence_index": 0, "correct_answer": "礼拜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们下只礼拜考试。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的物件，时间单位“礼拜”用“个”。"}, {"text": "我吃一顿饭要三个礼拜。", "explanation": "这里应该用〈分钟〉。“礼拜”是一周，不能用来计量吃一顿饭的时间。"}, {"text": "我三个礼拜就吃完了午饭。", "explanation": "这里应该用〈小时〉。“礼拜”是一周，不能用来计量吃午饭的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "礼拜", "is_correct": true, "explanation": "“礼拜”指一周，“每个礼拜”表示每周打电话，合乎语境。"}, {"text": "光年", "is_correct": false, "explanation": "语义：光年是距离单位，不能作时间周期，“每个光年打电话”不合理。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：瞬间极短，不能作“每个”后的周期，“每个瞬间打电话”不成立。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“方向”不是时间单位，不能接在“每个”后表示周期。"}], "explanations": {"礼拜": "“礼拜”指一周，“每个礼拜”表示每周打电话，合乎语境。", "光年": "语义：光年是距离单位，不能作时间周期，“每个光年打电话”不合理。", "瞬间": "语义：瞬间极短，不能作“每个”后的周期，“每个瞬间打电话”不成立。", "方向": "搭配：“方向”不是时间单位，不能接在“每个”后表示周期。"}, "sentence_index": 6, "correct_answer": "礼拜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份礼拜我很忙。", "explanation": "这里应该用〈个〉。“份”用于份额或食物，时间单位“礼拜”用“个”。"}, {"text": "这座山有三个礼拜那么高。", "explanation": "这里应该用〈米〉。“礼拜”是时间单位，不能用来计量高度。"}, {"text": "我刷牙要用一个礼拜。", "explanation": "这里应该用〈分钟〉。“礼拜”是一周，刷牙只要几分钟，不能用“礼拜”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每只礼拜去看一次爷爷。", "corrected_sentence": "我每个礼拜去看一次爷爷。", "error_description": "“礼拜”作时间单位，量词应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
