INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宗教信徒在教堂等场所进行的敬拜活动。", "primary_collocate": null, "pronunciation": "lǐ bài", "ipa": "li˨˩˦ paɪ˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶星期天去教堂做礼拜。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一家人每周都去做礼拜。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教堂里的人正在做礼拜。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做完礼拜，大家一起吃饭。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷信教，常常去做礼拜。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "星期天早上，我陪妈妈去做礼拜。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每周日都带我去教堂做礼拜。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每周日都在家里做礼拜。", "target_word": "礼拜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们穿着白衣服参加礼拜。", "target_word": "礼拜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完早饭，我们全家就去教堂做礼拜。", "target_word": "礼拜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "礼拜天", "label": "复合"}, {"form": "禮拜", "label": "繁体"}], "register": "口语", "sense_fingerprint": "宗教信徒在教堂等场所的敬拜活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼拜", "is_correct": true, "explanation": "“做礼拜”是宗教信徒在教堂进行的敬拜活动，与“去教堂”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，不在教堂做，与“去教堂”矛盾。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗行为，不在教堂进行，与“去教堂”矛盾。"}, {"text": "生意", "is_correct": false, "explanation": "搭配：“做生意”需要经营场所，与“去教堂”所指的宗教活动不搭。"}], "explanations": {"礼拜": "“做礼拜”是宗教信徒在教堂进行的敬拜活动，与“去教堂”相符。", "作业": "语义：作业是学生的功课，不在教堂做，与“去教堂”矛盾。", "手术": "语义：手术是医疗行为，不在教堂进行，与“去教堂”矛盾。", "生意": "搭配：“做生意”需要经营场所，与“去教堂”所指的宗教活动不搭。"}, "sentence_index": 0, "correct_answer": "礼拜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做完一只礼拜，大家一起吃饭。", "explanation": "这里应该用〈次〉。礼拜是一次次的活动，量词用“次”，不用“只”。"}, {"text": "他对老师很有礼拜。", "explanation": "这里应该用〈礼貌〉。“礼拜”是宗教活动，不能用来形容待人的态度。"}, {"text": "我妈妈是一个礼拜。", "explanation": "这里应该用〈信徒〉。“礼拜”指一周或敬拜活动，不指人，指人要用“信徒”等词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "礼拜", "is_correct": true, "explanation": "“做礼拜”是信徒在教堂进行的敬拜活动，与“去教堂”相符。"}, {"text": "窝", "is_correct": false, "explanation": "语义：“做窝”指筑巢，是鸟类的活动，与“去教堂”的宗教活动不搭。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗行为，不在教堂进行，与“去教堂”矛盾。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是学业测验，不在教堂进行，与“去教堂”的宗教活动不符。"}], "explanations": {"礼拜": "“做礼拜”是信徒在教堂进行的敬拜活动，与“去教堂”相符。", "窝": "语义：“做窝”指筑巢，是鸟类的活动，与“去教堂”的宗教活动不搭。", "手术": "语义：手术是医疗行为，不在教堂进行，与“去教堂”矛盾。", "考试": "语义：考试是学业测验，不在教堂进行，与“去教堂”的宗教活动不符。"}, "sentence_index": 6, "correct_answer": "礼拜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教堂的钟响了，大家开始做一只礼拜。", "explanation": "这里应该用〈次〉。礼拜是一次次的活动，量词用“次”，不用“只”。"}, {"text": "他对邻居很有礼拜，大家都喜欢他。", "explanation": "这里应该用〈礼貌〉。“礼拜”指敬拜活动，不能用来形容待人的态度。"}, {"text": "他是我们教堂的一个礼拜。", "explanation": "这里应该用〈信徒〉。“礼拜”指敬拜活动，不指人，指人要用“信徒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷每个星期天都去教堂做一只礼拜。", "corrected_sentence": "爷爷每个星期天都去教堂做一次礼拜。", "error_description": "“礼拜”作活动，量词应用“次”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每周日都去教堂做一只礼拜。", "corrected_sentence": "他们每周日都去教堂做一次礼拜。", "error_description": "量词错误：“礼拜”作敬拜活动，用“次”计数，不能用“只”（“只”用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
