INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "粮食，供人吃的谷类等食物。", "primary_collocate": null, "pronunciation": "liáng", "ipa": "ljɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "秋天，农民忙着收粮。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里堆满了粮。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用车把粮运到城里。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的粮卖了个好价钱。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，很多家庭没粮吃。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俗话说，手中有粮，心中不慌。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水能浇地，地里才能打出粮来。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把多余的粮存了起来。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年发大水，村里的粮全坏了。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要保证老百姓有粮吃。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粮食", "label": "复合"}, {"form": "粮仓", "label": "复合"}], "register": "中性", "sense_fingerprint": "粮食，供人吃的谷类等食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89422d92-e8b7-408c-a79e-eb0b7d409ade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95898, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粮", "is_correct": true, "explanation": "粮（liáng）指供人吃的谷类等食物，是正确答案。"}, {"text": "量", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是数量。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liáng（第二声）声调不同，意思是二。"}, {"text": "亮", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是明亮。"}, {"text": "娘", "is_correct": false, "explanation": "niáng 与 liáng 声母不同（n/l），意思是母亲。"}], "explanations": {"粮": "粮（liáng）指供人吃的谷类等食物，是正确答案。", "量": "liàng（第四声）与 liáng（第二声）声调不同，意思是数量。", "两": "liǎng（第三声）与 liáng（第二声）声调不同，意思是二。", "亮": "liàng（第四声）与 liáng（第二声）声调不同，意思是明亮。", "娘": "niáng 与 liáng 声母不同（n/l），意思是母亲。"}, "sentence_index": null, "correct_answer": "粮"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不能收，“收空气”说不通。"}, {"text": "粮", "is_correct": true, "explanation": "粮是秋天收获的谷物，与“收”搭配自然。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是“收”的对象，秋天农民不收树。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不是秋天农民收获的东西。"}], "explanations": {"空气": "语义：空气不能收，“收空气”说不通。", "粮": "粮是秋天收获的谷物，与“收”搭配自然。", "树": "语义：树不是“收”的对象，秋天农民不收树。", "笔": "语义：笔不是秋天农民收获的东西。"}, "sentence_index": 0, "correct_answer": "粮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用粮给朋友写了一封信。", "explanation": "这里应该用〈笔〉。粮是吃的东西，不能用来写信。"}, {"text": "我的粮增加了五厘米。", "explanation": "这里应该用〈身高〉。粮不能用来说身体长高，要说“增加”的是身高。"}, {"text": "妈妈给我买了一件粮。", "explanation": "这里应该用〈袋〉或〈斤〉。〈件〉用于衣服等物品，粮不能用〈件〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95898, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "粮", "is_correct": true, "explanation": "粮（liáng）指供人吃的谷类等食物，是正确答案。"}, {"text": "连", "is_correct": false, "explanation": "lián 与 liáng 韵母不同（an/ang），意思是连接。"}, {"text": "辆", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是车的量词。"}, {"text": "晾", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是晾晒。"}, {"text": "谅", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是原谅。"}], "explanations": {"粮": "粮（liáng）指供人吃的谷类等食物，是正确答案。", "连": "lián 与 liáng 韵母不同（an/ang），意思是连接。", "辆": "liàng（第四声）与 liáng（第二声）声调不同，意思是车的量词。", "晾": "liàng（第四声）与 liáng（第二声）声调不同，意思是晾晒。", "谅": "liàng（第四声）与 liáng（第二声）声调不同，意思是原谅。"}, "sentence_index": null, "correct_answer": "粮"}, "level_3": {"options": [{"text": "钱", "is_correct": false, "explanation": "搭配：“打出”不说打出钱来，这里应说“挣钱”。"}, {"text": "粮", "is_correct": true, "explanation": "粮是土地里打出来的谷物，与“打出……来”搭配自然。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋不是从地里打出来的东西。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“打出歌来”不自然，这里说的是土地的收获。"}], "explanations": {"钱": "搭配：“打出”不说打出钱来，这里应说“挣钱”。", "粮": "粮是土地里打出来的谷物，与“打出……来”搭配自然。", "鞋": "语义：鞋不是从地里打出来的东西。", "歌": "搭配：“打出歌来”不自然，这里说的是土地的收获。"}, "sentence_index": 6, "correct_answer": "粮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家要保证老百姓有粮喝。", "explanation": "这里应该用〈水〉。粮是谷物，不能喝。"}, {"text": "国家要保证老百姓有粮住。", "explanation": "这里应该用〈房〉。粮不能用来住。"}, {"text": "国家要保证老百姓有粮读。", "explanation": "这里应该用〈书〉。粮不能用来读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_error