INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们买了两只粮，准备过冬。", "corrected_sentence": "他们买了两袋粮，准备过冬。", "error_description": "量词错误：粮要用〈袋〉计量，不能用〈只〉。正确说法是“两袋粮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民粮把装进了袋子里。", "corrected_sentence": "农民把粮装进了袋子里。", "error_description": "“把”的位置错误：“把”要放在处置对象“粮”之前，应说“把粮装进了袋子里”，不能说“粮把装进了袋子里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
