INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改正错误或偏差，使之正确。", "primary_collocate": null, "pronunciation": "jiū zhèng", "ipa": "tɕjou˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师纠正了我的发音。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你纠正我的错误。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，慢慢纠正了坐姿。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生帮孩子纠正走路的姿势。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要及时纠正这个错误做法。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章里的错字，编辑都纠正了。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现问题，要马上纠正。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发音有偏差，需要纠正。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这个错误纠正以后，成绩就好多了。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想纠正一下刚才的说法。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纠正了", "label": "体标"}, {"form": "纠正过", "label": "体标"}], "register": "中性", "sense_fingerprint": "改正错误或偏差，使之变得正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1736f8c-b416-42c2-9d2b-c556b9cf59db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "搭配：“原谅”的对象是人的过失，不能说“原谅发音”"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与改正发音的意思不符"}, {"text": "纠正", "is_correct": true, "explanation": "纠正：把错误的发音改正过来，符合“老师”的动作"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”与纠正发音的意思毫不相关"}], "explanations": {"原谅": "搭配：“原谅”的对象是人的过失，不能说“原谅发音”", "唱": "语义：“唱”指唱歌，与改正发音的意思不符", "纠正": "纠正：把错误的发音改正过来，符合“老师”的动作", "吃掉": "语义：“吃掉”与纠正发音的意思毫不相关"}, "sentence_index": 0, "correct_answer": "纠正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司纠正了这次聚会。", "explanation": "这里应该用〈举办〉。纠正用于改正错误或偏差，组织聚会要用举办"}, {"text": "我的体重纠正了三公斤。", "explanation": "这里应该用〈增加〉。纠正用于改正错误，体重变化的数量要用增加"}, {"text": "他纠正了良好的习惯。", "explanation": "这里应该用〈培养〉。良好的习惯本身没有错误，纠正用于改正错误；培养习惯要用培养"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”不能以“问题”为宾语"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝的是喜事，与发现问题的语境相反"}, {"text": "纠正", "is_correct": true, "explanation": "纠正：发现问题后马上改正，符合语境"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是生活、待遇等，不能说“享受问题”"}], "explanations": {"欢迎": "搭配：“欢迎”不能以“问题”为宾语", "庆祝": "语义：庆祝的是喜事，与发现问题的语境相反", "纠正": "纠正：发现问题后马上改正，符合语境", "享受": "搭配：“享受”的对象是生活、待遇等，不能说“享受问题”"}, "sentence_index": 6, "correct_answer": "纠正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师纠正了他的进步。", "explanation": "这里应该用〈表扬〉。纠正用于改正错误，肯定进步要用表扬"}, {"text": "我们纠正了这片森林。", "explanation": "这里应该用〈保护〉。纠正的对象是错误或做法，保护森林要用保护"}, {"text": "我们纠正了快乐的时光。", "explanation": "这里应该用〈分享〉。快乐的时光没有错误，与别人共享快乐要用分享"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要马上纠正了这个问题。", "corrected_sentence": "我们要马上纠正这个问题。", "error_description": "体标错误。动词后的“了”表示动作已完成，与表示打算的“要”不能直接搭配；去掉“了”，正确为“我们要马上纠正这个问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快就把错误纠正来了。", "corrected_sentence": "他很快就把错误纠正过来了。", "error_description": "补语错误。结果补语“过来”中的“过”被漏掉，“纠正来”不成立。正确为“纠正过来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
