INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95903, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "美味是吃起来很香很好吃的东西。", "primary_collocate": null, "pronunciation": "měi wèi", "ipa": "meɪ˨˩˦ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈做了一桌美味，我们都吃得很开心。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有很多海边的美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着各种美味，我不知道先吃哪一个。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在夜市吃到了很多美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱吃美味，不爱吃青菜。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，家里总有很多美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些美味都是奶奶亲手做的。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来到成都，一定要尝一尝当地的美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着满桌的美味，孩子笑了。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请我们品尝了一道美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道美味", "label": "量词"}], "register": "中性", "sense_fingerprint": "吃起来很香很好吃的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ce3a876-3c1d-44d7-b39d-01649e9db7d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美味", "is_correct": true, "explanation": "美味是味道鲜美的食物，与“做”和“吃得很开心”搭配。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能吃，与“吃得很开心”冲突。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“一桌”指一桌饭菜，作业不能用“一桌”计量。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能吃，也不会让人“吃得很开心”。"}], "explanations": {"美味": "美味是味道鲜美的食物，与“做”和“吃得很开心”搭配。", "玩具": "语义：玩具不能吃，与“吃得很开心”冲突。", "作业": "搭配：“一桌”指一桌饭菜，作业不能用“一桌”计量。", "垃圾": "语义：垃圾不能吃，也不会让人“吃得很开心”。"}, "sentence_index": 0, "correct_answer": "美味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花很美味。", "explanation": "这里应该用〈美丽〉。美味只指食物好吃，形容花要用美丽。"}, {"text": "我吃了一条美味。", "explanation": "这里应该用〈道〉。美味作为菜肴用“道”计量，“条”只用于细长的东西。"}, {"text": "这幅画很美味。", "explanation": "这里应该用〈好看〉。美味指食物好吃，形容画要用好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美味", "is_correct": true, "explanation": "美味是食物，可以“做”，与“亲手做的”搭配。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然物，不能“亲手做”。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“做”一般不搭配“故事”，这里应说“编”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被人亲手做出来。"}], "explanations": {"美味": "美味是食物，可以“做”，与“亲手做的”搭配。", "河流": "语义：河流是自然物，不能“亲手做”。", "故事": "搭配：“做”一般不搭配“故事”，这里应说“编”。", "天空": "语义：天空不能被人亲手做出来。"}, "sentence_index": 6, "correct_answer": "美味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段音乐很美味。", "explanation": "这里应该用〈美妙〉。美味指食物好吃，音乐要用美妙。"}, {"text": "他很美味。", "explanation": "这里应该用〈漂亮〉。美味只指食物，不能形容人的外貌。"}, {"text": "这首诗很美味。", "explanation": "这里应该用〈优美〉。美味指食物好吃，诗歌的美要用优美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶做了一只美味，全家都夸好吃。", "corrected_sentence": "奶奶做了一道美味，全家都夸好吃。", "error_description": "“美味”指菜肴，计量用“道”；“只”用于动物等，不能用于菜肴，应为“一道美味”，而非“一只美味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅有一只美味，值得一试。", "corrected_sentence": "这家餐厅有一道美味，值得一试。", "error_description": "“美味”是菜肴，应用量词“道”。“只”用于动物等，不能用来计量菜肴，应为“一道美味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7c191a-a2cb-449e-b46a-56c2529b4691') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
