INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "长期形成的、为社会所共同遵守的风俗习惯。", "primary_collocate": null, "pronunciation": "xí sú", "ipa": "ɕi˧˥ su˧˥", "syllable_count": 2, "sentences": [{"text": "婚礼的习俗在各民族里不一样。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是长期形成的社会习俗。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究习俗可以了解一个民族的历史。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同地区的习俗各有特点。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尊重当地习俗是最基本的礼貌。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民族的饮食习俗很特别。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "习俗会随着时代慢慢改变。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年贴春联是汉族的传统习俗。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到外地旅行，要先了解当地的习俗。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了南方的节日习俗。", "target_word": "习俗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "習俗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长期形成、社会共同遵守的风俗习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc14243-eedd-4dfd-9576-020da2c00dc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "习俗", "is_correct": true, "explanation": "正确：习俗指长期形成的做法，“婚礼的习俗在各民族里不一样”说得通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能用来说婚礼在各民族间的差异。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来说婚礼的差异。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入是个人或单位的所得，与婚礼的差异无关。"}], "explanations": {"习俗": "正确：习俗指长期形成的做法，“婚礼的习俗在各民族里不一样”说得通。", "天气": "语义：天气是自然现象，不能用来说婚礼在各民族间的差异。", "身材": "体貌：身材指人的体形，不能用来说婚礼的差异。", "收入": "语义：收入是个人或单位的所得，与婚礼的差异无关。"}, "sentence_index": 0, "correct_answer": "习俗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猫见到陌生人会躲起来，这是它们的习俗。", "explanation": "这里应该用〈习性〉。习俗指人类社会共同遵守的风俗，动物的天性要用习性。"}, {"text": "他做事的习俗很认真，大家都很佩服。", "explanation": "这里应该用〈作风〉。习俗指社会共同遵守的做法，个人做事的风格要用作风。"}, {"text": "这孩子性子很急，这是他的习俗。", "explanation": "这里应该用〈脾气〉。习俗指社会共同遵守的做法，个人性情急躁要用脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "习俗", "is_correct": true, "explanation": "正确：习俗是长期形成、会慢慢变化的社会做法，“习俗会随着时代慢慢改变”说得通。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电瞬间即逝，与“慢慢改变”的意思矛盾。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：瞬间指极短的时间，与“慢慢”修饰的渐变过程矛盾。"}, {"text": "身影", "is_correct": false, "explanation": "体貌：身影是人的身形轮廓，不能指习俗。"}], "explanations": {"习俗": "正确：习俗是长期形成、会慢慢变化的社会做法，“习俗会随着时代慢慢改变”说得通。", "闪电": "语义：闪电瞬间即逝，与“慢慢改变”的意思矛盾。", "瞬间": "语义：瞬间指极短的时间，与“慢慢”修饰的渐变过程矛盾。", "身影": "体貌：身影是人的身形轮廓，不能指习俗。"}, "sentence_index": 6, "correct_answer": "习俗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他见到长辈总是先问好，这是他的习俗。", "explanation": "这里应该用〈习惯〉。习俗指社会共同遵守的风俗，个人长期养成的做法要用习惯。"}, {"text": "她总改不掉爱迟到的习俗。", "explanation": "这里应该用〈习惯〉。习俗是社会共同遵守的风俗，个人的坏习惯要用习惯。"}, {"text": "我不同意他的习俗，我觉得这个问题很简单。", "explanation": "这里应该用〈看法〉。习俗指社会共同遵守的风俗，个人对问题的意见要用看法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只习俗已经流传了很久。", "corrected_sentence": "这种习俗已经流传了很久。", "error_description": "量词错误：“只”用于动物或成对物品中的一个，习俗不能用“只”，应说“这种习俗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书介绍了很多习俗们。", "corrected_sentence": "这本书介绍了很多习俗。", "error_description": "复数标记错误：“们”只用于指人的名词，“习俗”不能加“们”，有“很多”已表示多数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a09aad5-0dd1-429c-a961-fcf592d5e9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
