INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由若干团体或个人联合组成的组织。", "primary_collocate": null, "pronunciation": "lián hé huì", "ipa": "ljɛn˧˥ xɤ˧˥ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "他是作家联合会的会员。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联合会有一百多个会员。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人联合会为大家争取了更多休息时间。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合会的办公室在三楼。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想成立一个青年联合会。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联合会帮助很多老人。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合会请了几位老师来讲课。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际联合会每四年选一次新会长。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在联合会里做了五年工作。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份通知发给联合会。", "target_word": "联合会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "团体或个人联合组成的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "联合会", "is_correct": true, "explanation": "“作家联合会”是由作家个人组成的组织，会员身份与之相符。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表是计时用具，没有会员，“作家手表的会员”不成立。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是交通场所，不是组织，没有会员，“作家车站的会员”不合理。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是盛放废弃物的器具，没有会员，与“会员”无关。"}], "explanations": {"联合会": "“作家联合会”是由作家个人组成的组织，会员身份与之相符。", "手表": "语义：手表是计时用具，没有会员，“作家手表的会员”不成立。", "车站": "语义：车站是交通场所，不是组织，没有会员，“作家车站的会员”不合理。", "垃圾桶": "语义：垃圾桶是盛放废弃物的器具，没有会员，与“会员”无关。"}, "sentence_index": 0, "correct_answer": "联合会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校新成立了一台联合会。", "explanation": "这里应该用〈个〉。联合会是组织，“台”用于机器、电视等。"}, {"text": "我们班有一座联合会，专门负责组织活动。", "explanation": "这里应该用〈个〉。“座”多用于山、楼、桥等大型固定物。"}, {"text": "他们准备成立一场青年联合会。", "explanation": "这里应该用〈个〉。“场”用于比赛、演出等活动，不用于组织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联合会", "is_correct": true, "explanation": "联合会是由个人或团体组成的组织，可以请老师来讲课，符合句中的语境。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景物，不会请老师来讲课。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“请……来讲课”要求有行为能力的主语，“面包”不能与之搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能请人，也不能讲课。"}], "explanations": {"联合会": "联合会是由个人或团体组成的组织，可以请老师来讲课，符合句中的语境。", "河流": "语义：河流是自然景物，不会请老师来讲课。", "面包": "搭配：“请……来讲课”要求有行为能力的主语，“面包”不能与之搭配。", "桌子": "语义：桌子是家具，不能请人，也不能讲课。"}, "sentence_index": 6, "correct_answer": "联合会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在联合会排队买票。", "explanation": "这里应该用〈车站〉。联合会是组织，不是售票的场所。"}, {"text": "我每天在联合会睡午觉。", "explanation": "这里应该用〈家〉。联合会是组织，不是睡午觉的地方。"}, {"text": "爷爷在联合会看病。", "explanation": "这里应该用〈医院〉。联合会是组织，不是看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班的同学都加入了一只青年联合会。", "corrected_sentence": "我们班的同学都加入了一个青年联合会。", "error_description": "量词错误：联合会是组织，应用量词“个”。“只”用于动物，应把“一只”改为“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年加入了这部联合会。", "corrected_sentence": "他去年加入了这个联合会。", "error_description": "量词错误：联合会是组织，应用量词“个”。“部”用于书、电影、车辆等，应把“这部”改为“这个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
