INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95909, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "致命是会让人失去生命，非常危险。", "primary_collocate": null, "pronunciation": "zhì mìng", "ipa": "ʈʂɻ̩˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这条河里的鱼有致命的毒。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一枪很致命，他没有救回来。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从这么高的地方掉下去是会致命的。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种毒药只要一点点就致命。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这种病不致命。", "target_word": "致命", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他吃下了致命的毒药。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里有不少致命的动物。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种细菌对小孩来说非常致命。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高处掉下来的砖头很致命。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛇咬了他一口，毒很致命。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "致命伤", "label": "复合"}], "register": "中性", "sense_fingerprint": "致命：会让人失去生命，非常危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95909, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：zhì mìng，会让人失去生命，非常危险。"}, {"text": "治病", "is_correct": false, "explanation": "zhì bìng（第四声）与 zhì mìng（第四声）只有第二个音节声母不同（b 与 m），意思是治疗疾病。"}, {"text": "制定", "is_correct": false, "explanation": "zhì dìng 与 zhì mìng 只有第二个音节声母不同（d 与 m），意思是制订、拟定。"}, {"text": "指明", "is_correct": false, "explanation": "zhǐ míng（第三、二声）与 zhì mìng（第四声）声调都不同，意思是明确指出。"}], "explanations": {"致命": "致命：zhì mìng，会让人失去生命，非常危险。", "治病": "zhì bìng（第四声）与 zhì mìng（第四声）只有第二个音节声母不同（b 与 m），意思是治疗疾病。", "制定": "zhì dìng 与 zhì mìng 只有第二个音节声母不同（d 与 m），意思是制订、拟定。", "指明": "zhǐ míng（第三、二声）与 zhì mìng（第四声）声调都不同，意思是明确指出。"}, "sentence_index": null, "correct_answer": "致命"}, "level_3": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：形容能让人失去生命的毒，与“有……的毒”搭配，符合句意。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情或态度，毒不能用性情来描述。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多用于声音，不说毒清脆。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色，与毒的危害性质不符。"}], "explanations": {"致命": "致命：形容能让人失去生命的毒，与“有……的毒”搭配，符合句意。", "温柔": "语义：“温柔”形容性情或态度，毒不能用性情来描述。", "清脆": "搭配：“清脆”多用于声音，不说毒清脆。", "雪白": "体貌：“雪白”形容颜色，与毒的危害性质不符。"}, "sentence_index": 0, "correct_answer": "致命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路面只是有点滑，走起来很致命。", "explanation": "这里应该用〈危险〉。路面湿滑只是有风险，不会致人死亡，“致命”说得太重。"}, {"text": "他的脚扭伤了，肿得很致命。", "explanation": "这里应该用〈严重〉。脚扭伤不会致死，只能说肿得厉害，“致命”程度太重。"}, {"text": "只是轻微的感冒，医生却说很致命。", "explanation": "这里应该用〈不要紧〉。轻微感冒不会让人失去生命，不能说“致命”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95909, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：zhì mìng，会让人失去生命，非常危险。"}, {"text": "致敬", "is_correct": false, "explanation": "zhì jìng 与 zhì mìng 只有第二个音节声母不同（j 与 m），意思是表示敬意。"}, {"text": "致病", "is_correct": false, "explanation": "zhì bìng 与 zhì mìng 只有第二个音节声母不同（b 与 m），意思是引起疾病。"}, {"text": "知名", "is_correct": false, "explanation": "zhī míng（第一、二声）与 zhì mìng（第四声）声调都不同，意思是有名、为人所知。"}], "explanations": {"致命": "致命：zhì mìng，会让人失去生命，非常危险。", "致敬": "zhì jìng 与 zhì mìng 只有第二个音节声母不同（j 与 m），意思是表示敬意。", "致病": "zhì bìng 与 zhì mìng 只有第二个音节声母不同（b 与 m），意思是引起疾病。", "知名": "zhī míng（第一、二声）与 zhì mìng（第四声）声调都不同，意思是有名、为人所知。"}, "sentence_index": null, "correct_answer": "致命"}, "level_3": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：形容能让人失去生命的动物，与“有不少”搭配，符合句意。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用于水和眼神，不说动物清澈。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：“晴朗”形容天气，不能用来形容动物。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，动物不能用味道来描述。"}], "explanations": {"致命": "致命：形容能让人失去生命的动物，与“有不少”搭配，符合句意。", "清澈": "搭配：“清澈”多用于水和眼神，不说动物清澈。", "晴朗": "语义：“晴朗”形容天气，不能用来形容动物。", "辛辣": "语义：“辛辣”形容味道，动物不能用味道来描述。"}, "sentence_index": 6, "correct_answer": "致命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的甜度很致命，我吃了一口就放下了。", "explanation": "这里应该用〈过甜〉。致命指会让人失去生命，形容甜度不能用致命，只能说太甜或过甜。"}, {"text": "他这次的心情很致命，一整天都没说话。", "explanation": "这里应该用〈糟糕〉。致命指会让人失去生命，不能用来形容心情。"}, {"text": "这张桌子很致命，只有十厘米高。", "explanation": "这里应该用〈矮〉。致命指会让人失去生命，不能用来形容桌子的高矮，只能说“矮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种蘑菇里含有一种致命地毒素。", "corrected_sentence": "这种蘑菇里含有一种致命的毒素。", "error_description": "助词错误：修饰名词“毒素”的形容词“致命”后应用“的”，不能用“地”（“地”用于修饰动词或形容词作状语）。正确说法是“一种致命的毒素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种病菌对小孩子来说被非常致命，要尽快治疗。", "corrected_sentence": "这种病菌对小孩子来说非常致命，要尽快治疗。", "error_description": "被字句错误：形容词“致命”前不能加“被”，“被非常致命”不成立。正确说法是“非常致命”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
