INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95910, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能导致死亡的；极其严重的。", "primary_collocate": null, "pronunciation": "zhì mìng", "ipa": "ʈʂɻ̩˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种蛇的毒很致命。", "target_word": "致命", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他受了致命的伤。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个错误对公司是致命的。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吸烟对身体有致命的危害。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病在老人身上很致命。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车时看手机可能带来致命的后果。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骄傲是他最致命的缺点。", "target_word": "致命", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那只蜘蛛的毒不致命。", "target_word": "致命", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的伤不算致命，休息几天就好。", "target_word": "致命", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些蘑菇看着好看，毒却很致命。", "target_word": "致命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "致命伤", "label": "复合"}], "register": "中性", "sense_fingerprint": "致命：能导致死亡的，或严重到无法挽回的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95910, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：zhì mìng，能导致死亡，或严重到无法挽回。"}, {"text": "治病", "is_correct": false, "explanation": "zhì bìng（第四声）与 zhì mìng（第四声）只有第二个音节声母不同（b 与 m），意思是治疗疾病。"}, {"text": "制定", "is_correct": false, "explanation": "zhì dìng 与 zhì mìng 只有第二个音节声母不同（d 与 m），意思是制订、拟定。"}, {"text": "指明", "is_correct": false, "explanation": "zhǐ míng（第三、二声）与 zhì mìng（第四声）声调都不同，意思是明确指出。"}], "explanations": {"致命": "致命：zhì mìng，能导致死亡，或严重到无法挽回。", "治病": "zhì bìng（第四声）与 zhì mìng（第四声）只有第二个音节声母不同（b 与 m），意思是治疗疾病。", "制定": "zhì dìng 与 zhì mìng 只有第二个音节声母不同（d 与 m），意思是制订、拟定。", "指明": "zhǐ míng（第三、二声）与 zhì mìng（第四声）声调都不同，意思是明确指出。"}, "sentence_index": null, "correct_answer": "致命"}, "level_3": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：形容能导致死亡的毒，与“很”搭配，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，毒液不能用“甜”来形容，与“毒”的含义冲突。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用于水和眼神，不说毒液清澈。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外表，毒液不是能从外表评价的东西。"}], "explanations": {"致命": "致命：形容能导致死亡的毒，与“很”搭配，符合句意。", "甜": "语义：“甜”说的是味道，毒液不能用“甜”来形容，与“毒”的含义冲突。", "清澈": "搭配：“清澈”多用于水和眼神，不说毒液清澈。", "漂亮": "体貌：“漂亮”形容外表，毒液不是能从外表评价的东西。"}, "sentence_index": 0, "correct_answer": "致命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次感冒很致命，我在家躺了一个星期。", "explanation": "这里应该用〈严重〉。致命指能导致死亡或严重到无法挽回，普通感冒不会致死，用“严重”即可。"}, {"text": "这次旅行的时间很致命，只有一个小时。", "explanation": "这里应该用〈很短〉。致命只用于能导致死亡或无法挽回的坏事，不能形容时间长短，应说“很短”。"}, {"text": "他对花粉过敏，症状很致命，每次都要吃药。", "explanation": "这里应该用〈严重〉。花粉过敏一般不会致死，症状只是严重，用“严重”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95910, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：zhì mìng，能导致死亡，或严重到无法挽回。"}, {"text": "致敬", "is_correct": false, "explanation": "zhì jìng 与 zhì mìng 只有第二个音节声母不同（j 与 m），意思是表示敬意。"}, {"text": "致病", "is_correct": false, "explanation": "zhì bìng 与 zhì mìng 只有第二个音节声母不同（b 与 m），意思是引起疾病。"}, {"text": "知名", "is_correct": false, "explanation": "zhī míng（第一、二声）与 zhì mìng（第四声）声调都不同，意思是有名、为人所知。"}], "explanations": {"致命": "致命：zhì mìng，能导致死亡，或严重到无法挽回。", "致敬": "zhì jìng 与 zhì mìng 只有第二个音节声母不同（j 与 m），意思是表示敬意。", "致病": "zhì bìng 与 zhì mìng 只有第二个音节声母不同（b 与 m），意思是引起疾病。", "知名": "zhī míng（第一、二声）与 zhì mìng（第四声）声调都不同，意思是有名、为人所知。"}, "sentence_index": null, "correct_answer": "致命"}, "level_3": {"options": [{"text": "致命", "is_correct": true, "explanation": "致命：形容能导致严重后果的缺点，与“最”和“缺点”搭配，符合句意。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”形容温度或感受，不能用来形容缺点。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色，缺点不能用颜色来描述。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”多用于质地，不说缺点柔软。"}], "explanations": {"致命": "致命：形容能导致严重后果的缺点，与“最”和“缺点”搭配，符合句意。", "温暖": "语义：“温暖”形容温度或感受，不能用来形容缺点。", "雪白": "体貌：“雪白”形容颜色，缺点不能用颜色来描述。", "柔软": "搭配：“柔软”多用于质地，不说缺点柔软。"}, "sentence_index": 6, "correct_answer": "致命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告的字迹很致命，我看了半天也看不懂。", "explanation": "这里应该用〈潦草〉。致命指能导致死亡或无法挽回，字迹难认只能说“潦草”，不能说致命。"}, {"text": "这杯咖啡的味道很致命，我很喜欢喝。", "explanation": "这里应该用〈好〉。致命指能导致死亡或无法挽回，不能用来夸咖啡好喝，应说“味道很好”。"}, {"text": "他的胆子很致命，什么都不怕。", "explanation": "致命不能形容人的胆量，这里说的是胆子大，应该用“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他受了一处致命地伤，送医院时已经晚了。", "corrected_sentence": "他受了一处致命的伤，送医院时已经晚了。", "error_description": "助词错误：修饰名词“伤”的形容词“致命”后应用“的”，不能用“地”（“地”用于修饰动词或形容词作状语）。正确说法是“一处致命的伤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个缺点对他的前途来说被非常致命。", "corrected_sentence": "这个缺点对他的前途来说非常致命。", "error_description": "被字句错误：形容词“致命”前不能加“被”，“被非常致命”不成立。正确说法是“非常致命”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
