INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95913, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搜集是到处找东西，把它们放在一起。", "primary_collocate": null, "pronunciation": "sōu jí", "ipa": "sou˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我正在为作文搜集资料。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢搜集各国的邮票。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们搜集一些旧报纸。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在现场搜集了很多证据。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大家的意见都搜集起来了。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做调查以前，要先搜集数据。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷搜集过很多老照片。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在网上搜集旅行的信息。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直搜集着各地的民间故事。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们搜集了一些废纸，准备卖掉。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搜集了", "label": "体标（了）"}, {"form": "搜集过", "label": "体标（过）"}, {"form": "搜集着", "label": "体标（着）"}, {"form": "搜集搜集", "label": "重叠"}], "register": "中性", "sense_fingerprint": "到处寻找并汇集资料、物品等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1736f8c-b416-42c2-9d2b-c556b9cf59db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“资料”为宾语"}, {"text": "睡", "is_correct": false, "explanation": "搭配：“睡”不能带“资料”作宾语"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”是不及物动作，不能以“资料”为宾语"}, {"text": "搜集", "is_correct": true, "explanation": "搜集：为作文把资料聚集起来，符合语境"}], "explanations": {"吃": "搭配：“吃”不能以“资料”为宾语", "睡": "搭配：“睡”不能带“资料”作宾语", "跑": "搭配：“跑”是不及物动作，不能以“资料”为宾语", "搜集": "搜集：为作文把资料聚集起来，符合语境"}, "sentence_index": 0, "correct_answer": "搜集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察搜集了失踪的孩子。", "explanation": "这里应该用〈寻找〉。搜集用于物品或资料，找失踪的人要用寻找"}, {"text": "公司搜集了很多员工。", "explanation": "这里应该用〈招募〉。搜集用于物品或资料，招聘人员要用招募"}, {"text": "他搜集了一座旧寺庙。", "explanation": "这里应该用〈修复〉。搜集用于物品或资料，修缮古建筑要用修复"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能用于照片"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能用于照片"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与老照片无关"}, {"text": "搜集", "is_correct": true, "explanation": "搜集：爷爷收集过很多老照片，符合语境"}], "explanations": {"喝": "搭配：“喝”的对象是饮品，不能用于照片", "穿": "搭配：“穿”的对象是衣物，不能用于照片", "唱": "语义：“唱”指唱歌，与老照片无关", "搜集": "搜集：爷爷收集过很多老照片，符合语境"}, "sentence_index": 6, "correct_answer": "搜集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察搜集了小偷。", "explanation": "这里应该用〈抓捕〉。搜集用于物品或资料，抓人要用抓捕"}, {"text": "医生搜集了病人。", "explanation": "这里应该用〈治疗〉。搜集用于物品或资料，给病人看病要用治疗"}, {"text": "大家搜集了一场演出。", "explanation": "这里应该用〈观看〉。搜集用于物品或资料，看演出要用观看"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在为论文搜集了材料。", "corrected_sentence": "他正在为论文搜集材料。", "error_description": "“正在”表示动作正在进行，不能与表示完成的“了”同用。正确为“正在搜集材料”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他搜集了着一些旧邮票。", "corrected_sentence": "他搜集着一些旧邮票。", "error_description": "体标错误。“搜集了着”不成立：“搜集着”表示持续，不能再加“了”；去掉“了”，正确为“他搜集着一些旧邮票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
