INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从事产品加工、制作的工业部门。", "primary_collocate": null, "pronunciation": "zhì zào yè", "ipa": "ʈʂɻ̩˥˩ tsɑʊ̯˥˩ jɛ˥˩", "syllable_count": 3, "sentences": [{"text": "汽车工厂和手机工厂都属于制造业。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制造业是国家经济的重要部门。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给制造业减了税。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制造业的产值今年又提高了。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省的制造业和服务业都不错。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究的是制造业的发展。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制造业用的原材料越来越贵。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制造业比农业需要更多机器。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行专门帮助制造业企业。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制造业的出口增加了。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "製造業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经济中加工、制作产品的工业部门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5f01a3f-0c54-4133-9b25-173d415a41c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制造业", "is_correct": true, "explanation": "正确。汽车工厂和手机工厂都在加工、制作产品，属于制造业。"}, {"text": "农业", "is_correct": false, "explanation": "语义：汽车和手机是工业产品，不属于农业。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：「属于」后接的应是行业或类别，「人口」不能充当。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是产品的类别，汽车和手机不属于天气。"}], "explanations": {"制造业": "正确。汽车工厂和手机工厂都在加工、制作产品，属于制造业。", "农业": "语义：汽车和手机是工业产品，不属于农业。", "人口": "搭配：「属于」后接的应是行业或类别，「人口」不能充当。", "天气": "语义：天气不是产品的类别，汽车和手机不属于天气。"}, "sentence_index": 0, "correct_answer": "制造业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家制造业今年的利润增加了。", "explanation": "这里应该用〈公司〉。制造业指整个行业，不能用「这家」来指一家公司的利润。"}, {"text": "我每天骑着制造业上班。", "explanation": "这里应该用〈自行车〉。制造业是行业，不是交通工具，不能用「骑」。"}, {"text": "他爸爸是一名制造业，每天在医院看病。", "explanation": "这里应该用〈医生〉。制造业是行业，不指人，不能说「一名制造业」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制造业", "is_correct": true, "explanation": "正确。原材料由制造业使用，「制造业用的原材料」成立。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是生产单位，不会使用原材料。"}, {"text": "春天", "is_correct": false, "explanation": "配价：「用」要求施事是人或单位，春天不能作为「用」的主语。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学体裁，不使用原材料。"}], "explanations": {"制造业": "正确。原材料由制造业使用，「制造业用的原材料」成立。", "音乐": "语义：音乐不是生产单位，不会使用原材料。", "春天": "配价：「用」要求施事是人或单位，春天不能作为「用」的主语。", "诗歌": "语义：诗歌是文学体裁，不使用原材料。"}, "sentence_index": 6, "correct_answer": "制造业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们一起去制造业玩儿。", "explanation": "这里应该用〈公园〉。制造业是行业，不是可以去玩的地方。"}, {"text": "昨天晚上制造业下了一场大雨。", "explanation": "这里应该用〈天气〉。制造业是行业，不会下雨，下雨的主语应是天气。"}, {"text": "他每天早上只喝制造业。", "explanation": "这里应该用〈牛奶〉。制造业是行业，不能喝，「喝」要接饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一家制造业工作。", "corrected_sentence": "他在一家制造业企业工作。", "error_description": "错误形式：「一家制造业」。正确形式：「一家制造业企业」。制造业指整个行业，不能用「家」来数，具体的公司要说「制造业企业」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府想把制造业迁。", "corrected_sentence": "政府想把制造业迁到内陆地区。", "error_description": "错误形式：「把制造业迁」动词后缺少补语。正确形式：「把制造业迁到内陆地区」。「把」字句中的单音节动词后必须带补语或「了」等成分，动作才算说完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
