INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "亲人是家里的人，是最爱你的人。", "primary_collocate": null, "pronunciation": "qīn rén", "ipa": "tɕʰin˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "过年的时候，我想回家看亲人。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲人在身边，我觉得很幸福。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个亲人也没有。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想念远方的亲人。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病的时候，亲人最关心我。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给每位亲人都买了礼物。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈是我最爱的亲人。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外工作，他常常给亲人打电话。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲人的爱让我不怕困难。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节时，我们和亲人一起吃饭。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "親人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "亲人·名词：家里最爱你、最关心你的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95917, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲人", "is_correct": true, "explanation": "亲人，指家里最爱你、最关心你的人，即本音对应的词。"}, {"text": "秦人", "is_correct": false, "explanation": "qín（第二声）与 qīn（第一声）只差声调，意思是秦国的人。"}, {"text": "新人", "is_correct": false, "explanation": "xīn 与 qīn 声母不同（x/q），声调相同，意思是新婚的人或新来的人。"}, {"text": "金人", "is_correct": false, "explanation": "jīn 与 qīn 只差声母（j/q），意思是金属做的人像。"}], "explanations": {"亲人": "亲人，指家里最爱你、最关心你的人，即本音对应的词。", "秦人": "qín（第二声）与 qīn（第一声）只差声调，意思是秦国的人。", "新人": "xīn 与 qīn 声母不同（x/q），声调相同，意思是新婚的人或新来的人。", "金人": "jīn 与 qīn 只差声母（j/q），意思是金属做的人像。"}, "sentence_index": null, "correct_answer": "亲人"}, "level_3": {"options": [{"text": "亲人", "is_correct": true, "explanation": "“亲人”指家里的人，“我想回家看亲人”符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，“回家看空气”说不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：过年回家不是为了“看数学”，句意不通。"}, {"text": "地址", "is_correct": false, "explanation": "语义：回家过年不会去“看地址”，这里的“看”不合句意。"}], "explanations": {"亲人": "“亲人”指家里的人，“我想回家看亲人”符合句意。", "空气": "语义：空气看不见，“回家看空气”说不通。", "数学": "语义：过年回家不是为了“看数学”，句意不通。", "地址": "语义：回家过年不会去“看地址”，这里的“看”不合句意。"}, "sentence_index": 0, "correct_answer": "亲人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在学校认识了很多亲人。", "explanation": "这里应该用〈同学〉。亲人指有血缘或婚姻关系的人，学校里认识的同学不是亲属。"}, {"text": "我很想念远方的一只亲人。", "explanation": "这里应该用〈位〉或〈个〉。量词“只”用于动物，指人要用“位”或“个”。"}, {"text": "这家商店的亲人在卖水果。", "explanation": "这里应该用〈店员〉。亲人指家里的人，商店里卖东西的人是店员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲人", "is_correct": true, "explanation": "“亲人”指最爱自己的家里人，“妈妈是我最爱的亲人”符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：妈妈是人，不能是颜色。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：妈妈是人，不能是乐器。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“妈妈是我最爱的”矛盾，妈妈不是陌生人。"}], "explanations": {"亲人": "“亲人”指最爱自己的家里人，“妈妈是我最爱的亲人”符合句意。", "颜色": "语义：妈妈是人，不能是颜色。", "乐器": "语义：妈妈是人，不能是乐器。", "陌生人": "语义：“陌生人”与“妈妈是我最爱的”矛盾，妈妈不是陌生人。"}, "sentence_index": 6, "correct_answer": "亲人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在出租车上刚认识了一位亲人。", "explanation": "这里应该用〈朋友〉。亲人是家里的人，不是刚认识的人。"}, {"text": "过节时，我们和一本亲人一起吃饭。", "explanation": "这里应该用〈位〉或〈个〉。量词“本”用于书籍，指人不能说“一本亲人”。"}, {"text": "超市里的亲人在收钱。", "explanation": "这里应该用〈收银员〉。亲人指家里的人，在超市收钱的是收银员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我见了过很多亲人。", "corrected_sentence": "我见过很多亲人。", "error_description": "错误：“了”与“过”不能同时用在动词“见”后，去掉“了”即“我见过很多亲人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一只亲人很关心她。", "corrected_sentence": "她有一位亲人很关心她。", "error_description": "错误：量词“只”用于动物，指人应用“位”或“个”。正确：应说“她有一位亲人很关心她”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
