INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有血缘或婚姻关系的人，如父母、兄弟姐妹。", "primary_collocate": null, "pronunciation": "qīn rén", "ipa": "tɕʰin˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "爸爸妈妈和兄弟姐妹都是我的亲人。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的亲人都住在南方。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚以后，妻子的家人也成了他的亲人。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院请病人的亲人去签字。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这个城市没有亲人。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察找到了孩子的亲人。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些人是我的亲人，不是朋友。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的亲人里有很多老师。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一位亲人在北京工作。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写下亲人的名字和电话。", "target_word": "亲人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "親人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "亲人·名词：有血缘或婚姻关系的家属，如父母、兄弟姐妹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95918, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲人", "is_correct": true, "explanation": "亲人，指有血缘或婚姻关系的家人，即本音对应的词。"}, {"text": "秦人", "is_correct": false, "explanation": "qín（第二声）与 qīn（第一声）只差声调，意思是秦国的人。"}, {"text": "新人", "is_correct": false, "explanation": "xīn 与 qīn 声母不同（x/q），声调相同，意思是新婚的人或新来的人。"}, {"text": "金人", "is_correct": false, "explanation": "jīn 与 qīn 只差声母（j/q），意思是金属做的人像。"}], "explanations": {"亲人": "亲人，指有血缘或婚姻关系的家人，即本音对应的词。", "秦人": "qín（第二声）与 qīn（第一声）只差声调，意思是秦国的人。", "新人": "xīn 与 qīn 声母不同（x/q），声调相同，意思是新婚的人或新来的人。", "金人": "jīn 与 qīn 只差声母（j/q），意思是金属做的人像。"}, "sentence_index": null, "correct_answer": "亲人"}, "level_3": {"options": [{"text": "亲人", "is_correct": true, "explanation": "“亲人”指有血缘或婚姻关系的人，父母和兄弟姐妹都属于此类。"}, {"text": "同学", "is_correct": false, "explanation": "语义：同学指同校的人，父母和兄弟姐妹不是我的同学。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：邻居指住得近的人，父母不是我的邻居。"}, {"text": "同伙", "is_correct": false, "explanation": "语域：“同伙”含贬义，用来说家人不妥。"}], "explanations": {"亲人": "“亲人”指有血缘或婚姻关系的人，父母和兄弟姐妹都属于此类。", "同学": "语义：同学指同校的人，父母和兄弟姐妹不是我的同学。", "邻居": "语义：邻居指住得近的人，父母不是我的邻居。", "同伙": "语域：“同伙”含贬义，用来说家人不妥。"}, "sentence_index": 0, "correct_answer": "亲人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的亲人都很友好。", "explanation": "这里应该用〈同学〉。亲人指有血缘或婚姻关系的人，同班同学不是亲属。"}, {"text": "我们公司的亲人都很友好。", "explanation": "这里应该用〈同事〉。亲人指有血缘或婚姻关系的人，同事不是亲属。"}, {"text": "他有一条亲人在北京。", "explanation": "这里应该用〈位〉或〈个〉。量词“条”用于细长的东西，指人不能说“一条亲人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲人", "is_correct": true, "explanation": "“亲人”指有血缘或婚姻关系的人，“这些人是我的亲人”符合句意。"}, {"text": "陌生人", "is_correct": false, "explanation": "搭配：“我的陌生人”自相矛盾，陌生人与“我”没有关系。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不是人，与“这些人”不合。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：前文说“不是朋友”，这里再填“朋友”自相矛盾。"}], "explanations": {"亲人": "“亲人”指有血缘或婚姻关系的人，“这些人是我的亲人”符合句意。", "陌生人": "搭配：“我的陌生人”自相矛盾，陌生人与“我”没有关系。", "宠物": "语义：宠物不是人，与“这些人”不合。", "朋友": "语义：前文说“不是朋友”，这里再填“朋友”自相矛盾。"}, "sentence_index": 6, "correct_answer": "亲人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不认识他，他是我的亲人。", "explanation": "这里应该用〈陌生人〉。亲人是有血缘或婚姻关系的人，不认识的人是陌生人。"}, {"text": "公司的亲人很努力。", "explanation": "这里应该用〈员工〉。亲人指有血缘或婚姻关系的人，公司的员工不是亲属。"}, {"text": "学校的亲人很多。", "explanation": "这里应该用〈学生〉。亲人指有血缘或婚姻关系的人，学校里的学生不是亲属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一条亲人在北京工作。", "corrected_sentence": "我的一位亲人在北京工作。", "error_description": "错误：量词“条”用于细长的东西，指人应用“位”或“个”。正确：应说“我的一位亲人在北京工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一只亲人在北京。", "corrected_sentence": "她有一位亲人在北京。", "error_description": "错误：量词“只”用于动物，指人应用“位”或“个”。正确：应说“一位亲人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
