INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "报社或电台等派驻外地的新闻采访机构。", "primary_collocate": null, "pronunciation": "jì zhě zhàn", "ipa": "tɕi˥˩ ʈʂɤ˨˩˦ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "电台在西安设了一个记者站。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报社在全国有二十多个记者站。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者站的同事一起去采访。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新闻稿从记者站传回总部。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者站的负责人姓李。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个记者站专门报道当地的新闻。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台打算在海南开办记者站。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者站的灯一直亮到半夜。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在广州记者站实习过两个月。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总社给记者站送来了新设备。", "target_word": "记者站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "記者站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报社或电台派驻外地的新闻采访机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菜谱", "is_correct": false, "explanation": "搭配：“设”用于机构或据点，不能说设立菜谱。"}, {"text": "记者站", "is_correct": true, "explanation": "正确：记者站是报社或电台派驻外地的采访机构，可以“设”。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不是可以设立的机构。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不能作设立的对象。"}], "explanations": {"菜谱": "搭配：“设”用于机构或据点，不能说设立菜谱。", "记者站": "正确：记者站是报社或电台派驻外地的采访机构，可以“设”。", "眼镜": "语义：眼镜是物品，不是可以设立的机构。", "西瓜": "语义：西瓜是水果，不能作设立的对象。"}, "sentence_index": 0, "correct_answer": "记者站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天在记者站看病。", "explanation": "这里应该用〈医院〉。看病要去医院；记者站是新闻采访机构。"}, {"text": "妈妈去记者站买了一些水果。", "explanation": "这里应该用〈商店〉。买水果要去商店；记者站是新闻单位派驻外地的采访机构，不卖东西。"}, {"text": "他每天在记者站等车。", "explanation": "这里应该用〈车站〉。等车要去车站；记者站不是候车的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能作开办的对象。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是声音，不能被开办。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“开办”搭配机构或事业，不与“眼泪”搭配。"}, {"text": "记者站", "is_correct": true, "explanation": "正确：记者站是派驻外地的采访机构，可以在海南“开办”。"}], "explanations": {"感冒": "语义：感冒是疾病，不能作开办的对象。", "雷声": "语义：雷声是声音，不能被开办。", "眼泪": "搭配：“开办”搭配机构或事业，不与“眼泪”搭配。", "记者站": "正确：记者站是派驻外地的采访机构，可以在海南“开办”。"}, "sentence_index": 6, "correct_answer": "记者站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天去记者站取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行；记者站不办理存取款。"}, {"text": "孩子在记者站上课。", "explanation": "这里应该用〈学校〉。上课要去学校；记者站是新闻采访机构。"}, {"text": "警察在记者站值班。", "explanation": "这里应该用〈派出所〉。警察值班在派出所；记者站不是公安机关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视台在上海设了一名记者站。", "corrected_sentence": "电视台在上海设了一个记者站。", "error_description": "量词错误：〈记者站〉是机构，量词应用〈个〉。〈名〉用于人，“设了一名记者站”是错的，应改为“设了一个记者站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天记者站写稿子。", "corrected_sentence": "他每天在记者站写稿子。", "error_description": "介词缺失：表示地点要用〈在〉，应说“在记者站写稿子”，不能直接说“记者站写稿子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
