INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95922, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过面对面的交谈来了解情况、听取意见。", "primary_collocate": null, "pronunciation": "fǎng tán", "ipa": "faŋ˨˩ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "公司访谈了员工，想听听大家的意见。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者先访谈了几位老人，再写这篇报道。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长去村里访谈农民，了解种地的困难。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校访谈家长，听取他们的意见。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师访谈过每个学生，了解学习情况。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查员上门访谈住户，问他们对小区的看法。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要面对面访谈，才能了解真实情况。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理明天访谈新来的同事，听听他们的想法。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察到现场访谈了几位邻居，了解情况。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者正在访谈使用者，收集意见。", "target_word": "访谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "访谈了", "label": "了体标"}, {"form": "访谈过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "面对面交谈以了解情况听取意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d993711-fcb6-4ae5-84ed-b24535ccaac2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "访谈", "is_correct": true, "explanation": "访谈：面对面交谈以听取员工的意见，与句中想听听大家意见的目的相合。"}, {"text": "装修", "is_correct": false, "explanation": "配价：“装修”的对象是房屋或场所，不能接员工作宾语。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指涂饰墙面，与员工和意见无关。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对器物，不能用于员工。"}], "explanations": {"访谈": "访谈：面对面交谈以听取员工的意见，与句中想听听大家意见的目的相合。", "装修": "配价：“装修”的对象是房屋或场所，不能接员工作宾语。", "粉刷": "语义：“粉刷”指涂饰墙面，与员工和意见无关。", "修理": "语义：“修理”针对器物，不能用于员工。"}, "sentence_index": 0, "correct_answer": "访谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师访谈了学生的作业。", "explanation": "这里应该用〈检查〉。访谈是面对面交谈、了解情况，作业是物品，应说检查。"}, {"text": "学校访谈了新的校规。", "explanation": "这里应该用〈宣传〉。访谈是为了了解情况、听取意见，校规要向大家宣传，不能说访谈。"}, {"text": "消防员访谈了那辆消防车。", "explanation": "这里应该用〈检修〉。访谈的对象是人，消防车是器物，应说检修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "访谈", "is_correct": true, "explanation": "访谈：面对面交谈以了解真实情况，与“面对面”和“了解真实情况”的目的相合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“了解真实情况”的目的不符。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“面对面欣赏”不成立，“欣赏”不与“面对面”这种交谈方式搭配。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的对象是活动或会议，“面对面举办”不通。"}], "explanations": {"访谈": "访谈：面对面交谈以了解真实情况，与“面对面”和“了解真实情况”的目的相合。", "赞美": "语义：“赞美”表示称赞，与“了解真实情况”的目的不符。", "欣赏": "搭配：“面对面欣赏”不成立，“欣赏”不与“面对面”这种交谈方式搭配。", "举办": "搭配：“举办”的对象是活动或会议，“面对面举办”不通。"}, "sentence_index": 6, "correct_answer": "访谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者访谈了那场火灾。", "explanation": "这里应该用〈采访〉。访谈的对象是人，要通过交谈了解情况；火灾是事件，记者应说采访。"}, {"text": "调查员访谈了小区的环境。", "explanation": "这里应该用〈调查〉。访谈是面对面交谈，小区环境要靠实地观察和调查来了解，应说调查。"}, {"text": "他访谈了那个国家。", "explanation": "这里应该用〈访问〉。访谈的对象是人，去某个国家是访问，不能说访谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理访谈地很仔细，每个人都说了心里话。", "corrected_sentence": "经理访谈得很仔细，每个人都说了心里话。", "error_description": "“很仔细”是说明“访谈”程度的补语，应用“得”连接，应为“访谈得很仔细”；用“地”修饰不当。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员昨天访谈着了二十位用户，收集了很多意见。", "corrected_sentence": "研究人员昨天访谈了二十位用户，收集了很多意见。", "error_description": "“着”表示动作持续，不能与“了”同时用在动词后；表示动作已完成只用“了”，应为“访谈了二十位用户”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5ad13-27c8-4690-b925-5a96065c511b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
