INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "话本是以前说书人讲故事用的书。", "primary_collocate": null, "pronunciation": "huà běn", "ipa": "xwa˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本话本是说书人用的书。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说书人手里拿着一本话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有一本很旧的话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说书人看着话本给大家讲故事。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有很多古代的话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上读一本话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本话本里的故事很有意思。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说书人把话本放在桌子上。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的人听说书，说书人靠话本记故事。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本话本是我从旧书店买的。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一本话本", "label": "量词"}, {"form": "话本小说", "label": "复合"}, {"form": "話本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "话本：说书人讲故事用的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4cfc666-8119-44d9-9cb1-da1cda7a5a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话本", "is_correct": true, "explanation": "“话本”指说书人讲故事用的书，与“说书人用的书”的语境相符，是正确答案。"}, {"text": "日记", "is_correct": false, "explanation": "语义：“日记”记录个人的经历，不是说书人讲故事用的书。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”讲的是做菜的方法，与说书人讲故事没有关系。"}, {"text": "字帖", "is_correct": false, "explanation": "语义：“字帖”是用来练字的，不是说书人讲故事用的书。"}], "explanations": {"话本": "“话本”指说书人讲故事用的书，与“说书人用的书”的语境相符，是正确答案。", "日记": "语义：“日记”记录个人的经历，不是说书人讲故事用的书。", "菜谱": "语义：“菜谱”讲的是做菜的方法，与说书人讲故事没有关系。", "字帖": "语义：“字帖”是用来练字的，不是说书人讲故事用的书。"}, "sentence_index": 0, "correct_answer": "话本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只话本。", "explanation": "这里应该用〈本〉。话本是书，量词要用“本”，“只”多用于动物，不能用于书。"}, {"text": "演员每天都读一本话本，记住台词。", "explanation": "这里应该用〈剧本〉。话本是说书人讲故事的底本，演员记台词要用剧本。"}, {"text": "我每天在话本上写日记。", "explanation": "这里应该用〈本子〉。话本是讲故事的书，不是供人写字用的本子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话本", "is_correct": true, "explanation": "“话本”里有说书人讲的故事，与“故事很有意思”的语境相符，是正确答案。"}, {"text": "论文", "is_correct": false, "explanation": "语义：“论文”是学术写作，一般不用来讲故事。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：“说明书”介绍产品的使用方法，里面不是有意思的故事。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：“名片”用来介绍个人身份，不能说“名片里的故事”。"}], "explanations": {"话本": "“话本”里有说书人讲的故事，与“故事很有意思”的语境相符，是正确答案。", "论文": "语义：“论文”是学术写作，一般不用来讲故事。", "说明书": "语义：“说明书”介绍产品的使用方法，里面不是有意思的故事。", "名片": "搭配：“名片”用来介绍个人身份，不能说“名片里的故事”。"}, "sentence_index": 6, "correct_answer": "话本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈照着话本做了一顿饭。", "explanation": "这里应该用〈菜谱〉。话本是讲故事的书，做饭要照着菜谱。"}, {"text": "我每天用话本擦桌子。", "explanation": "这里应该用〈抹布〉。话本是书，不能用来擦桌子；擦桌子要用〈抹布〉。"}, {"text": "我用话本查不认识的字。", "explanation": "这里应该用〈字典〉。话本是讲故事的书，查生字要用字典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了三个话本。", "corrected_sentence": "他买了三本话本。", "error_description": "量词错误：话本是书，应用量词“本”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候常在晚上读一片话本。", "corrected_sentence": "我小时候常在晚上读一本话本。", "error_description": "量词错误：话本是书，应用量词“本”，不能用“片”（“片”多用于薄而平的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
