INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95927, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "透是从一边穿过去，到达另一边。", "primary_collocate": null, "pronunciation": "tòu", "ipa": "tʰou˥˩", "syllable_count": 1, "sentences": [{"text": "阳光透进了我的房间。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布很薄，光能透过去。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘太厚，一点光也不透。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从屋顶透进来了。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种雨衣很厚，雨水透不进来。", "target_word": "透", "complexity_tier": "T3", "furigana": "zhè zhǒng yǔ yī hěn hòu, yǔ shuǐ tòu bu jìn lái.", "sentence_source": "generated"}, {"text": "灯光从门缝里透出来。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙很厚，声音透不过去。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套很厚，寒风透不进来，冬天很暖和。", "target_word": "透", "complexity_tier": "T3", "furigana": "zhè jiàn wài tào hěn hòu, hán fēng tòu bu jìn lái, dōng tiān hěn nuǎnhuo.", "sentence_source": "generated"}, {"text": "树叶很密，阳光透不下来。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光透过干净的玻璃照进来，屋子里很亮。", "target_word": "透", "complexity_tier": "T3", "furigana": "yáng guāng tòu guò gān jìng de bō li zhào jìn lái, wū zi lǐ hěn liàng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "透过", "label": "复合"}, {"form": "透气", "label": "复合"}, {"form": "透风", "label": "复合"}], "register": "中性", "sense_fingerprint": "透：光、水、风、声音等从一边穿过到另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '981d0e3c-e2be-4751-af4a-301b1d651d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95927, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "透", "is_correct": true, "explanation": "tòu（第四声）是透，意思是从一边穿到另一边。"}, {"text": "头", "is_correct": false, "explanation": "tóu（第二声）与 tòu（第四声）声调不同，意思是头。"}, {"text": "偷", "is_correct": false, "explanation": "tōu（第一声）与 tòu（第四声）声调不同，意思是偷。"}, {"text": "豆", "is_correct": false, "explanation": "dòu 与 tòu 声母不同（d 与 t），意思是豆。"}, {"text": "奏", "is_correct": false, "explanation": "zòu（第四声）与 tòu（第四声）仅声母不同（z 与 t），意思是奏（演奏）。"}, {"text": "扣", "is_correct": false, "explanation": "kòu 与 tòu 声母不同（k 与 t），意思是扣。"}], "explanations": {"透": "tòu（第四声）是透，意思是从一边穿到另一边。", "头": "tóu（第二声）与 tòu（第四声）声调不同，意思是头。", "偷": "tōu（第一声）与 tòu（第四声）声调不同，意思是偷。", "豆": "dòu 与 tòu 声母不同（d 与 t），意思是豆。", "奏": "zòu（第四声）与 tòu（第四声）仅声母不同（z 与 t），意思是奏（演奏）。", "扣": "kòu 与 tòu 声母不同（k 与 t），意思是扣。"}, "sentence_index": null, "correct_answer": "透"}, "level_3": {"options": [{"text": "透", "is_correct": true, "explanation": "透：光从一边穿过门窗进入房间，与句意相符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指人用力移动物体，阳光不能被搬进房间。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”需要有人持握物体，阳光不能作“拿”的主语。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡”是阻拦，与句意中的“进入”方向相反，阳光不能被挡进房间。"}], "explanations": {"透": "透：光从一边穿过门窗进入房间，与句意相符。", "搬": "语义：“搬”指人用力移动物体，阳光不能被搬进房间。", "拿": "搭配：“拿”需要有人持握物体，阳光不能作“拿”的主语。", "挡": "语义：“挡”是阻拦，与句意中的“进入”方向相反，阳光不能被挡进房间。"}, "sentence_index": 0, "correct_answer": "透"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他透上了楼梯，走到了二楼。", "explanation": "这里应该用〈爬〉。透用于光、水、风、声音等穿过物体，人上楼梯要用爬。"}, {"text": "小狗透进了厨房，偷吃了一块肉。", "explanation": "这里应该用〈闯〉。透的主语是光、水、风、声音等，小狗主动冲入某处要用闯。"}, {"text": "我把水透进了杯子里。", "explanation": "这里应该用〈倒〉。透指液体自己渗入或穿过，不能带“把”字宾语；人把水倒进杯子要用倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95927, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "透", "is_correct": true, "explanation": "tòu（第四声）是透，意思是从一边穿到另一边。"}, {"text": "投", "is_correct": false, "explanation": "tóu（第二声）与 tòu（第四声）声调不同，意思是投。"}, {"text": "逗", "is_correct": false, "explanation": "dòu 与 tòu 声母不同（d 与 t），意思是逗。"}, {"text": "后", "is_correct": false, "explanation": "hòu 与 tòu 声母不同（h 与 t），意思是后。"}, {"text": "奏", "is_correct": false, "explanation": "zòu（第四声）与 tòu（第四声）仅声母不同（z 与 t），意思是奏（演奏）。"}, {"text": "叩", "is_correct": false, "explanation": "kòu 与 tòu 声母不同（k 与 t），意思是叩。"}], "explanations": {"透": "tòu（第四声）是透，意思是从一边穿到另一边。", "投": "tóu（第二声）与 tòu（第四声）声调不同，意思是投。", "逗": "dòu 与 tòu 声母不同（d 与 t），意思是逗。", "后": "hòu 与 tòu 声母不同（h 与 t），意思是后。", "奏": "zòu（第四声）与 tòu（第四声）仅声母不同（z 与 t），意思是奏（演奏）。", "叩": "kòu 与 tòu 声母不同（k 与 t），意思是叩。"}, "sentence_index": null, "correct_answer": "透"}, "level_3": {"options": [{"text": "透", "is_correct": true, "explanation": "透：声音穿不过厚墙，与句意相符。"}, {"text": "抬", "is_correct": false, "explanation": "搭配：“抬”需要用手或肩托起重物，声音不能被抬过去。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指把物体投出去，声音无法被扔过墙。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”指用力使物体移动，声音无法被推过墙。"}], "explanations": {"透": "透：声音穿不过厚墙，与句意相符。", "抬": "搭配：“抬”需要用手或肩托起重物，声音不能被抬过去。", "扔": "语义：“扔”指把物体投出去，声音无法被扔过墙。", "推": "语义：“推”指用力使物体移动，声音无法被推过墙。"}, "sentence_index": 6, "correct_answer": "透"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他透进了被窝，躲了起来。", "explanation": "这里应该用〈钻〉。透指光、水、风、声音穿过物体，人钻进被窝要用钻。"}, {"text": "他透进了教室，没有被老师发现。", "explanation": "这里应该用〈溜〉。人悄悄进入某处要用溜，透的主语只能是光、水、风、声音等。"}, {"text": "我把窗帘透进了房间。", "explanation": "这里应该用〈搬〉。透的主语只能是光、水、风、声音等，窗帘是固体，不能透进房间；把窗帘搬进房间要用搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户开着，风能进透来。", "corrected_sentence": "窗户开着，风能透进来。", "error_description": "错误形式：进透来；正确形式：透进来。“透”是动词，“进”是趋向补语，应说“透进来”，颠倒后“进透”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门关得很紧，风透进不来。", "corrected_sentence": "门关得很紧，风透不进来。", "error_description": "错误形式：透进不来；正确形式：透不进来。可能补语的否定“不”应放在动词“透”和趋向补语“进来”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
