INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "连续的号码。", "primary_collocate": null, "pronunciation": "lián hào", "ipa": "ljɛn˧˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "买票时我想要连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个车牌是连号，很好记。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他两个孩子的学号是连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的收据都是连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队的时候，我们拿到了连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连号的座位比较难买。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的房间号是连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几张彩票是连号，不一定会中奖。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他特别喜欢连号的车牌。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个手机号是连号，只差一个数。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数字连续的号码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5f01a3f-0c54-4133-9b25-173d415a41c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连号", "is_correct": true, "explanation": "正确。买票时可以要一组连号的号码或座位，「想要连号」成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是买票时可以「想要」的东西。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能在买票时被「想要」。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：「想要」后接的应是可以获得的具体东西，「感情」与「买票」不搭配。"}], "explanations": {"连号": "正确。买票时可以要一组连号的号码或座位，「想要连号」成立。", "天气": "语义：天气不是买票时可以「想要」的东西。", "海洋": "语义：海洋不能在买票时被「想要」。", "感情": "搭配：「想要」后接的应是可以获得的具体东西，「感情」与「买票」不搭配。"}, "sentence_index": 0, "correct_answer": "连号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天骑连号去上班。", "explanation": "这里应该用〈自行车〉。连号是号码，不是交通工具，不能用「骑」。"}, {"text": "他是我的连号，坐在我旁边。", "explanation": "这里应该用〈同学〉。连号指号码，不指人。"}, {"text": "他每天早上都洗连号。", "explanation": "这里应该用〈衣服〉。连号是号码，不能洗，「洗」要接衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连号", "is_correct": true, "explanation": "正确。房间号是一组连续的号码，可以说是连号。"}, {"text": "价格", "is_correct": false, "explanation": "语义：房间号不是价格，「房间号是价格」说不通。"}, {"text": "红色", "is_correct": false, "explanation": "语义：房间号是数字，不是颜色。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「是」后接的应是号码的类别，「星期」与「房间号」不能这样对应。"}], "explanations": {"连号": "正确。房间号是一组连续的号码，可以说是连号。", "价格": "语义：房间号不是价格，「房间号是价格」说不通。", "红色": "语义：房间号是数字，不是颜色。", "星期": "搭配：「是」后接的应是号码的类别，「星期」与「房间号」不能这样对应。"}, "sentence_index": 6, "correct_answer": "连号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下班后去连号喝茶。", "explanation": "这里应该用〈茶馆〉。连号是号码，不是地方，不能用「去」指向它。"}, {"text": "这家公司的连号很忙。", "explanation": "这里应该用〈老板〉。连号指号码，不指人，不能说「很忙」。"}, {"text": "连号下了一场大雨。", "explanation": "这里应该用〈天气〉。连号是号码，不会下雨，下雨的主语应是天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店给我一个连号的收据。", "corrected_sentence": "这家店给我一组连号的收据。", "error_description": "错误形式：「一个连号的收据」用了量词「个」，但「连号」指一组相连的号码，应用「组」。正确形式：「一组连号的收据」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们两家的门牌号在连号。", "corrected_sentence": "他们两家的门牌号是连号。", "error_description": "错误形式：「在连号」。「连号」是号码的类别，不是地点，不能用「在」。正确形式：「是连号」，判断号码属于哪一类要用「是」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
