INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物中相邻两道横墙之间的距离，即房间的宽度。", "primary_collocate": null, "pronunciation": "kāi jiān", "ipa": "kʰaɪ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "这栋楼每个房间的开间都是三米。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师把开间定为四米。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的开间要宽一些，学生才坐得下。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开间是两道墙之间的距离。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人按图纸量好了开间。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图纸上标出了每个开间的尺寸。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的开间比较小。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公楼的开间一般是三米到四米。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开间越大，用的材料越多。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大厅的开间有十二米。", "target_word": "开间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大开间", "label": "复合"}], "register": "中性", "sense_fingerprint": "建筑中相邻两道横墙之间的距离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开间", "is_correct": true, "explanation": "正确：每个房间左右两道墙之间的距离都是三米。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是距离，不能用米来计量。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是重量，用公斤计量，不能说“三米”。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别不是距离，句子说不通。"}], "explanations": {"开间": "正确：每个房间左右两道墙之间的距离都是三米。", "名字": "语义：名字不是距离，不能用米来计量。", "体重": "语义：体重是重量，用公斤计量，不能说“三米”。", "性别": "语义：性别不是距离，句子说不通。"}, "sentence_index": 0, "correct_answer": "开间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这面墙的开间是二十厘米。", "explanation": "这里应该用〈厚度〉。开间指两道墙之间的距离，墙本身的厚度不是开间。"}, {"text": "这张桌子的开间是一米二，正好坐下六个人。", "explanation": "这里应该用〈宽度〉。开间指建筑中相邻两道横墙之间的距离，桌子不是建筑，不能说开间。"}, {"text": "这栋楼的开间有三十米，从地面一直到楼顶。", "explanation": "这里应该用〈高度〉。开间是横向的距离，不指从地面到楼顶的高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开间", "is_correct": true, "explanation": "正确：老房子两道墙之间的距离比较小。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“比较小”不用来形容颜色。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“老”房子的年龄不会比较小，与“老”矛盾。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：房子没有脾气，这句话说不通。"}], "explanations": {"开间": "正确：老房子两道墙之间的距离比较小。", "颜色": "搭配：“比较小”不用来形容颜色。", "年龄": "语义：“老”房子的年龄不会比较小，与“老”矛盾。", "脾气": "语义：房子没有脾气，这句话说不通。"}, "sentence_index": 6, "correct_answer": "开间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大厅的开间是两千万，很贵。", "explanation": "这里应该用〈房价〉。开间是房间的宽度，不是价钱。"}, {"text": "这座大厅的开间是一千立方米，很大。", "explanation": "这里应该用〈容积〉。开间是左右方向的宽度，单位是米，不是体积。"}, {"text": "这座大厅的开间是二十五度，很舒服。", "explanation": "这里应该用〈温度〉。开间是房间的宽度，不是温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋办公楼每层的开间有四宽米。", "corrected_sentence": "这栋办公楼每层的开间有四米宽。", "error_description": "语序错误：数量补语应说“四米宽”，“宽”要放在“米”后面，不能说“四宽米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个大厅的开间有十二米深，能摆下很多桌子。", "corrected_sentence": "这个大厅的开间有十二米宽，能摆下很多桌子。", "error_description": "词义错误：“开间”指左右方向的宽度，应说“有十二米宽”，不能说“十二米深”，“深”指前后方向的距离，那是进深。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95935, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结尾", "is_correct": true, "explanation": "正确：「结尾」与「开头」互为反义，指事情的最后阶段。"}, {"text": "河流", "is_correct": false, "explanation": "河流与「开头」没有反义关系，二者不是同类的事情或阶段。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子与「开头」没有反义关系，它是具体的物体，不是事情的阶段。"}, {"text": "春天", "is_correct": false, "explanation": "春天与「开头」没有反义关系，它是季节，不是事情的阶段。"}], "correct_answer": "结尾", "explanations": {"结尾": "正确：「结尾」与「开头」互为反义，指事情的最后阶段。", "河流": "河流与「开头」没有反义关系，二者不是同类的事情或阶段。", "桌子": "桌子与「开头」没有反义关系，它是具体的物体，不是事情的阶段。", "春天": "春天与「开头」没有反义关系，它是季节，不是事情的阶段。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95935, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结尾", "is_correct": true, "explanation": "正确：「结尾」与「开头」互为反义，指事情的最后阶段。"}, {"text": "白天", "is_correct": false, "explanation": "白天与「开头」没有反义关系，它是时间段，不是事情的阶段。"}, {"text": "书包", "is_correct": false, "explanation": "书包与「开头」没有反义关系，它是具体的物品。"}, {"text": "雨水", "is_correct": false, "explanation": "雨水与「开头」没有反义关系，它是自然现象，不是事情的阶段。"}], "correct_answer": "结尾", "explanations": {"结尾": "正确：「结尾」与「开头」互为反义，指事情的最后阶段。", "白天": "白天与「开头」没有反义关系，它是时间段，不是事情的阶段。", "书包": "书包与「开头」没有反义关系，它是具体的物品。", "雨水": "雨水与「开头」没有反义关系，它是自然现象，不是事情的阶段。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95935, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "开头是一件事刚开始的阶段。", "primary_collocate": null, "pronunciation": "kāi tóu", "ipa": "kʰai̯˥ tʰou̯˧˥", "syllable_count": 2, "sentences": [{"text": "好的开头是成功的一半。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的开头很难，我们花了很多时间。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的开头，我们踢得不好。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一天的开头，我喜欢喝一杯热茶。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作有了一个好开头。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语的开头，我觉得声调很难。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开头有点难，以后会越来越容易。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的开头不太顺利。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人都说，开头最难。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的会议开头很安静。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "開頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开头·名词：一件事情刚开始的阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95935, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开头", "is_correct": true, "explanation": "正确：「开头」指事情刚开始的阶段，与「成功的一半」相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是一件事的阶段，不能说「好的天气是成功的一半」。"}, {"text": "结果", "is_correct": false, "explanation": "语义：结果本身就是成败，不能说它是成功的一半。"}, {"text": "结局", "is_correct": false, "explanation": "搭配：「结局」指收场的部分，「是成功的一半」说的是前期，与收场不搭配。"}], "explanations": {"开头": "正确：「开头」指事情刚开始的阶段，与「成功的一半」相合。", "天气": "语义：天气不是一件事的阶段，不能说「好的天气是成功的一半」。", "结果": "语义：结果本身就是成败，不能说它是成功的一半。", "结局": "搭配：「结局」指收场的部分，「是成功的一半」说的是前期，与收场不搭配。"}, "sentence_index": 0, "correct_answer": "开头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跑步比赛的开头在操场东边。", "explanation": "这里应该用〈起点〉。「开头」指事情刚开始的阶段，不指地点；说比赛的出发地点要用「起点」。"}, {"text": "这支笔的开头很尖。", "explanation": "这里应该用〈笔尖〉。「开头」指事情的最初阶段，不指物体的尖端；说笔的尖端要用「笔尖」。"}, {"text": "这张桌子的开头是红色的。", "explanation": "这里的「开头」指事情的最初阶段，不指物体的一部分，不能用来描述桌子的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开头", "is_correct": true, "explanation": "正确：「开头有点难」指事情刚开始时的困难阶段。"}, {"text": "结尾", "is_correct": false, "explanation": "语义：「以后会越来越容易」说的是之后的时间，结尾之后不再有事，与句意矛盾。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「难」一般不用来形容声音，声音通常说好听或难听。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是一件事的阶段，「颜色有点难」说不通。"}], "explanations": {"开头": "正确：「开头有点难」指事情刚开始时的困难阶段。", "结尾": "语义：「以后会越来越容易」说的是之后的时间，结尾之后不再有事，与句意矛盾。", "声音": "搭配：「难」一般不用来形容声音，声音通常说好听或难听。", "颜色": "语义：颜色不是一件事的阶段，「颜色有点难」说不通。"}, "sentence_index": 6, "correct_answer": "开头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喝了这个开头。", "explanation": "「开头」指事情的最初阶段，不是能喝的东西；这里把它当作饮品来用，与词义不符。"}, {"text": "我们的会议开头很胖。", "explanation": "「开头」指事情的最初阶段，不能形容体形；这里把它当作人的身体来用，与词义不符。"}, {"text": "他的开头比我高。", "explanation": "「开头」只指事情的开始，不指人的身高；这句把它当作人的身体部位来用，与词义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试的开头的很顺利。", "corrected_sentence": "这次考试的开头很顺利。", "error_description": "错误：「开头」后面多加了「的」。正确说法是「这次考试的开头很顺利」，「的」只用在定语「这次考试」后面，「开头」直接作主语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只好开头让我很高兴。", "corrected_sentence": "这个好开头让我很高兴。", "error_description": "错误：「开头」的量词用了「只」。正确是「这个好开头」，「开头」的量词是「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
