INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95936, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结尾", "is_correct": true, "explanation": "正确：「结尾」与「开头」互为反义，指文章的最后部分。"}, {"text": "镜子", "is_correct": false, "explanation": "镜子与「开头」没有反义关系，它是具体的物体。"}, {"text": "树叶", "is_correct": false, "explanation": "树叶与「开头」没有反义关系，它是植物的一部分，不是文章的部分。"}, {"text": "冬天", "is_correct": false, "explanation": "冬天与「开头」没有反义关系，它是季节，不是文章的部分。"}], "correct_answer": "结尾", "explanations": {"结尾": "正确：「结尾」与「开头」互为反义，指文章的最后部分。", "镜子": "镜子与「开头」没有反义关系，它是具体的物体。", "树叶": "树叶与「开头」没有反义关系，它是植物的一部分，不是文章的部分。", "冬天": "冬天与「开头」没有反义关系，它是季节，不是文章的部分。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文章、书信、故事、歌曲等作品最初的部分。", "primary_collocate": null, "pronunciation": "kāi tóu", "ipa": "kʰai̯˥ tʰou̯˧˥", "syllable_count": 2, "sentences": [{"text": "这篇文章的开头写得很好。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的信开头写着“你好”。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你读一下这本书的开头。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说作文的开头要短一点。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢这个电影的开头。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的开头很好听。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把故事的开头又写了一遍。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每段话的开头都要空两格。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的开头怎么写？", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说的开头让我想继续看下去。", "target_word": "开头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "開頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开头·名词：文章、故事、歌曲等最初的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开头", "is_correct": true, "explanation": "正确：「开头」指文章的最初部分，「写得很好」说的正是文章的开头。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋是穿在脚上的鞋，不属于文章，也不能「写得很好」，与句意不合。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：价钱不属于文章的组成部分，「这篇文章的价钱写得很好」说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的身体指标，文章没有体重，「写得很好」说不通。"}], "explanations": {"开头": "正确：「开头」指文章的最初部分，「写得很好」说的正是文章的开头。", "拖鞋": "语义：拖鞋是穿在脚上的鞋，不属于文章，也不能「写得很好」，与句意不合。", "价钱": "语义：价钱不属于文章的组成部分，「这篇文章的价钱写得很好」说不通。", "体重": "语义：体重是人的身体指标，文章没有体重，「写得很好」说不通。"}, "sentence_index": 0, "correct_answer": "开头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的开头很生气，不想理我。", "explanation": "这里的「开头」指文章的最初部分，不会生气，也不会不理人；这里把它当作人来用，与词义不符。"}, {"text": "这把椅子的开头很软。", "explanation": "这里的「开头」指文章或故事的最初部分，不指物体的一部分，不能用来描述椅子。"}, {"text": "作者的开头很高。", "explanation": "「开头」指文章的最初部分，不指人的身高；这句把它当作人的身体部位来用，与词义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开头", "is_correct": true, "explanation": "正确：「把故事的开头又写了一遍」，「开头」是故事的最初部分，可以被写。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：价钱不是故事的组成部分，不能被写，「把故事的价钱又写了一遍」说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：「脚步」指走路的动作或声音，不是故事的组成部分，不能被写。"}, {"text": "体温", "is_correct": false, "explanation": "语义：「体温」是身体的温度，故事的部分没有体温，「写一遍」说不通。"}], "explanations": {"开头": "正确：「把故事的开头又写了一遍」，「开头」是故事的最初部分，可以被写。", "价钱": "语义：价钱不是故事的组成部分，不能被写，「把故事的价钱又写了一遍」说不通。", "脚步": "语义：「脚步」指走路的动作或声音，不是故事的组成部分，不能被写。", "体温": "语义：「体温」是身体的温度，故事的部分没有体温，「写一遍」说不通。"}, "sentence_index": 6, "correct_answer": "开头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的开头很大，放不进书包。", "explanation": "「开头」指文章的最初部分，不是可以放进书包的实物；这里把它当作有体积的东西来用，与词义不符。"}, {"text": "这本小说的开头今天吃了午饭。", "explanation": "「开头」是文章的一部分，不是人，不能作施事去做吃饭这样的动作。"}, {"text": "这本小说的开头很有钱。", "explanation": "「很有钱」只用于人或机构，「开头」是文章的部分，这句与词义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
