INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章有个很好开头。", "corrected_sentence": "这篇文章有个很好的开头。", "error_description": "错误：「很好」修饰「开头」时，中间要加「的」，「很好开头」漏掉了「的」。正确说法是「这篇文章有个很好的开头」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
