INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95939, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "顺是朝着同一个方向走，不拐弯，不对着干。", "primary_collocate": null, "pronunciation": "shùn", "ipa": "ʂwən˥˩", "syllable_count": 1, "sentences": [{"text": "我们顺这条街一直走，不用拐弯。", "target_word": "顺", "complexity_tier": "T3", "furigana": "wǒmen shùn zhè tiáo jiē yìzhí zǒu, bú yòng guǎiwān.", "sentence_source": "generated"}, {"text": "大家顺同一个方向走，没有拐弯。", "target_word": "顺", "complexity_tier": "T3", "furigana": "dàjiā shùn tóng yí ge fāngxiàng zǒu, méiyǒu guǎiwān.", "sentence_source": "generated"}, {"text": "你顺我指的方向走，别拐弯。", "target_word": "顺", "complexity_tier": "T3", "furigana": "nǐ shùn wǒ zhǐ de fāngxiàng zǒu, bié guǎiwān.", "sentence_source": "generated"}, {"text": "他从不跟爸爸对着干，总是顺爸爸的心意。", "target_word": "顺", "complexity_tier": "T3", "furigana": "tā cóng bù gēn bàba duìzhe gàn, zǒngshì shùn bàba de xīnyì.", "sentence_source": "generated"}, {"text": "这条路一直顺河岸延伸，没有拐弯。", "target_word": "顺", "complexity_tier": "T3", "furigana": "zhè tiáo lù yìzhí shùn hé''àn yánshēn, méiyǒu guǎiwān.", "sentence_source": "generated"}, {"text": "我们顺人流往前走。", "target_word": "顺", "complexity_tier": "T3", "furigana": "wǒmen shùn rénliú wǎng qián zǒu.", "sentence_source": "generated"}, {"text": "他想顺大家的想法做，不想吵架。", "target_word": "顺", "complexity_tier": "T3", "furigana": "tā xiǎng shùn dàjiā de xiǎngfǎ zuò, bù xiǎng chǎojià.", "sentence_source": "generated"}, {"text": "梳头发时要顺发丝的方向。", "target_word": "顺", "complexity_tier": "T3", "furigana": "shū tóufa shí yào shùn fàsī de fāngxiàng.", "sentence_source": "generated"}, {"text": "火车顺铁路开向南方。", "target_word": "顺", "complexity_tier": "T3", "furigana": "huǒchē shùn tiělù kāi xiàng nánfāng.", "sentence_source": "generated"}, {"text": "孩子不听话时，别硬来，先顺他。", "target_word": "顺", "complexity_tier": "T3", "furigana": "háizi bù tīnghuà shí, bié yìng lái, xiān shùn tā.", "sentence_source": "generated"}], "morphological_forms": [{"form": "顺着", "label": "体标"}, {"form": "顺了", "label": "体标"}, {"form": "順", "label": "繁体"}], "register": "中性", "sense_fingerprint": "顺:朝同一方向不拐弯，不对着干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95939, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顺", "is_correct": true, "explanation": "正确答案。顺 shùn：朝同一方向走，不拐弯，或不对着干。"}, {"text": "睡", "is_correct": false, "explanation": "shuì（第四声）与 shùn 韵尾不同（-ui 对 -un），意思是睡觉。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shùn 韵母不同（a 对 u），意思是善良、擅长。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shùn 韵母不同（e 对 u），意思是谨慎。"}, {"text": "润", "is_correct": false, "explanation": "rùn（第四声）与 shùn 声母不同（r 对 sh），意思是湿润、滋润。"}], "explanations": {"顺": "正确答案。顺 shùn：朝同一方向走，不拐弯，或不对着干。", "睡": "shuì（第四声）与 shùn 韵尾不同（-ui 对 -un），意思是睡觉。", "善": "shàn（第四声）与 shùn 韵母不同（a 对 u），意思是善良、擅长。", "慎": "shèn（第四声）与 shùn 韵母不同（e 对 u），意思是谨慎。", "润": "rùn（第四声）与 shùn 声母不同（r 对 sh），意思是湿润、滋润。"}, "sentence_index": null, "correct_answer": "顺"}, "level_3": {"options": [{"text": "顺", "is_correct": true, "explanation": "正确。这里的“顺”表示沿着，“顺这条街一直走”即沿这条街朝同一方向走。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能带“这条街”表示行走路线，“甜这条街一直走”不通。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容体形，不能带处所宾语，“胖这条街一直走”不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是流泪的动作，不能表示沿某条路走，“哭这条街一直走”不通。"}], "explanations": {"顺": "正确。这里的“顺”表示沿着，“顺这条街一直走”即沿这条街朝同一方向走。", "甜": "语义：“甜”形容味道，不能带“这条街”表示行走路线，“甜这条街一直走”不通。", "胖": "语义：“胖”形容体形，不能带处所宾语，“胖这条街一直走”不通。", "哭": "语义：“哭”是流泪的动作，不能表示沿某条路走，“哭这条街一直走”不通。"}, "sentence_index": 0, "correct_answer": "顺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次项目进展得很顺，提前完成了。", "explanation": "这里的“顺”是〈顺利〉的意思（事情进展顺利），与“不对着干、依从”的意思不符。"}, {"text": "这首歌唱起来很顺口，大家都会唱。", "explanation": "这里的“顺”是〈顺口〉的意思（唱起来省力），与“朝同一方向走、依从”的意思不符。"}, {"text": "这把剪刀用起来很顺手，一点也不费劲。", "explanation": "这里的“顺”是〈顺手〉的意思（用着方便），与“不对着干、依从”的意思不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95939, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺", "is_correct": true, "explanation": "正确。这里的“顺”表示依照、顺着别人的想法做事。"}, {"text": "背", "is_correct": false, "explanation": "语义：“背”是背驮或背诵，“背大家的想法做”不通，与依照别人的想法无关。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是击打、切断，与“按想法做事”的意思不相干，句子说不通。"}, {"text": "躲", "is_correct": false, "explanation": "配价：“躲”不能直接带“想法”作宾语表示依照，“躲大家的想法做”不成立。"}], "explanations": {"顺": "正确。这里的“顺”表示依照、顺着别人的想法做事。", "背": "语义：“背”是背驮或背诵，“背大家的想法做”不通，与依照别人的想法无关。", "砍": "语义：“砍”是击打、切断，与“按想法做事”的意思不相干，句子说不通。", "躲": "配价：“躲”不能直接带“想法”作宾语表示依照，“躲大家的想法做”不成立。"}, "sentence_index": 6, "correct_answer": "顺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服看着很顺眼，我很喜欢。", "explanation": "这里的“顺”是〈顺眼〉的意思（看着舒服），与“朝同一方向走、不对着干”的意思不符。"}, {"text": "她顺产生下了一个女儿，母女平安。", "explanation": "这里的“顺”是〈顺产〉的意思（自然分娩），与“依从”义不符。"}, {"text": "这段旋律听着很顺耳。", "explanation": "这里的“顺”是〈顺耳〉的意思（听着舒服），与“依从”义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汽车顺了公路往前开。", "corrected_sentence": "汽车顺着公路往前开。", "error_description": "错误形式：“顺了公路”；正确形式：“顺着公路”。“顺了”表示依从别人的意愿，沿路线行进要用“顺着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子顺过台阶走下来。", "corrected_sentence": "孩子顺着台阶走下来。", "error_description": "错误形式：“顺过台阶”；正确形式：“顺着台阶”。“过”表示经历，不能接在“顺”后表示沿着某处走；沿台阶走要说“顺着台阶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95940, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95940, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆", "is_correct": true, "explanation": "正确。“逆”指方向相反，“逆着河边走”与“顺河边走”的方向正好相反，是反义关系。"}, {"text": "停", "is_correct": false, "explanation": "“停”表示停止不动，与“顺”的行进方向义没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”说的是行走的快慢和方式，与“顺”的方向义没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "“站”表示站立不动，与“顺”的行进方向义没有反义关系。"}], "correct_answer": "逆", "explanations": {"逆": "正确。“逆”指方向相反，“逆着河边走”与“顺河边走”的方向正好相反，是反义关系。", "停": "“停”表示停止不动，与“顺”的行进方向义没有反义关系。", "跑": "“跑”说的是行走的快慢和方式，与“顺”的方向义没有反义关系。", "站": "“站”表示站立不动，与“顺”的行进方向义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "朝着同一个方向；沿着；依从。", "primary_collocate": null, "pronunciation": "shùn", "ipa": "ʂwən˥˩", "syllable_count": 1, "sentences": [{"text": "你顺这条路往前走，就到车站了。", "target_word": "顺", "complexity_tier": "T3", "furigana": "nǐ shùn zhè tiáo lù wǎng qián zǒu, jiù dào chēzhàn le.", "sentence_source": "generated"}, {"text": "我们顺河边走了很久。", "target_word": "顺", "complexity_tier": "T3", "furigana": "wǒmen shùn hé biān zǒu le hěn jiǔ.", "sentence_source": "generated"}, {"text": "他顺扶手往上走，到了二楼。", "target_word": "顺", "complexity_tier": "T3", "furigana": "tā shùn fúshǒu wǎng shàng zǒu, dào le èr lóu.", "sentence_source": "generated"}, {"text": "孩子小的时候，妈妈总是顺他的心意。", "target_word": "顺", "complexity_tier": "T3", "furigana": "háizi xiǎo de shíhou, māma zǒngshì shùn tā de xīnyì.", "sentence_source": "generated"}, {"text": "你别总顺孩子的意，他会变得不听话。", "target_word": "顺", "complexity_tier": "T3", "furigana": "nǐ bié zǒng shùn háizi de yì, tā huì biàn de bù tīnghuà.", "sentence_source": "generated"}, {"text": "切木板要顺纹理下刀。", "target_word": "顺", "complexity_tier": "T3", "furigana": "qiē mùbǎn yào shùn wénlǐ xiàdāo.", "sentence_source": "generated"}, {"text": "小猫顺树干往上爬，爬到了房顶上。", "target_word": "顺", "complexity_tier": "T3", "furigana": "xiǎo māo shùn shùgàn wǎng shàng pá, pá dào le fángdǐng shàng.", "sentence_source": "generated"}, {"text": "雨水顺玻璃流下来。", "target_word": "顺", "complexity_tier": "T3", "furigana": "yǔshuǐ shùn bōli liú xiàlái.", "sentence_source": "generated"}, {"text": "老师说得对，我就顺他的意思做了。", "target_word": "顺", "complexity_tier": "T3", "furigana": "lǎoshī shuō de duì, wǒ jiù shùn tā de yìsi zuò le.", "sentence_source": "generated"}, {"text": "顺河边走，你会看到一座桥。", "target_word": "顺", "complexity_tier": "T3", "furigana": "shùn hé biān zǒu, nǐ huì kàndào yí zuò qiáo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "顺着", "label": "体标"}, {"form": "顺了", "label": "体标"}, {"form": "順", "label": "繁体"}], "register": "中性", "sense_fingerprint": "顺:沿着某物前进或依从别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顺", "is_correct": true, "explanation": "正确答案。顺 shùn：朝同一方向前进，沿着某物走，或依从别人。"}, {"text": "睡", "is_correct": false, "explanation": "shuì（第四声）与 shùn 韵尾不同（-ui 对 -un），意思是睡觉。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shùn 韵母不同（a 对 u），意思是善良、擅长。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shùn 韵母不同（e 对 u），意思是谨慎。"}, {"text": "润", "is_correct": false, "explanation": "rùn（第四声）与 shùn 声母不同（r 对 sh），意思是湿润、滋润。"}], "explanations": {"顺": "正确答案。顺 shùn：朝同一方向前进，沿着某物走，或依从别人。", "睡": "shuì（第四声）与 shùn 韵尾不同（-ui 对 -un），意思是睡觉。", "善": "shàn（第四声）与 shùn 韵母不同（a 对 u），意思是善良、擅长。", "慎": "shèn（第四声）与 shùn 韵母不同（e 对 u），意思是谨慎。", "润": "rùn（第四声）与 shùn 声母不同（r 对 sh），意思是湿润、滋润。"}, "sentence_index": null, "correct_answer": "顺"}, "level_3": {"options": [{"text": "顺", "is_correct": true, "explanation": "正确。这里的“顺”表示沿着，“顺这条路往前走”即沿这条路走。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食的动作，“吃这条路往前走”句意说不通。"}, {"text": "避", "is_correct": false, "explanation": "配价：“避”后接处所要说“避开”，“避这条路”不成立，也与“往前走”矛盾。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是躲开、回避，与“沿这条路往前走到车站”的意思相反。"}], "explanations": {"顺": "正确。这里的“顺”表示沿着，“顺这条路往前走”即沿这条路走。", "吃": "语义：“吃”是进食的动作，“吃这条路往前走”句意说不通。", "避": "配价：“避”后接处所要说“避开”，“避这条路”不成立，也与“往前走”矛盾。", "躲": "语义：“躲”是躲开、回避，与“沿这条路往前走到车站”的意思相反。"}, "sentence_index": 0, "correct_answer": "顺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段时间一切都很顺，工作和生活都没有烦恼。", "explanation": "这里的“顺”是〈顺利〉的意思（事情进展顺利），与“依从”义不符，句中没有需要依从的人或意愿。"}, {"text": "这支笔用起来很顺，写字一点也不卡。", "explanation": "这里的“顺”是〈顺手〉的意思（用着方便），与“依从”义不符。"}, {"text": "他顺口说了一句玩笑话，大家都笑了。", "explanation": "这里的“顺”是〈随口〉的意思（不假思索地说出口），与“依从”义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺", "is_correct": true, "explanation": "正确。这里的“顺”表示沿着，“顺树干往上爬”即沿着树干向上爬。"}, {"text": "背", "is_correct": false, "explanation": "语义：“背”是用背驮或背诵，“背树干往上爬”与攀爬的动作不符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是击打、切断，与小猫沿树干向上爬的动作相冲突。"}, {"text": "撞", "is_correct": false, "explanation": "搭配：“撞”后接“树干”可以，但“撞树干往上爬”不通，搭配不当。"}], "explanations": {"顺": "正确。这里的“顺”表示沿着，“顺树干往上爬”即沿着树干向上爬。", "背": "语义：“背”是用背驮或背诵，“背树干往上爬”与攀爬的动作不符。", "砍": "语义：“砍”是击打、切断，与小猫沿树干向上爬的动作相冲突。", "撞": "搭配：“撞”后接“树干”可以，但“撞树干往上爬”不通，搭配不当。"}, "sentence_index": 6, "correct_answer": "顺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服看着很顺眼，我很喜欢。", "explanation": "这里的“顺”是〈顺眼〉的意思（看着舒服），与“沿着、朝同一方向走”的意思不符，句中没有可走的路线。"}, {"text": "她昨天顺产生下了一个男孩。", "explanation": "这里的“顺”是〈顺产〉的意思（自然分娩），与“沿河边走”的方向义不符。"}, {"text": "这段旋律听起来很顺耳。", "explanation": "这里的“顺”是〈顺耳〉的意思（听着舒服），与“依从”义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们顺了小路走到了湖边。", "corrected_sentence": "我们顺着小路走到了湖边。", "error_description": "错误形式：“顺了小路”；正确形式：“顺着小路”。沿某条路走要用“顺着”，“顺了”表示依从别人的意愿，不能接路线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫顺过墙根跑过去。", "corrected_sentence": "猫顺着墙根跑过去。", "error_description": "错误形式：“顺过墙根”；正确形式：“顺着墙根”。“过”表示经历，不能接在“顺”后表示沿着某处走；沿墙根走要说“顺着墙根”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
