INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "发带是绑头发或戴在头上的带子。", "primary_collocate": null, "pronunciation": "fà dài", "ipa": "fa˥˩ tai˥˩", "syllable_count": 2, "sentences": [{"text": "她用一条红发带绑头发。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动的时候，他头上戴着发带。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的发带掉在地上了。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹买了一条新发带。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条发带是妈妈送我的。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发用发带绑起来了。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时，发带能挡住汗水。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发带太紧，头有点疼。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柜子里放着很多颜色的发带。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把发带戴在头上，很好看。", "target_word": "发带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "髮帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发带：绑头发或戴在头上的带子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '981d0e3c-e2be-4751-af4a-301b1d651d32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95943, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发带", "is_correct": true, "explanation": "发带：能把头发绑起来的带子，与句意相符。"}, {"text": "项链", "is_correct": false, "explanation": "语义：“项链”是戴在颈上的装饰，不能用来绑头发。"}, {"text": "手链", "is_correct": false, "explanation": "语义：“手链”戴在手腕上，不能用来绑头发。"}, {"text": "围裙", "is_correct": false, "explanation": "语义：围裙是系在身前防污的衣物，不能用来绑头发。"}], "explanations": {"发带": "发带：能把头发绑起来的带子，与句意相符。", "项链": "语义：“项链”是戴在颈上的装饰，不能用来绑头发。", "手链": "语义：“手链”戴在手腕上，不能用来绑头发。", "围裙": "语义：围裙是系在身前防污的衣物，不能用来绑头发。"}, "sentence_index": 0, "correct_answer": "发带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹买了一把新发带。", "explanation": "这里应该用〈条〉。发带细长，量词用“条”；“把”用于有柄或有把手的东西。"}, {"text": "他用发带刷牙。", "explanation": "这里应该用〈牙刷〉。发带是束头发或戴在头上的带子，刷牙要用牙刷。"}, {"text": "她把发带戴在手上，手很暖和。", "explanation": "这里应该用〈手套〉。发带是戴在头上的，能让手暖和的应是手套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发带", "is_correct": true, "explanation": "发带：戴在头上、能挡住汗水的带子，与句意相符。"}, {"text": "腰带", "is_correct": false, "explanation": "语义：“腰带”系在腰间，不能挡住额头上的汗水。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”穿在脚上，与挡汗水的功能毫无关系。"}, {"text": "耳环", "is_correct": false, "explanation": "搭配：“耳环”戴在耳朵上，与“挡住汗水”搭配不当。"}], "explanations": {"发带": "发带：戴在头上、能挡住汗水的带子，与句意相符。", "腰带": "语义：“腰带”系在腰间，不能挡住额头上的汗水。", "鞋子": "语义：“鞋子”穿在脚上，与挡汗水的功能毫无关系。", "耳环": "搭配：“耳环”戴在耳朵上，与“挡住汗水”搭配不当。"}, "sentence_index": 6, "correct_answer": "发带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把发带戴在手指上，很好看。", "explanation": "这里应该用〈戒指〉。戒指套在手指上，发带是戴在头上的带子，不能戴在手指上。"}, {"text": "桌子上铺着一条发带。", "explanation": "这里应该用〈桌布〉。发带是束发或戴在头上的带子，铺在桌上要用桌布。"}, {"text": "她把发带吃了，肚子很饱。", "explanation": "这里应该用〈饼干〉。饼干可以吃，发带是束头发或戴在头上的带子，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她戴着一张发带，跑得很快。", "corrected_sentence": "她戴着一条发带，跑得很快。", "error_description": "错误形式：一张发带；正确形式：一条发带。发带是细长的带子，量词应用“条”；“张”用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的几条发带们都很漂亮。", "corrected_sentence": "我的几条发带都很漂亮。", "error_description": "错误形式：发带们；正确形式：发带。“们”只用于指人的名词，发带是物品，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c93faa-b202-4039-852d-c7269b0ca56e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
