INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95946, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示合计、总共。", "primary_collocate": null, "pronunciation": "yí gòng", "ipa": "i˧˥ kʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们班一共有二十个学生。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书一共五十块钱。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一共买了三斤苹果。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一共去过两次北京。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我一共看了四部电影。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上一共放着五个杯子。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家一共有六口人。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行一共花了三千块。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一共写了十封信。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我们一共走了八公里。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一共：副词，陈述合计、总共的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d4986a0-230f-4048-a49e-666580b97150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一共", "is_correct": true, "explanation": "正确：“一共”是副词，表示合计，符合“二十个学生”的总数语境。"}, {"text": "共同", "is_correct": false, "explanation": "语义：“共同”表示一起、共有，不表示合计数量，这里说不通。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”表示格外、程度高，不能用来说明班里学生的总数。"}, {"text": "颇", "is_correct": false, "explanation": "语域：“颇”是书面语，口语里不用，且表示“相当”，不表示合计。"}], "explanations": {"一共": "正确：“一共”是副词，表示合计，符合“二十个学生”的总数语境。", "共同": "语义：“共同”表示一起、共有，不表示合计数量，这里说不通。", "特别": "语义：“特别”表示格外、程度高，不能用来说明班里学生的总数。", "颇": "语域：“颇”是书面语，口语里不用，且表示“相当”，不表示合计。"}, "sentence_index": 0, "correct_answer": "一共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他一共散步。", "explanation": "这里应该用〈一起〉。一共表示数量的合计，不表示共同行动，共同做某事应说“一起”。"}, {"text": "他一共在学习。", "explanation": "这里应该用〈一直〉。一共表示合计，不表示动作持续不断。"}, {"text": "他一共十八岁。", "explanation": "这里应该用〈今年〉。一共表示合计，不能用来说明年龄；说年龄应该用“他今年十八岁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一共", "is_correct": true, "explanation": "正确：“一共”表示合计，符合“六口人”的总数语境。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能修饰“有六口人”这样的数量表达，这里说不通。"}, {"text": "互相", "is_correct": false, "explanation": "语义：“互相”表示双方相互对待，后面要接相互的动作，不能说明家里人数的总和。"}, {"text": "尽量", "is_correct": false, "explanation": "搭配：“尽量”后接动作性动词，不能与“有”这类存在动词搭配，这里说不通。"}], "explanations": {"一共": "正确：“一共”表示合计，符合“六口人”的总数语境。", "非常": "搭配：“非常”是程度副词，不能修饰“有六口人”这样的数量表达，这里说不通。", "互相": "语义：“互相”表示双方相互对待，后面要接相互的动作，不能说明家里人数的总和。", "尽量": "搭配：“尽量”后接动作性动词，不能与“有”这类存在动词搭配，这里说不通。"}, "sentence_index": 6, "correct_answer": "一共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一共出发了。", "explanation": "这里应该用〈一起〉。一共表示数量的合计，不表示共同行动；“我们一起出发了”才是共同行动。"}, {"text": "他一共在吃饭。", "explanation": "这里应该用〈正在〉。一共表示合计数量，不能表示动作正在进行。"}, {"text": "明天一共会下雨。", "explanation": "这里应该用〈将会〉。一共表示合计，不能表示将要发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班一共有学生。", "corrected_sentence": "我们班一共有三十个学生。", "error_description": "“一共”表示合计，后面必须有具体数量。这里缺少数量词，应说“我们班一共有三十个学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一共背了单词。", "corrected_sentence": "他一共背了十个单词。", "error_description": "“一共”表示合计，后面必须有具体数量。这里缺少数量词，应说“他一共背了十个单词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
