INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95947, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上演是在台上给大家演出。", "primary_collocate": null, "pronunciation": "shàng yǎn", "ipa": "ʂɑŋ⁵¹ jɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "孩子们在台上上演了一出小话剧。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校礼堂里正在上演一出新戏。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚剧团在大剧院上演了京剧。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧团每年春节都会上演新戏。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上正上演着一场精彩的舞剧。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们打算在毕业晚会上上演一个小节目。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在小城的广场上上演过这出戏。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们在舞台上上演了一出动人的话剧。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的舞台上将上演一场音乐剧。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧团到各个村子里上演这出老戏。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上演了", "label": "完成体"}, {"form": "上演过", "label": "经历体"}, {"form": "上演着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "演员在舞台上当众演出节目或戏剧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上演", "is_correct": true, "explanation": "正确：“上演”指在台上公开演出话剧，符合句意。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：“放映”多用于电影，不能说在台上放映一出话剧。"}, {"text": "收看", "is_correct": false, "explanation": "搭配：“收看”指看电视、网络节目，不能用于在台上观看话剧。"}, {"text": "编写", "is_correct": false, "explanation": "语义：“编写”指写作剧本，与句中在台上演出的场景不符。"}], "explanations": {"上演": "正确：“上演”指在台上公开演出话剧，符合句意。", "放映": "搭配：“放映”多用于电影，不能说在台上放映一出话剧。", "收看": "搭配：“收看”指看电视、网络节目，不能用于在台上观看话剧。", "编写": "语义：“编写”指写作剧本，与句中在台上演出的场景不符。"}, "sentence_index": 0, "correct_answer": "上演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这部电视剧里上演了一个小角色。", "explanation": "这里应该用〈参演〉。“上演”指剧目在台上公开演出，不能用来说某人担任了角色。"}, {"text": "歌手在演唱会上上演了一首新歌。", "explanation": "这里应该用〈演唱〉。“上演”用于戏剧、节目等整出或整场的演出，单独一首歌要说演唱。"}, {"text": "这家商店在橱窗里上演了一排新款手表。", "explanation": "这里应该用〈陈列〉。“上演”指在台上给观众演出节目，把商品摆出来展示要说陈列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上演", "is_correct": true, "explanation": "正确：“上演”指在广场上公开演出过这出戏，符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑、设施，不能说拆除一出戏。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是票或物品，不能说在广场上购买过一出戏。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指把作品印刷发行，与在广场上演出的场景不符。"}], "explanations": {"上演": "正确：“上演”指在广场上公开演出过这出戏，符合句意。", "拆除": "搭配：“拆除”的对象是建筑、设施，不能说拆除一出戏。", "购买": "搭配：“购买”的对象是票或物品，不能说在广场上购买过一出戏。", "出版": "语义：“出版”指把作品印刷发行，与在广场上演出的场景不符。"}, "sentence_index": 6, "correct_answer": "上演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小王在班会上上演了一段发言。", "explanation": "这里应该用〈发言〉。“上演”用于戏剧、节目等整出的公开演出，在班会上讲话要说发言。"}, {"text": "学校下个月上演一场画展。", "explanation": "这里应该用〈举办〉。“上演”用于戏剧、节目等演出，画展是展览，要说举办。"}, {"text": "他去年上演了一篇论文。", "explanation": "这里应该用〈发表〉。“上演”用于戏剧、节目等演出，论文是书面成果，要说发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "剧团在县城的礼堂里上演了过一出古装戏。", "corrected_sentence": "剧团在县城的礼堂里上演了一出古装戏。", "error_description": "“了”与“过”不能同时用在“上演”后。这里说的是已经完成的演出，只用“了”，应去掉“过”，说“上演了一出古装戏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今晚的舞台上正在上演了一场音乐剧。", "corrected_sentence": "今晚的舞台上正在上演一场音乐剧。", "error_description": "“正在”表示动作进行中，不能与表示完成的“了”同用，应去掉“了”，说“正在上演一场音乐剧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
