INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "戏剧、电影等演出或放映。", "primary_collocate": null, "pronunciation": "shàng yǎn", "ipa": "ʂɑŋ⁵¹ jɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "这部电影下个月在全国上演。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那部老电影今晚在电影院上演。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新戏上演以后，很多人去看了。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影只上演了三天。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里正上演着一部新的喜剧片。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部话剧在北京上演过很多次。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好电影一上演，大家都想去看。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画片暑假会在各大电影院上演。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说周末电影节会上演几部老片子。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那出戏上演的时候，我正在国外。", "target_word": "上演", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上演了", "label": "完成体"}, {"form": "上演过", "label": "经历体"}, {"form": "上演着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "戏剧、电影等公开演出或放映", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上演", "is_correct": true, "explanation": "正确：“上演”指电影公开放映，符合“在全国上演”的句意。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”用于乐器和乐曲，不能用于电影。"}, {"text": "印刷", "is_correct": false, "explanation": "语义：“印刷”指把文字图片印在纸上，与电影放映无关。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：“朗读”用于文字，不能说在全国朗读一部电影。"}], "explanations": {"上演": "正确：“上演”指电影公开放映，符合“在全国上演”的句意。", "演奏": "搭配：“演奏”用于乐器和乐曲，不能用于电影。", "印刷": "语义：“印刷”指把文字图片印在纸上，与电影放映无关。", "朗读": "搭配：“朗读”用于文字，不能说在全国朗读一部电影。"}, "sentence_index": 0, "correct_answer": "上演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这部电影里上演了一个配角。", "explanation": "这里应该用〈参演〉。“上演”说的是影片公开放映或演出，不能用来说某人在片中担任配角。"}, {"text": "这本小说去年上演了。", "explanation": "这里应该用〈出版〉。“上演”只用于戏剧、电影等公开演出或放映，小说是印刷出版的，不能说上演。"}, {"text": "乐队在公园里上演了三首曲子。", "explanation": "这里应该用〈演奏〉。“上演”用于戏剧、电影等整部作品的演出，乐曲要说演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上演", "is_correct": true, "explanation": "正确：“上演”指好电影公开放映，符合“一上演，大家都想去看”的句意。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：“演唱”用于歌曲，不能说好电影一演唱。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”指公开发布言论或作品，与电影放映不符。"}, {"text": "写作", "is_correct": false, "explanation": "语义：“写作”指创作文字，与句中电影放映的语境不符。"}], "explanations": {"上演": "正确：“上演”指好电影公开放映，符合“一上演，大家都想去看”的句意。", "演唱": "搭配：“演唱”用于歌曲，不能说好电影一演唱。", "发表": "语义：“发表”指公开发布言论或作品，与电影放映不符。", "写作": "语义：“写作”指创作文字，与句中电影放映的语境不符。"}, "sentence_index": 6, "correct_answer": "上演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试下周在体育馆上演。", "explanation": "这里应该用〈举行〉。“上演”用于戏剧、电影等公开演出或放映，考试要说举行。"}, {"text": "这张专辑上个月上演了。", "explanation": "这里应该用〈发行〉。专辑是录音制品，要说发行；“上演”只用于戏剧、电影等公开演出或放映。"}, {"text": "博物馆正在上演一批古画。", "explanation": "这里应该用〈展出〉。“上演”用于戏剧、电影等演出，古画要说展出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影去年上演了过三次。", "corrected_sentence": "这部电影去年上演过三次。", "error_description": "“了”与“过”不能同时用在“上演”后。这里表示曾经有过的经历，只用“过”，应去掉“了”，说“上演过三次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部动画片正在各大电影院上演过。", "corrected_sentence": "这部动画片正在各大电影院上演。", "error_description": "“正在”表示动作正在进行，不能和表示过去经历的“过”同用，应去掉“过”，说“正在各大电影院上演”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
