INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95949, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "仿佛是看起来像，其实不是。", "primary_collocate": null, "pronunciation": "fǎng fú", "ipa": "faŋ˨˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "月光下，湖面仿佛一面大镜子。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白云仿佛一朵朵大棉花。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，她仿佛变成了小孩。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后的山仿佛穿上了白衣服。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在那儿，仿佛一棵老树。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的城市仿佛一片星星的海洋。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的山仿佛一幅水墨画。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，仿佛一个小天使。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老朋友，他仿佛回到了二十年前。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的灯光仿佛天上的星星。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彷彿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用于比喻，表示看起来像某物或某种情况，其实并不是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1736f8c-b416-42c2-9d2b-c556b9cf59db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95949, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：仿佛（fǎng fú），表示“看起来像某物”的比喻。"}, {"text": "防腐", "is_correct": false, "explanation": "防腐（fáng fǔ）：fǎng（第三声）与 fáng（第二声）声调不同，fú（第二声）与 fǔ（第三声）声调不同；意思是防止食物腐烂。"}, {"text": "反复", "is_correct": false, "explanation": "反复（fǎn fù）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fù（第四声）声调不同；意思是重复或来回。"}, {"text": "反腐", "is_correct": false, "explanation": "反腐（fǎn fǔ）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fǔ（第三声）声调不同；意思是反对腐败。"}], "explanations": {"仿佛": "正确答案：仿佛（fǎng fú），表示“看起来像某物”的比喻。", "防腐": "防腐（fáng fǔ）：fǎng（第三声）与 fáng（第二声）声调不同，fú（第二声）与 fǔ（第三声）声调不同；意思是防止食物腐烂。", "反复": "反复（fǎn fù）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fù（第四声）声调不同；意思是重复或来回。", "反腐": "反腐（fǎn fǔ）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fǔ（第三声）声调不同；意思是反对腐败。"}, "sentence_index": null, "correct_answer": "仿佛"}, "level_3": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：“湖面仿佛一面大镜子”是比喻，与后面的“一面大镜子”搭配。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”要接动词或形容词，表示完成或变化，不能直接接“一面大镜子”这样的名词短语。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生的动作或变化，而“湖面像一面大镜子”是静态的比喻，不能用“忽然”。"}, {"text": "确实", "is_correct": false, "explanation": "搭配：“确实”后面要接判断或谓语，“确实一面大镜子”不成句，需要加上“是”。"}], "explanations": {"仿佛": "正确答案：“湖面仿佛一面大镜子”是比喻，与后面的“一面大镜子”搭配。", "已经": "搭配：“已经”要接动词或形容词，表示完成或变化，不能直接接“一面大镜子”这样的名词短语。", "忽然": "语义：“忽然”表示突然发生的动作或变化，而“湖面像一面大镜子”是静态的比喻，不能用“忽然”。", "确实": "搭配：“确实”后面要接判断或谓语，“确实一面大镜子”不成句，需要加上“是”。"}, "sentence_index": 0, "correct_answer": "仿佛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山仿佛是我们学校的操场，昨天刚有人在这里开过运动会。", "explanation": "这里应该用〈就是〉。仿佛表示“看起来像，其实不是”，而句中断定它就是操场，与这一意思相反。"}, {"text": "我们的老师仿佛是一位真正的医生，每天都在医院值班。", "explanation": "这里应该用〈的确〉。仿佛表示“看起来像，其实不是”，而句中陈述的是老师的实际身份，用仿佛会与语义冲突。"}, {"text": "这次比赛仿佛是我赢的，奖杯就在我的书包里。", "explanation": "这里应该用〈确实〉。仿佛表示“看起来像，其实不是”，而句中“奖杯就在我的书包里”说明事实已经确定，与仿佛的比喻义冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95949, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：仿佛（fǎng fú），表示“看起来像某物”的比喻。"}, {"text": "丰富", "is_correct": false, "explanation": "丰富（fēng fù）：fǎng（第三声）与 fēng（第一声）的韵腹不同（a 与 e），fú（第二声）与 fù（第四声）声调不同；意思是种类或数量多。"}, {"text": "往复", "is_correct": false, "explanation": "往复（wǎng fù）：声母 f 与 w 不同，fú（第二声）与 fù（第四声）声调不同；意思是来回运动。"}, {"text": "仿古", "is_correct": false, "explanation": "仿古（fǎng gǔ）：第一个音节相同，第二个音节声母不同（f 与 g），声调也不同；意思是模仿古代的样式。"}], "explanations": {"仿佛": "正确答案：仿佛（fǎng fú），表示“看起来像某物”的比喻。", "丰富": "丰富（fēng fù）：fǎng（第三声）与 fēng（第一声）的韵腹不同（a 与 e），fú（第二声）与 fù（第四声）声调不同；意思是种类或数量多。", "往复": "往复（wǎng fù）：声母 f 与 w 不同，fú（第二声）与 fù（第四声）声调不同；意思是来回运动。", "仿古": "仿古（fǎng gǔ）：第一个音节相同，第二个音节声母不同（f 与 g），声调也不同；意思是模仿古代的样式。"}, "sentence_index": null, "correct_answer": "仿佛"}, "level_3": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：“远处的山仿佛一幅水墨画”是比喻，表示远处的山看起来像一幅画。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚发生的事，而“山像一幅水墨画”是持续的比喻状态，不能用“刚刚”。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”要接动作或状态谓语，不能直接接“一幅水墨画”这样的名词短语。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”说明有意识的行为，山不能有意做什么，与比喻的意思不符。"}], "explanations": {"仿佛": "正确答案：“远处的山仿佛一幅水墨画”是比喻，表示远处的山看起来像一幅画。", "刚刚": "语义：“刚刚”表示刚发生的事，而“山像一幅水墨画”是持续的比喻状态，不能用“刚刚”。", "一直": "搭配：“一直”要接动作或状态谓语，不能直接接“一幅水墨画”这样的名词短语。", "故意": "语义：“故意”说明有意识的行为，山不能有意做什么，与比喻的意思不符。"}, "sentence_index": 6, "correct_answer": "仿佛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她仿佛是我们班的班长，每天都在管大家。", "explanation": "这里应该用〈正是〉。仿佛表示“看起来像，其实不是”，而句中陈述的是她实际担任的职务，用仿佛会与语义冲突。"}, {"text": "这份计划仿佛全部完成了，负责人昨天就签了字。", "explanation": "这里应该用〈已经〉。仿佛表示“看起来像，其实不是”，而“负责人昨天就签了字”说明事情已经发生，用仿佛会与语境矛盾。"}, {"text": "我们的车仿佛在路上抛锚了，司机刚刚打来了电话。", "explanation": "这里应该用〈真的〉。这句要陈述的是实际发生的事，而仿佛是把甲说成像乙的比喻，用在这里与语境冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里的操场仿佛的一片白色的海。", "corrected_sentence": "夜里的操场仿佛一片白色的海。", "error_description": "错误：“仿佛”后面多加了“的”。“仿佛”是副词，后面不能直接接“的”，正确形式为“夜里的操场仿佛一片白色的海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪后的大地仿佛了一张白纸。", "corrected_sentence": "雪后的大地仿佛一张白纸。", "error_description": "错误：“仿佛”后面多加了“了”。“仿佛”是副词，用来打比方，后面不能接体标记“了”，正确形式为“雪后的大地仿佛一张白纸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
