INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "好像；似乎。", "primary_collocate": null, "pronunciation": "fǎng fú", "ipa": "faŋ˨˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "他仿佛没听见我说的话。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里仿佛有人在说话。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她仿佛有点儿不高兴。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天仿佛要下雨了。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我仿佛在哪儿见过他。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸色仿佛不太好。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家仿佛都忘了今天是他的生日。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外仿佛传来了一阵音乐声。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈仿佛知道我在想什么。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仿佛很累，一进门就睡了。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彷彿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示不太确定的感觉或判断，相当于好像、似乎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1736f8c-b416-42c2-9d2b-c556b9cf59db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。"}, {"text": "防腐", "is_correct": false, "explanation": "防腐（fáng fǔ）：fǎng（第三声）与 fáng（第二声）声调不同，fú（第二声）与 fǔ（第三声）声调不同；意思是防止食物腐烂。"}, {"text": "反复", "is_correct": false, "explanation": "反复（fǎn fù）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fù（第四声）声调不同；意思是重复或来回。"}, {"text": "反腐", "is_correct": false, "explanation": "反腐（fǎn fǔ）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fǔ（第三声）声调不同；意思是反对腐败。"}], "explanations": {"仿佛": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。", "防腐": "防腐（fáng fǔ）：fǎng（第三声）与 fáng（第二声）声调不同，fú（第二声）与 fǔ（第三声）声调不同；意思是防止食物腐烂。", "反复": "反复（fǎn fù）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fù（第四声）声调不同；意思是重复或来回。", "反腐": "反腐（fǎn fǔ）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fǔ（第三声）声调不同；意思是反对腐败。"}, "sentence_index": null, "correct_answer": "仿佛"}, "level_3": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：“他仿佛没听见我说的话”表示一种推测，与句子的语境相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与“没听见”这种结果状态冲突，句子不通。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做某件事，要求有动作，不能修饰“没听见”这种静态状态。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示马上行动，与“没听见”这种状态不能搭配，句子不通。"}], "explanations": {"仿佛": "正确答案：“他仿佛没听见我说的话”表示一种推测，与句子的语境相符。", "正在": "体貌：“正在”表示动作正在进行，与“没听见”这种结果状态冲突，句子不通。", "赶紧": "语义：“赶紧”表示急忙去做某件事，要求有动作，不能修饰“没听见”这种静态状态。", "连忙": "语义：“连忙”表示马上行动，与“没听见”这种状态不能搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "仿佛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我刚才亲眼看见他进了家门，他仿佛已经到家了。", "explanation": "这里应该用〈肯定〉。仿佛表示不确定的推测，而“我刚才亲眼看见他进了家门”是亲身见到的事实，用仿佛会与语境矛盾。"}, {"text": "这份报告仿佛有三处错误，我已经一条一条数过了。", "explanation": "这里应该用〈确实〉。仿佛表示不确定的判断，而“我已经一条一条数过了”说明是确定的事实，用仿佛会与语境矛盾。"}, {"text": "小王这次仿佛考了班里第一，成绩单已经发下来了。", "explanation": "这里应该用〈果然〉。仿佛表示推测，而“成绩单已经发下来了”说明结果已经确定，应表达“如预料那样”的确认，用仿佛会与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。"}, {"text": "丰富", "is_correct": false, "explanation": "丰富（fēng fù）：fǎng（第三声）与 fēng（第一声）的韵腹不同（a 与 e），fú（第二声）与 fù（第四声）声调不同；意思是种类或数量多。"}, {"text": "往复", "is_correct": false, "explanation": "往复（wǎng fù）：声母 f 与 w 不同，fú（第二声）与 fù（第四声）声调不同；意思是来回运动。"}, {"text": "仿古", "is_correct": false, "explanation": "仿古（fǎng gǔ）：第一个音节相同，第二个音节声母不同（f 与 g），声调也不同；意思是模仿古代的样式。"}], "explanations": {"仿佛": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。", "丰富": "丰富（fēng fù）：fǎng（第三声）与 fēng（第一声）的韵腹不同（a 与 e），fú（第二声）与 fù（第四声）声调不同；意思是种类或数量多。", "往复": "往复（wǎng fù）：声母 f 与 w 不同，fú（第二声）与 fù（第四声）声调不同；意思是来回运动。", "仿古": "仿古（fǎng gǔ）：第一个音节相同，第二个音节声母不同（f 与 g），声调也不同；意思是模仿古代的样式。"}, "sentence_index": null, "correct_answer": "仿佛"}, "level_3": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：“大家仿佛都忘了今天是他的生日”表示推测，与“大家都忘了”的语境相符。"}, {"text": "纷纷", "is_correct": false, "explanation": "语义：“纷纷”表示许多人接连做同一动作，不能修饰“忘了”这种一次性的状态。"}, {"text": "即将", "is_correct": false, "explanation": "体貌：“即将”表示即将发生，与“忘了”这种已经完成的情况冲突。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”用于叮嘱、劝告，不能用来陈述“大家都忘了”这一情况。"}], "explanations": {"仿佛": "正确答案：“大家仿佛都忘了今天是他的生日”表示推测，与“大家都忘了”的语境相符。", "纷纷": "语义：“纷纷”表示许多人接连做同一动作，不能修饰“忘了”这种一次性的状态。", "即将": "体貌：“即将”表示即将发生，与“忘了”这种已经完成的情况冲突。", "千万": "语义：“千万”用于叮嘱、劝告，不能用来陈述“大家都忘了”这一情况。"}, "sentence_index": 6, "correct_answer": "仿佛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长仿佛亲自到场了，签到表上还有他的签名。", "explanation": "这里应该用〈显然〉。仿佛表示不确定的推测，而“签到表上还有他的签名”是确定的依据，用仿佛会与语境矛盾。"}, {"text": "工作仿佛完成了，报告我今天上午就交给老板了。", "explanation": "这里应该用〈已经〉。仿佛表示不确定的推测，而“报告今天上午就交给老板了”是具体的已发生事实，用仿佛会让语气显得含糊。"}, {"text": "合同仿佛生效了，所有人都收到了通知。", "explanation": "这里应该用〈真的〉。仿佛表示推测，而“所有人都收到了通知”说明合同已经确定生效，用仿佛会显得不肯定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电话那头仿佛的有人在笑。", "corrected_sentence": "电话那头仿佛有人在笑。", "error_description": "错误：“仿佛”后面多加了“的”。“仿佛”是副词，后面不能直接接“的”，正确形式为“电话那头仿佛有人在笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她仿佛的很有把握。", "corrected_sentence": "她仿佛很有把握。", "error_description": "错误：“仿佛”是副词，后面不能直接接“的”，应删去“的”，正确形式为“她仿佛很有把握”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c22414d1-521c-4334-9260-fd8451a09f0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95951, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95951, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95951, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "来生是人们说的，这辈子以后的下一辈子。", "primary_collocate": null, "pronunciation": "lái shēng", "ipa": "lai˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "我希望来生还能做你的朋友。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果有来生，我还想当老师。", "target_word": "来生", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "她说来生要做一只小鸟。", "target_word": "来生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这辈子太累了，来生想轻松点。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常说，来生再见。", "target_word": "来生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想来生也和妻子在一起。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今生没机会，只能等来生了。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来生我还要嫁给你。", "target_word": "来生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这辈子欠你的，来生再还给你。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说来生做你的哥哥。", "target_word": "来生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "日常说话中表示心愿的下一辈子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作", "is_correct": false, "explanation": "语义：这里要填表示“什么时候”的时间词，“工作”不是时间，不能说“希望工作还能做你的朋友”。"}, {"text": "来生", "is_correct": true, "explanation": "正确：“来生”指这辈子以后的下一辈子，符合“希望还能做你的朋友”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能做人的朋友，与句意矛盾。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能做朋友，与“希望还能做你的朋友”不符。"}], "explanations": {"工作": "语义：这里要填表示“什么时候”的时间词，“工作”不是时间，不能说“希望工作还能做你的朋友”。", "来生": "正确：“来生”指这辈子以后的下一辈子，符合“希望还能做你的朋友”的语境。", "桌子": "语义：桌子不能做人的朋友，与句意矛盾。", "名字": "语义：名字不能做朋友，与“希望还能做你的朋友”不符。"}, "sentence_index": 0, "correct_answer": "来生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期先复习，来生再考虑出国。", "explanation": "这里应该用〈将来〉。“将来”指这辈子以内的以后，“来生”指死后的下一辈子，不能接在“这学期”这样的眼前时段之后。"}, {"text": "这个问题来生再解决，今晚先休息。", "explanation": "这里应该用〈日后〉。“日后”指这辈子以内的某个以后，“来生”指死后的下一辈子，与“今晚先休息”的眼前安排矛盾。"}, {"text": "吃完饭来生再散步吧。", "explanation": "这里应该用〈以后〉。“吃完饭以后”指眼前的先后顺序，“来生”指死后的下一辈子，不能接在吃饭之后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今生", "is_correct": false, "explanation": "语义：“只能等今生了”与“今生没机会”重复矛盾，等待的应是另一世。"}, {"text": "来生", "is_correct": true, "explanation": "正确：“今生没机会，只能等来生了”形成今生与来生的对比，符合句意。"}, {"text": "前世", "is_correct": false, "explanation": "语义：“前世”在今生之前，不能用来表示等待的时间。"}, {"text": "眼前", "is_correct": false, "explanation": "搭配：“等眼前”不能这样搭配，与“只能等”的语境不符。"}], "explanations": {"今生": "语义：“只能等今生了”与“今生没机会”重复矛盾，等待的应是另一世。", "来生": "正确：“今生没机会，只能等来生了”形成今生与来生的对比，符合句意。", "前世": "语义：“前世”在今生之前，不能用来表示等待的时间。", "眼前": "搭配：“等眼前”不能这样搭配，与“只能等”的语境不符。"}, "sentence_index": 6, "correct_answer": "来生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来生三点我们开会。", "explanation": "这里应该用〈下午〉。“来生”指死后的下一辈子，不能指当天的具体时刻。"}, {"text": "我来生去过北京。", "explanation": "这里应该用〈去年〉。“来生”是未来的一辈子，不能与已经发生的过去经历搭配。"}, {"text": "我毕业之后，来生在北京工作。", "explanation": "“来生”指死后的下一辈子，与“毕业之后”这种这辈子之内的先后不能搭配，用在这里是时间混淆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我相信这个来生我们还会相遇。", "corrected_sentence": "我相信来生我们还会相遇。", "error_description": "“来生”是泛指的未来时间，前面不能加“这个”，应说“来生”，“这个来生”不成说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我愿意做你来生妻子。", "corrected_sentence": "我愿意做你来生的妻子。", "error_description": "“来生”修饰“妻子”时要加“的”，应说“来生的妻子”，漏掉“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
