INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95952, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "佛教等所说的人死后的下一辈子。", "primary_collocate": null, "pronunciation": "lái shēng", "ipa": "lai˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "佛教认为人死后会有来生。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信佛的人相信有来生。", "target_word": "来生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "佛教说，今生做好事，来生有好报。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶信佛，常为来生念经。", "target_word": "来生", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在佛教里，来生由今生的行为决定。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和尚说，来生的样子和今生的行为有关。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们相信人死以后还有来生。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "佛教讲因果，今生种什么，来生得什么。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人一生行善，希望来生有福。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "寺里的师父常讲来生和因果。", "target_word": "来生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "佛教等宗教所说的人死后轮回的下一辈子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c50e90-7f0a-4573-b9ea-1cc3625e3a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今生", "is_correct": false, "explanation": "语义：“人死后”之后不会再有“今生”，今生指死前的这一生。"}, {"text": "来生", "is_correct": true, "explanation": "正确：佛教认为人死后轮回的下一辈子就是“来生”，符合句意。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“人死后会有”后面不能接“工作”，两者不搭配。"}, {"text": "前世", "is_correct": false, "explanation": "语义：“前世”指死前的过去生命，与“人死后会有”的说法矛盾。"}], "explanations": {"今生": "语义：“人死后”之后不会再有“今生”，今生指死前的这一生。", "来生": "正确：佛教认为人死后轮回的下一辈子就是“来生”，符合句意。", "工作": "搭配：“人死后会有”后面不能接“工作”，两者不搭配。", "前世": "语义：“前世”指死前的过去生命，与“人死后会有”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "来生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "佛教认为，来生的行为决定今生的命运。", "explanation": "这里应该用〈前世〉。“来生”在今生之后，不能决定今生，应说“前世的行为决定今生”。"}, {"text": "我来生曾经在寺里修行。", "explanation": "这里应该用〈过去〉。“来生”是未来的一辈子，不能与“曾经”的过去经历搭配。"}, {"text": "来生是奶奶的生日。", "explanation": "这里应该用〈今天〉。“来生”不是某个具体的日子，不能用来说生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：“人死以后还有昨天”前后矛盾，昨天是已经过去的日子。"}, {"text": "来生", "is_correct": true, "explanation": "正确：“他们相信人死以后还有来生”表示死后轮回的下一辈子，符合句意。"}, {"text": "眼前", "is_correct": false, "explanation": "搭配：“人死以后还有眼前”不成搭配，与“死后”的语境不符。"}, {"text": "今晚", "is_correct": false, "explanation": "语义：“人死以后还有今晚”矛盾，今晚指眼前这一夜，不能指死后。"}], "explanations": {"昨天": "语义：“人死以后还有昨天”前后矛盾，昨天是已经过去的日子。", "来生": "正确：“他们相信人死以后还有来生”表示死后轮回的下一辈子，符合句意。", "眼前": "搭配：“人死以后还有眼前”不成搭配，与“死后”的语境不符。", "今晚": "语义：“人死以后还有今晚”矛盾，今晚指眼前这一夜，不能指死后。"}, "sentence_index": 6, "correct_answer": "来生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在我们先吃饭，来生再去寺里。", "explanation": "这里应该用〈稍后〉。“来生”指死后的下一辈子，不能与“现在先吃饭”这种眼前安排接在一起。"}, {"text": "他打算和来生结婚。", "explanation": "这里应该用〈对象〉。“来生”指死后的下一辈子，是一段时间，不能作结婚的对象。"}, {"text": "来生我们搬了家。", "explanation": "这里应该用〈去年〉。“来生”是未来的一辈子，不能与已经发生的搬家搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我相信一个来生会更好。", "corrected_sentence": "我相信来生会更好。", "error_description": "“来生”是泛指的未来时间，前面不能加数量词“一个”，应说“来生”，“一个来生”不成说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶常为来生的念经。", "corrected_sentence": "奶奶常为来生念经。", "error_description": "错误：「来生」后面多加了「的」。「为来生念经」中「来生」直接作「为」的宾语，后面没有中心语，不能加「的」，应说「奶奶常为来生念经」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f09f49-0ff2-44db-a811-9cc478b266a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
