INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95953, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先把东西存放起来，留到以后需要时使用。", "primary_collocate": null, "pronunciation": "chǔ bèi", "ipa": "ʈʂʰu˨˩ pei˥˩", "syllable_count": 2, "sentences": [{"text": "停电以前，我们先储备一些蜡烛。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家里储备了很多大米。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在家里储备一些零食。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷了，松鼠开始储备食物。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里储备着很多水果。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风要来了，大家都在储备饮用水。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的商店冬天要储备更多的盐。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了过冬，他们储备了不少煤。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家里储备着一些常用药。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，这里储备的帐篷很快用完了。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "储备了", "label": "完成体"}, {"form": "储备着", "label": "持续体"}, {"form": "储备过", "label": "经历体"}, {"form": "储备粮", "label": "复合词"}], "register": "中性", "sense_fingerprint": "先把东西存起来，以后需要时再用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95953, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "储备", "is_correct": true, "explanation": "正确：“储备”指先存起来，以后用得着，与“停电以前”的语境相合。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”是使火熄掉，与为以后用而预先存放的意思相反。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”多用于衣物、画等，不说“挂蜡烛”。"}, {"text": "砸碎", "is_correct": false, "explanation": "语义：“砸碎”是毁坏东西，与为以后使用而存放的意思不合。"}], "explanations": {"储备": "正确：“储备”指先存起来，以后用得着，与“停电以前”的语境相合。", "熄灭": "语义：“熄灭”是使火熄掉，与为以后用而预先存放的意思相反。", "挂": "搭配：“挂”多用于衣物、画等，不说“挂蜡烛”。", "砸碎": "语义：“砸碎”是毁坏东西，与为以后使用而存放的意思不合。"}, "sentence_index": 0, "correct_answer": "储备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人喜欢储备旧钟表。", "explanation": "这里应该用〈收集〉。储备指为日后需要而存放，爱好性的搜罗保存要用“收集”。"}, {"text": "我们晚上储备了一顿饭。", "explanation": "这里应该用〈准备〉。储备的是日后要用的物资，为眼前要吃的饭做的预备要用“准备”。"}, {"text": "孩子把压岁钱储备在银行里。", "explanation": "这里应该用〈储蓄〉。存入银行的个人钱款叫储蓄，储备多指物资、人才或外汇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "储备", "is_correct": true, "explanation": "正确：“储备”指为以后需要而预先存放，与“冬天要”的语境相合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”多用于果实、花叶，不用于盐。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”是用牙嚼碎食物，与商店储货的意思不合。"}, {"text": "吃光", "is_correct": false, "explanation": "语义：“吃光”是把东西全部吃完，与“冬天要储备更多”的意思相反。"}], "explanations": {"储备": "正确：“储备”指为以后需要而预先存放，与“冬天要”的语境相合。", "摘": "搭配：“摘”多用于果实、花叶，不用于盐。", "咀嚼": "语义：“咀嚼”是用牙嚼碎食物，与商店储货的意思不合。", "吃光": "语义：“吃光”是把东西全部吃完，与“冬天要储备更多”的意思相反。"}, "sentence_index": 6, "correct_answer": "储备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同要储备十年。", "explanation": "这里应该用〈保存〉。合同是需要妥善保管的文件，应说“保存十年”；“储备”指为以后使用而存放物资。"}, {"text": "我们提前储备了两张电影票。", "explanation": "这里应该用〈预订〉。订票要用“预订”，“储备”指为以后需要而存放物资。"}, {"text": "他把旧书储备给了学校。", "explanation": "这里应该用〈捐赠〉。储备指把物资积存起来、以备需要时使用，并不表示把东西无偿交给别人；送给学校要用“捐赠”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬天快到了，村民们先储备来一些木柴。", "corrected_sentence": "冬天快到了，村民们先储备好一些木柴。", "error_description": "补语错误：结果补语应为“好”，“来”不能作“储备”的结果补语，应为“先储备好一些木柴”，不能说“先储备来一些木柴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市在台风前没有储备了很多饮用水。", "corrected_sentence": "这家超市在台风前没有储备很多饮用水。", "error_description": "体标错误：“没有”否定的动作后面不加“了”，应为“没有储备很多饮用水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
