INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95954, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把物资、人才等积存起来，以备需要时使用。", "primary_collocate": null, "pronunciation": "chǔ bèi", "ipa": "ʈʂʰu˨˩ pei˥˩", "syllable_count": 2, "sentences": [{"text": "冬天以前，农民要储备足够的粮食。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司一直在储备优秀的人才。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市储备了很多石油。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要储备一些药品，以防万一。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库储备了足够全城用的盐。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要提前储备水和食物。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院储备着大量的血液。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想储备更多年轻的老师。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的人们在雪季前储备木柴。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把一部分粮食储备在仓库里。", "target_word": "储备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "储备了", "label": "完成体"}, {"form": "储备着", "label": "持续体"}, {"form": "储备过", "label": "经历体"}, {"form": "储备粮", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把物资、人才等先积存起来，以备日后需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "储备", "is_correct": true, "explanation": "正确：“储备”指预先存起来以备需要，与“冬天以前”的语境相合。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是暗中拿走别人的东西，与农民自己备粮的意思不合。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”是无益地用掉，与“冬天以前”为将来做准备的意思相反。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”多用于杯碗等易碎物，不说“摔粮食”。"}], "explanations": {"储备": "正确：“储备”指预先存起来以备需要，与“冬天以前”的语境相合。", "偷": "语义：“偷”是暗中拿走别人的东西，与农民自己备粮的意思不合。", "浪费": "语义：“浪费”是无益地用掉，与“冬天以前”为将来做准备的意思相反。", "摔": "搭配：“摔”多用于杯碗等易碎物，不说“摔粮食”。"}, "sentence_index": 0, "correct_answer": "储备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喜欢储备邮票。", "explanation": "这里应该用〈收藏〉。储备指为日后需要而预先存放物资或人才，爱好性的保存要用“收藏”。"}, {"text": "周末我储备了一个生日蛋糕。", "explanation": "这里应该用〈准备〉。储备指为以后需要而事先存放，为某次活动做的预备要用“准备”。"}, {"text": "他每个月在银行储备一部分工资。", "explanation": "这里应该用〈储蓄〉。存入银行的个人存款叫储蓄，储备多用于物资、人才或外汇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "储备", "is_correct": true, "explanation": "正确：“储备”指为以后使用而存放，与医院备血的语境相合。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能用于血液。"}, {"text": "饮用", "is_correct": false, "explanation": "语义：“饮用”指喝，与“存放血液”的意思不合。"}, {"text": "灌溉", "is_correct": false, "explanation": "搭配：“灌溉”用于田地和植物，不说“灌溉血液”。"}], "explanations": {"储备": "正确：“储备”指为以后使用而存放，与医院备血的语境相合。", "种植": "搭配：“种植”的对象是植物，不能用于血液。", "饮用": "语义：“饮用”指喝，与“存放血液”的意思不合。", "灌溉": "搭配：“灌溉”用于田地和植物，不说“灌溉血液”。"}, "sentence_index": 6, "correct_answer": "储备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些旧照片要储备好。", "explanation": "这里应该用〈保存〉。储备指为日后需要而存放物资或人才，保护照片要用“保存”。"}, {"text": "我们提前储备了两张车票。", "explanation": "这里应该用〈预订〉。储备的对象是物资或人才，订车票要用“预订”。"}, {"text": "他把一本书储备给了朋友。", "explanation": "这里应该用〈赠送〉。储备指把物资积存起来、以备需要时使用，并不表示把东西交给别人；送人要用“赠送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在储备了大量沙袋。", "corrected_sentence": "政府正在储备大量沙袋。", "error_description": "体标错误：“正在”表示动作进行，不能与“了”同用，应为“正在储备大量沙袋”，不能说“正在储备了大量沙袋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府把大量大米储备来起。", "corrected_sentence": "政府把大量大米储备起来。", "error_description": "补语错误：趋向补语“起来”是固定搭配，应为“把大量大米储备起来”，不能说“储备来起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
